-- Guide texts (zhCN) for the Polestar_Guides_Horde pack.
-- Includes the official Polestar_zhCN texts (they win) and fills every gap,
-- so the addon stays complete whatever order the addons load in.

local _, E = ...
if not (GetLocale and GetLocale() == "zhCN") then return end
if not E.enabled then return end

local G = E.guides

-- Format:
--

G["forever/class/hunter/taming-the-beast-horde"] = {
	["Adult Plainstrider"] = "成年平原陆行鸟",
	["Adult Plainstriders (level 6-7) walk the plains south-west and north-west of {area:222}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). A plainstrider flees at 25% health, so do not damage it first. Keep each rod: it goes back to Yaw."] = "成年平原陆行鸟（6-7级）在{area:222}西南和西北的平原上活动。魔杖用法：选中一只活着的野兽，使用{item:15908}，在整个引导期间站着不动、任由它攻击你；移动、还手或他人帮忙都会中断，并消耗魔杖少量充能之一（充能耗尽：摧毁魔杖，放弃任务，再接一次）。平原陆行鸟血量到25%会逃跑，所以不要先伤它。每根魔杖都留着：要还给Yaw。",
	["Armored Scorpid"] = "装甲蝎",
	["At 10 go to {npc:3065}, who stands at the north edge of {area:222}. The Hunter's Path from {npc:3038} in {zone:1456}, {npc:3407} in {zone:1454} or {npc:3171} in {area:362} also leads here, for a little experience; it is only a pointer."] = "10级时去找{npc:3065}，他站在{area:222}北缘。来自{zone:1456}的{npc:3038}、{zone:1454}的{npc:3407}或{area:362}的{npc:3171}的“猎手之路”也会指引到这里，可得到少量经验；它只是指路任务。",
	["At 10 go to {npc:3171}, the hunter trainer inside the barracks in {area:362}. If {npc:3407} in {zone:1454}, {npc:11814} in {area:367} or {npc:3038} in {zone:1456} hands you The Hunter's Path, take it and hand it to {npc:3171} for a little experience; it is only a pointer, and you can take the first rod without it."] = "10级时去找{area:362}兵营里的猎人训练师{npc:3171}。如果{zone:1454}的{npc:3407}、{area:367}的{npc:11814}或{zone:1456}的{npc:3038}交给你“猎手之路”，就接取并交给{npc:3171}，可得少量经验；它只是指路任务，没有它也能拿第一根魔杖。",
	["At 10, {npc:254084}, a hunter trainer on {zone:2521}, may send you on to {area:16638} with {quest:94007}. It is only a pointer: skip it if you are already in {area:16638}."] = "10级时，{zone:2521}上的猎人训练师{npc:254084}可能会用{quest:94007}派你前往{area:16638}。这只是指路任务：如果你已经在{area:16638}，就跳过它。",
	["Dire Mottled Boar"] = "凶恶斑纹野猪",
	["Dire Mottled Boars (level 6-7) roam just north and west of {area:362}. How the rod works: target a living beast, use the {item:15908} from inside its range and stand still for the whole channel while the beast hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from {npc:3171}. The boars charge from 20 yards, so start with the rod, not {spell:75}. The tamed boar becomes your pet for practice. Keep each rod: it goes back to {npc:3171}."] = "凶恶斑纹野猪（6-7级）就在{area:362}北面和西面游荡。魔杖用法：选中一只活着的野兽，在它的范围内使用{item:15908}，在整个引导期间站着不动、任由野兽攻击你。移动、还手、他人治疗或任何人攻击该野兽都会中断，并消耗魔杖少量充能之一；若充能耗尽，就摧毁魔杖、放弃任务并回去找{npc:3171}再接。野猪会从20码外冲锋，所以先用魔杖，别用{spell:75}。驯服的野猪会成为你的练习宠物。每根魔杖都留着：要还给{npc:3171}。",
	["Dismiss the crawler first (right-click the pet portrait, {spell:2641}). Ornery Galestriders graze in the {area:16626}, the fields a short walk west and south-west of {area:16638}."] = "先解散爬行者（右键点击宠物头像，{spell:2641}）。暴躁风行者（Ornery Galestrider）在{area:16626}吃草，那片田野就在{area:16638}西面和西南面不远处。",
	["Dismiss the crawler. Armored Scorpids (level 7-8) crawl the dry plains west and south-west of {area:362}, some just south of the road west out of town; {spell:1494} shows them. Their hits can break the channel: start at full health and keep still."] = "解散爬行者。装甲蝎（7-8级）在{area:362}西面和西南面的干燥平原上爬行，有些就在出镇西行道路的南侧；{spell:1494}能显示它们。它们的攻击会打断引导：满血开始并保持不动。",
	["Dismiss the galestrider. Vuldren Alphas hunt in the same {area:16626}, a little further south."] = "解散风行者。乌尔德伦首领在同一片{area:16626}狩猎，位置稍偏南。",
	["Dismiss the plainstrider first (right-click the pet portrait, {spell:2641}): a released practice pet may attack you. Prairie Stalkers (level 7-8) roam the grass north of {area:222}."] = "先解散平原陆行鸟（右键点击宠物头像，{spell:2641}）：放生的练习宠物可能会攻击你。草原潜伏者（7-8级）在{area:222}北面的草地上游荡。",
	["Dismiss the stalker. Swoops (level 7-9) glide over the plains north-west and north-east of Bloodhoof; the Taloned Swoops do not count. A {npc:2970}'s knockdown breaks the channel, but it lands only once per channel: start the rod just after it has used it."] = "解散潜伏者。俯冲者（7-9级）在血蹄村西北和东北的平原上空滑翔；利爪俯冲者不算。{npc:2970}的击倒会打断引导，但每次引导只会命中一次：在它用过击倒之后再开始用魔杖。",
	["First dismiss the boar (right-click your pet's portrait, {spell:2641}): a released practice pet can turn on you. Surf Crawlers (level 7-8) walk the beaches around {area:367} and the {area:368}; the small Pygmy Surf Crawlers do not count. A crawler runs for help at 15% health, so do not hurt it."] = "先解散野猪（右键点击宠物头像，{spell:2641}）：放生的练习宠物可能会反咬你。海滨爬行者（7-8级）在{area:367}和{area:368}周围的海滩上活动；小型的迷你海滨爬行者不算。爬行者血量到15%会跑去求援，所以别伤它。",
	["Follow the road north to {zone:1454}'s gate. {npc:3352} stands with the hunter trainers in the {object:172958}, up the ramp at the city's east side; {npc:10088}, the pet trainer, is a few steps north of him."] = "沿道路向北到{zone:1454}的城门。{npc:3352}和猎人训练师们一起待在{object:172958}里，从城市东侧的坡道上去；宠物训练师{npc:10088}就在他北边几步远。",
	["Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away."] = "快乐值：宠物框上的表情。不快乐的宠物只能造成四分之三的伤害，快乐的则多四分之一。快乐值会缓慢下降，宠物死亡时下降更快；宠物不快乐太久可能会跑掉。",
	["Head north to {zone:1456} and take a lift up. {npc:3039} stands with the hunter trainers on {area:1641}; {npc:10086}, the pet trainer, is nearby."] = "向北到{zone:1456}，乘升降梯上去。{npc:3039}和猎人训练师们在{area:1641}；宠物训练师{npc:10086}就在附近。",
	["Hunter"] = "猎人",
	["Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in {spell:5149} (pet level times loyalty rank minus one)."] = "忠诚度随时间与击杀增长。每提升一级忠诚度都会提高你在{spell:5149}中可用的训练点数（宠物等级乘以忠诚等级再减一）。",
	["Near Bloodhoof: Flatland Prowlers (cats, level 9) and Prairie Wolf Alphas (wolves, 9-10) roam the plains of northern {zone:1412}; at 11-12, Savannah Huntresses (cats) prowl around the {area:380} in the {zone:1413}."] = "血蹄村附近：平原徘徊者（猫科，9级）和草原狼首领（狼，9-10级）在{zone:1412}北部的平原上游荡；11-12级时，草原雌猎手（猫科）在{zone:1413}的{area:380}一带徘徊。",
	["Near {area:16638}: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the {area:16626}; Shriekling Matriarchs (raptors, level 9) nest just west of {area:16638}; Shadowgale Urseras (bears, 10-11) roam the north of {zone:2521}."] = "{area:16638}附近：乌尔德伦首领（10级，也就是你最后一次练习驯服的野兽）在{area:16626}狩猎；尖啸迅猛龙族长（迅猛龙，9级）在{area:16638}以西筑巢；暗风乌瑟拉斯（熊，10-11级）在{zone:2521}北部游荡。",
	["Near {area:362}: Durotar Tigers (cats, level 7-8) roam the south of {zone:1411}, from {area:367} down the coast; Venomtail Scorpids (9-10) the north-west toward {zone:1454}; at 11-12, Savannah Huntresses (cats) prowl the plains around the {area:380} in the {zone:1413}."] = "{area:362}附近：杜隆塔尔虎（猫科，7-8级）在{zone:1411}南部、从{area:367}沿海岸一带游荡；毒尾蝎（9-10级）在西北靠{zone:1454}的方向；11-12级时，草原雌猎手（猫科）在{zone:1413}的{area:380}周围的平原徘徊。",
	["Ornery Galestrider"] = "暴躁风行者",
	["Pet trainers sell {spell:1853} ranks and resistances. Horde: Harruk in {area:362}, {npc:3688} at Bloodhoof, {npc:10088} in {zone:1454}'s {object:172958}, {npc:10086} on {zone:1456}'s {area:1641}, {npc:254411} in {area:16638}, later Grokor in {area:75} and Zudd at {object:3202}."] = "宠物训练师出售{spell:1853}的各级和抗性。部落：{area:362}的哈鲁克、血蹄村的{npc:3688}、{zone:1454}的{object:172958}里的{npc:10088}、{zone:1456}的{area:1641}上的{npc:10086}、{area:16638}的{npc:254411}，之后还有{area:75}的格罗科尔和{object:3202}的祖德。",
	["Prairie Stalker"] = "草原潜伏者",
	["Surf Crawler"] = "海滨爬行者",
	["Swoop"] = "俯冲者",
	["Tame a beast of your level to keep"] = "驯服一只与你等级相当的野兽作为永久宠物",
	["Tame {npc:250874}"] = "驯服{npc:250874}",
	["Tame {npc:251707}"] = "驯服{npc:251707}",
	["Tame {npc:254588}"] = "驯服{npc:254588}",
	["Use the {item:15908} on a living alpha"] = "对活着的首领使用{item:15908}",
	["Use the {item:15908} on a living boar"] = "对活着的野猪使用{item:15908}",
	["Use the {item:15908} on a living crawler"] = "对活着的爬行者使用{item:15908}",
	["Use the {item:15908} on a living galestrider"] = "对活着的风行者使用{item:15908}",
	["Use the {item:15908} on a living plainstrider"] = "对活着的平原陆行鸟使用{item:15908}",
	["Use the {item:15908} on a living scorpid"] = "对活着的蝎子使用{item:15908}",
	["Use the {item:15908} on a living stalker"] = "对活着的潜伏者使用{item:15908}",
	["Use the {item:15908} on a living {npc:2970}"] = "对活着的{npc:2970}使用{item:15908}",
	["Use the {item:15908} on a living {npc:3107}"] = "对活着的{npc:3107}使用{item:15908}",
	["Vuldren Alpha"] = "乌尔德伦首领",
	["Windsong Crawler"] = "鸣风爬行者",
	["Windsong Crawlers live only by water: the nearest scuttle along the shore south-west of {area:16638}, among the crabs. How the rod works: target a living crawler, use the {item:15908} and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs a charge. Killing one does not count."] = "鸣风爬行者只生活在有水的地方：最近的一群在{area:16638}西南面的岸边，混在螃蟹之间。魔杖用法：选中一只活着的爬行者，使用{item:15908}，在整个引导期间站着不动、任由它攻击你；移动、还手或他人帮忙都会中断并消耗一次充能。杀死它不算数。",
	["Your first pet"] = "你的第一只宠物",
	["Your own pet at 10: three practice tames with a {item:15908} teach {spell:1515}, then {spell:5149}."] = "10级时的正式宠物：用{item:15908}完成三次练习驯服后，就学会{spell:1515}，然后是{spell:5149}。",
	["{npc:252389} in {area:16638}"] = "{npc:252389}，在{area:16638}",
	["{npc:252389} stands with the trainers by {area:16638}'s west gate, {npc:254411} beside her."] = "{npc:252389}和训练师们一起站在{area:16638}西门旁，{npc:254411}就在她身边。",
	["{npc:252389}: the first {item:15908}"] = "{npc:252389}：第一根{item:15908}",
	["{npc:254411}, beside her: {spell:5149}"] = "她身边的{npc:254411}：{spell:5149}",
	["{npc:3039} in {zone:1456}"] = "{npc:3039}，在{zone:1456}",
	["{npc:3065} at Bloodhoof"] = "{npc:3065}，在血蹄村",
	["{npc:3065}: the first {item:15908}"] = "{npc:3065}：第一根{item:15908}",
	["{npc:3171} in {area:362}"] = "{npc:3171}，在{area:362}",
	["{npc:3171}: the first {item:15908}"] = "{npc:3171}：第一根{item:15908}",
	["{npc:3352} in {zone:1454}"] = "{npc:3352}，在{zone:1454}",
	["{quest:6061} (Horde)"] = "{quest:6061}（部落）",
	["{spell:1515} works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and {spell:17253}) and a boar takes more punishment."] = "{spell:1515}的用法和魔杖一样：目标须是与你同级或更低级的野兽，引导期间不能移动，野兽会一直攻击你。宠物会保持你驯服它时的等级，并随你一起升级；它永远不会高于你的等级，所以抓一只等级接近你的。在Forever上每个科系都有自己的技能（比如野猪的冲锋）。练级时，猫科伤害最高（爪击与{spell:17253}），野猪则更耐打。",
	["{spell:1584}: open your spellbook, cast {spell:1584} and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Grimtak the butcher and {npc:6928} in {area:362} sell meat, {npc:3025} in {zone:1456} and the innkeepers on {zone:2521} too; Bloodhoof's innkeeper and bakers sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat."] = "{spell:1584}：打开法术书，施放{spell:1584}，然后点击一份你宠物科系会吃的食物（宠物提示里会列出：猫科吃肉和鱼，野猪几乎什么都吃）。从野兽身上拾取的生肉也算。购买：{area:362}的屠夫格里姆塔克和{npc:6928}卖肉，{zone:1456}的{npc:3025}以及{zone:2521}的旅店老板也卖；血蹄村的旅店老板和面包师卖面包。食物等级接近宠物等级时它最快乐；食物低太多只能得到大约一半效果。战斗中不能喂食。",
	["{spell:5149} (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master ({npc:9987} in {area:362}, Seikwa at Bloodhoof, {npc:265756} on {zone:2521}, {npc:9988} in {zone:1454}), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with {spell:5149}. A pet holds four active abilities at most."] = "{spell:5149}（法术书，通用页）会把你已学会的技能教给当前宠物。要学新技能或更高等级：把宠物寄放在兽栏管理员处（{area:362}的{npc:9987}、血蹄村的塞克瓦、{zone:2521}上的{npc:265756}、{zone:1454}的{npc:9988}），驯服一只拥有该技能的野兽（它的宠物法术书页会显示它会什么），在战斗中反复使用该技能直到游戏提示你已学会，然后接回自己的宠物并用{spell:5149}教它。宠物最多同时拥有四个主动技能。",
	["{spell:883}, {spell:2641} and {spell:982} are in your spellbook now; {spell:136} comes from your trainer at 12. A dead pet needs {spell:982}; one that is away more than about 100 yards is dismissed and comes back with {spell:883}."] = "{spell:883}、{spell:2641}和{spell:982}现在已在你的法术书里；{spell:136}会在12级时由训练师教你。死掉的宠物需要{spell:982}；离你超过约100码的宠物会被解散，用{spell:883}召回。",
}

G["forever/class/mage/ju-ju-heaps"] = {
	["A staff or an off-hand orb at 10: Orcs and Trolls on the {area:368}, the Undead at a Tirisfal farm."] = "10级时可选法杖或副手宝珠：兽人和巨魔在{area:368}，亡灵在提瑞斯法的一处农场。",
	["At 10 {npc:2128}, the {area:159} mage trainer upstairs in the {area:2119}, sends you to {npc:4568} in the {zone:1458}. Taking it shuts out {quest:1884}; if {quest:1883} (from {zone:1454} or {zone:1456}) is in your log, abandon it first or {npc:2128} cannot give you this one. (A Troll who took this one in {area:159} follows the Balnir steps; an Undead who took {quest:1884} in Sen'jin, the {area:368} steps.)"] = "10级时，{area:159}的法师训练师{npc:2128}（在{area:2119}楼上）会派你去找{zone:1458}的{npc:4568}。接受此任务会关闭{quest:1884}；若日志里已有{quest:1883}（来自{zone:1454}或{zone:1456}），请先放弃它，否则{npc:2128}无法给你这个任务。（在{area:159}接了此任务的巨魔，走巴尔尼尔那条路线；在森金村接了{quest:1884}的亡灵，走{area:368}路线。）",
	["Back to Anastasia"] = "返回安娜斯塔西娅",
	["Back to Un'thuwa"] = "回到安苏瓦那里",
	["Ley or {item:9514} or Orb (Horde)"] = "Ley法杖或{item:9514}或宝珠（部落）",
	["Mage"] = "法师",
	["The orb is an off-hand for a one-hand weapon; the staff is a two-hander."] = "宝珠是单手武器的副手；法杖是双手武器。",
	["The {quest:1884}"] = "{quest:1884}",
	["Un'thuwa"] = "安苏瓦",
	["Un'thuwa, the troll mage trainer, stands in {area:367} on the {zone:1411} coast south of {area:362}. Orcs coming from {zone:1454} can take {quest:1883} from {npc:7311} in the {object:172961} first; it is only a pointer and Un'thuwa gives {quest:1884} without it. Taking it shuts out the {zone:1458}'s {area:165}."] = "巨魔法师训练师Un'thuwa站在{zone:1411}海岸{area:362}以南的{area:367}。从{zone:1454}来的兽人可先在{object:172961}找{npc:7311}接{quest:1883}；它只是个指引任务，不接Un'thuwa也会给你{quest:1884}。接了它会关闭{zone:1458}的{area:165}。",
	["Un'thuwa: {item:7508} or {item:9513}"] = "Un'thuwa：{item:7508}或{item:9513}",
	["Wade across the shallows south-east of Sen'jin to the main Echo Isle, where Zalazane (level 10) holds his camp with Hexed and Voodoo Trolls (level 8). The heaps you can click are the skull piles inside the raised huts around his camp, one hut holding two, more in the huts to the north; the skulls lying on the ground outside cannot be clicked. Destroy four. There are seven and each comes back 30 seconds after it is destroyed."] = "从森金村向东南涉过浅滩到回音群岛主岛，扎拉赞恩（10级）率被诅咒的巨魔和巫毒巨魔（8级）驻守营地。可点击的堆是营地周围高脚屋里的骷髅堆，一间屋里有两只，北边的屋里更多；散落在外面的骷髅点不了。摧毁四堆。共有七堆，每堆被摧毁后30秒重生。",
	["Walk south from {area:159} to the {area:153} and take the lift down into the {zone:1458}. Anastasia stands in the {object:36082}, the north-east ring of the city."] = "从{area:159}向南走到{area:153}，乘升降梯下到{zone:1458}。安娜斯塔西娅站在{object:36082}，即城东北的环形区。",
	["{npc:4568}: {item:7507} or {item:9514}"] = "{npc:4568}：{item:7507}或{item:9514}",
	["{object:102986}, four of them"] = "{object:102986}，四座",
	["{quest:1882} lies south-east of {area:159}, south of the road east to the {area:152}. The snapdragons grow in the farm's garden and look more like bushes than flowers; any of them will do and you need no {skill:182}. They come back within seconds."] = "{quest:1882}位于{area:159}东南，向东通往{area:152}的道路以南。金鱼草长在农场的园子里，看上去更像灌木而非花；任意一株都行，不需要{skill:182}。它们几秒内就会重生。",
}

G["forever/class/mage/nether-lace-garment"] = {
	["A robe or a tunic for Horde mages in their late 20s."] = "为二十多级的部落法师准备的长袍或外衣。",
	["Back to {npc:5885}"] = "回到{npc:5885}那里",
	["Fly to {area:431} and swim north up the river past the big lake to its far northern end, where the zone text reads {area:429}; satyrs hold the ruins around it and a few river beasts are in the way. Swim right in under the highest waterfall until you touch the rock wall, then use the flask (you can stay in the water). The waterfalls on the western Falfarren fork do not work."] = "飞到{area:431}，沿河向北游过大湖，直到最北端，那里区域文字显示为{area:429}；萨特占据着周围的废墟，路上还有几只河里的野兽。一直游到最高瀑布正下方，直到碰到岩壁，然后使用药瓶（可以一直留在水里）。西侧法尔法伦支流的瀑布无效。",
	["Mage"] = "法师",
	["Take the zeppelin to {zone:1454} (or use {spell:3567}, which lands you on the upper floor of {object:173161}). {npc:5885} stands with the mage trainers on the lower floor of {object:173161} in the {object:172961}. She hands you {item:7269}."] = "乘飞艇到{zone:1454}（或使用{spell:3567}，它会把你传送到{object:173161}的上层）。{npc:5885}和法师训练师们一起待在{object:172961}内{object:173161}的底层。她会交给你{item:7269}。",
	["The {object:174797}"] = "{object:174797}",
	["The {quest:1945}"] = "{quest:1945}",
	["The {quest:1945}, dryads of level 24-25, roam around the {area:426} in central {zone:1440}; every one drops a hair and they come back after 5 minutes. They often resist fire (and some frost and shadow): arcane spells land best. Each runs for help at low health. Keep clear of the guards by the white tower of the retreat, who hit hard."] = "{quest:1945}，24-25级的树妖，在{zone:1440}中部的{area:426}一带游荡；每一只都会掉落一根头发，5分钟后重新出现。它们常抵抗火焰（有些还抵抗冰霜和暗影）：奥术法术命中最好。血量低时它们会跑去求援。远离隐居地白塔旁的卫兵，他们打人很疼。",
	["{item:7269}, under the falls"] = "{item:7269}，在瀑布下",
	["{npc:3484}, a troll tailor, works at the {area:380}. The robe gives intellect, stamina and spirit; the tunic more intellect and stamina but no spirit."] = "巨魔裁缝{npc:3484}在{area:380}工作。长袍提供智力、耐力和精神；外衣提供更多智力和耐力，但没有精神。",
	["{npc:4568} stands in the {zone:1458}'s {object:36082}. Orcs and Trolls use {spell:3563} or take the zeppelin from {zone:1454} to {zone:1420} for her."] = "{npc:4568}站在{zone:1458}的{object:36082}里。兽人和巨魔可以施放{spell:3563}，或从{zone:1454}乘飞艇到{zone:1420}去找她。",
}

G["forever/class/mage/spellfire-robes"] = {
	["A robe at 15 for Horde mages, from the {zone:1458} and {zone:1421}."] = "部落法师15级的长袍，任务在{zone:1458}和{zone:1421}。",
	["Algernon's alchemist shop is in the Apothecarium. Stand on the steps or the bridge outside the shop and read the {item:7308}: up to four invisible Rift Spawns (level 16-17) appear and attack at once, and the city guards do not help. Hit one with a single-target spell and back off over the bridge: the others give up and fade, the one you hit follows. Beat it down on the shop's half of the bridge (past halfway the coffer will not work on it) until it stops fighting and sits stunned under a spiral, use the {item:7247} on it, then click the {item:7292} once it appears on the floor (clicking too early wastes a charge). Three are needed."] = "阿尔杰农的炼金店在药剂师区。站在店外的台阶或桥上，读{item:7308}：最多四只隐形的裂隙生物（16-17级）会同时出现并攻击，城里的守卫不会帮忙。用单体法术打中一只，然后退过桥：其余几只放弃并消散，被你打中的那只会跟过来。在桥的店铺这一半把它打倒（过了桥中点，箱子对它就无效），直到它停止战斗、坐在螺旋法阵下眩晕，对它使用{item:7247}，等{item:7292}出现在地上后点击（点得太早会浪费一次充能）。需要三个。",
	["Back to the {zone:1458}. {npc:4576}, {npc:11048} and {npc:11049} keep the tailor's shop in the {object:36082}. Hand the gems and cloth to {npc:4576} and let the three of them talk for a moment; then take {quest:1962} (Forever's quest data has {npc:11049} offering it; if the \"!\" shows over {npc:4576} instead, take it from him) and hand it to {npc:4576} for the robe."] = "回到{zone:1458}。{npc:4576}、{npc:11048}和{npc:11049}在{object:36082}里经营裁缝店。把宝石和布料交给{npc:4576}，让他们三人交谈片刻；然后接{quest:1962}（Forever的任务数据里由{npc:11049}提供；如果“!”出现在{npc:4576}头上，就改从他那里接取），再把任务交回给{npc:4576}换取法袍。",
	["Back to {npc:4568}"] = "回到{npc:4568}处",
	["Leave the {zone:1458} and follow the road south through {zone:1421}. Every {area:279} human drops a {item:7293} four times in five, and {item:2589} too: the easiest are the Dalaran Apprentices (level 13-14, {spell:116}) on the hills south-east of the {area:228}, either side of the road south; deeper in, the walled town of {area:233} in south-east Silverpine has Watchers (18-19, {spell:134} and {spell:2120}) and Wizards (19-20, {spell:122}) that come back every 4 1/2 minutes and run for help at low health, so pull at the edge. Ten {item:2589} also come from any humanoid or the Undercity Auction House."] = "离开{zone:1458}，沿路向南穿过{zone:1421}。{area:279}的每个人类怪都有五分之四的概率掉落{item:7293}，也会掉{item:2589}：最轻松的是达拉然学徒（13-14级，{spell:116}），在{area:228}东南的山丘上、南边道路两侧；更深处，银松森林东南部有城墙的小镇{area:233}里，有守望者（18-19级，{spell:134}和{spell:2120}）和巫师（19-20级，{spell:122}），它们每4分半钟刷新一次，低血量时会跑去求援，所以要在边缘拉怪。十个{item:2589}也可以从任何人形怪或幽暗城拍卖行获得。",
	["Mage"] = "法师",
	["Rift Spawn"] = "裂隙生物",
	["The alchemist shop"] = "炼金商店",
	["{item:7247}, on the stunned {npc:6492}"] = "{item:7247}，对已眩晕的{npc:6492}使用",
	["{npc:2128} is the {area:159} mage trainer, upstairs in the {area:2119}: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:2128}是{area:159}的法师训练师，在{area:2119}楼上：走里面的楼梯上去，箭头分不清楼层。",
	["{npc:4568} stands in the {object:36082}. The {item:7247} and the {item:7308} lie on the ledge behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them."] = "{npc:4568}站在{object:36082}里。{item:7247}和{item:7308}放在她身后的台子上（被人拿走后5分钟刷新）。两件最后都要交出去，所以留着。",
	["{npc:6492}, down to the stun"] = "{npc:6492}，打到眩晕为止",
	["{npc:7311} is one of {zone:1454}'s mage trainers, in {object:173161} in the {object:172961}. Then take the zeppelin to {zone:1420} from the tower outside {zone:1454}'s main gate."] = "{npc:7311}是{zone:1454}的法师训练师之一，在{object:172961}里的{object:173161}。然后从{zone:1454}正门外的塔楼乘飞艇前往{zone:1420}。",
}

G["forever/class/mage/teleports-horde"] = {
	["At 20 go to {object:173161} in {zone:1454}'s {object:172961}, where the mage trainers live. {npc:5958}, the portal trainer, stands on the upper floor and teaches {spell:3567} for 20 silver. Every teleport burns one {item:17031} (10 silver at any reagent vendor), so carry a few."] = "20级时去{zone:1454}的{object:172961}里的{object:173161}，法师训练师都在那里。传送门训练师{npc:5958}站在上层，以20银教授{spell:3567}。每次传送消耗一个{item:17031}（任何材料商处10银），所以随身带几个。",
	["At 30. {zone:1456} is in {zone:1412}: fly there from {zone:1454} or the {area:380}. {npc:5957}, the portal trainer, stands with the mage trainers on {area:1640} and teaches {spell:3566} for 80 silver."] = "30级时。{zone:1456}位于{zone:1412}内：从{zone:1454}或{area:380}飞过去。传送门训练师{npc:5957}和法师训练师们一起站在{area:1640}上，以80银教授{spell:3566}。",
	["At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one {item:17032} (20 silver at any reagent vendor). {npc:5958} in {object:173161} has {spell:11417}; teleport to the {zone:1458} for {npc:2492}'s {spell:11418}."] = "40级时传送门训练师会教传送门：一道整队都能穿过的门，每个1金50银。每道传送门消耗一个{item:17032}（任何材料商处20银）。{object:173161}里的{npc:5958}有{spell:11417}；先传送到{zone:1458}再找{npc:2492}学{spell:11418}。",
	["At 50 {npc:5957} in {zone:1456} teaches the last one, {spell:11420}, for 3 gold 20 silver. Use your {spell:3566} to get there."] = "50级时，{zone:1456}的{npc:5957}会教最后一个{spell:11420}，3金20银。用你的{spell:3566}过去。",
	["Mage"] = "法师",
	["Portals to {zone:1454} and the {zone:1458}"] = "通往{zone:1454}和{zone:1458}的传送门",
	["Take the zeppelin from the tower outside {zone:1454}'s gate to {zone:1420} and walk into the {zone:1458}. {npc:2492}, the portal trainer, stands in the {object:36082} with the mage trainers: {spell:3563}, 20 silver. {npc:4575} beside him sells the runes."] = "从{zone:1454}城门外的塔乘飞艇到{zone:1420}，再走进{zone:1458}。传送门训练师{npc:2492}和法师训练师们一起待在{object:36082}里：{spell:3563}，20银。他身边的{npc:4575}出售符文。",
	["Teleports and Portals (Horde)"] = "传送与传送门（部落）",
	["Your city teleports at 20 and 30 and the group portals at 40 and 50, from each city's portal trainer."] = "20级和30级学城市传送，40级和50级学组队传送门，都找各城市的传送门训练师。",
	["{item:17031}, 10s each"] = "{item:17031}，每个10银",
	["{item:17032}, 20s each"] = "{item:17032}，每个20银",
}

G["forever/class/paladin/lumina-windsinger"] = {
	["At 18 {npc:246378}, inside {area:16602} on the bluffs north-west of the {area:156}, sends you south to the {area:228} in {zone:1421}."] = "18级时，{area:156}西北峭壁上{area:16602}内的{npc:246378}会派你南下前往{zone:1421}的{area:228}。",
	["At 20 {npc:259620} asks for a blade that can kill {quest:95140}. Talk to {npc:248840} beside her for his Weapon Notes, which list the parts, and keep them: he wants them back with the parts. Three parts, in any order: two from dungeons (a group of five each) and a gem from elite naga outside a third."] = "20级时，{npc:259620}想要一把能杀死{quest:95140}的剑。找她身旁的{npc:248840}领取他的武器笔记，上面列有零件，请保管好：他要和零件一起收回。共三个零件，顺序不限：两个来自副本（各需五人小队），一颗宝石来自第三个副本外的精英纳迦。",
	["Back to the {area:228}"] = "回到{area:228}",
	["Back to {npc:248840} in the {area:228}'s lower part: he hands you the {item:268484}, a two-handed sword."] = "回到{area:228}下层的{npc:248840}处：他交给你{item:268484}，一把双手剑。",
	["Back to {npc:259620} in the {area:228} with the {item:268484} (the quest asks for it): she takes it and blesses it with the magic of her people into {item:267369}."] = "带着{item:268484}回到{area:228}的{npc:259620}处（任务要求如此）：她收下剑，并以族人的魔法祝福成{item:267369}。",
	["Back to {npc:259649} at Zoram'gar: he cleanses the gem. Keep the {item:272448} for {npc:248840}."] = "回到佐拉姆加的{npc:259649}处：他净化宝石。保留{item:272448}交给{npc:248840}。",
	["Bring the lumber, the ingot and the gem to {npc:248840} in the {area:228}. He gives you a {item:268192} for a smith in {area:272}: keep it in your bags."] = "把木材、锭和宝石交给{area:228}的{npc:248840}。他给你一封给{area:272}铁匠的{item:268192}：放在背包里留着。",
	["Equip the {item:268484}. {quest:95140}, the great worgen, roams the woods south of the {area:228} toward the gates of {area:17065}. He is elite (level 25): grouping up is encouraged; one player needed a second, another soloed him at 25. A purple shield guards him until your first swing with the blade lands: a message tells you it broke."] = "装备{item:268484}。大狼人{quest:95140}在{area:228}以南通往{area:17065}大门的树林中游荡。他是精英（25级）：建议组队；有玩家需要第二人帮忙，也有玩家在25级单挑过他。在你用剑第一次命中前，一层紫色护盾保护着他：会有信息提示护盾已破。",
	["Free {npc:248755}"] = "解救{npc:248755}",
	["Goblin Woodcarvers, inside"] = "里面的地精木雕师",
	["Hand in the key first: starting the escort before that gives the key quest no credit. Then open the cage: {npc:248755} walks out through the keep and its courtyard while the gnolls attack, then runs for the dock and makes her own way back to the {area:228}. Stay close and keep her alive; if she dies, take the quest again when she is back in her cage."] = "先交钥匙：在此之前开始护送，钥匙任务将不计进度。然后打开笼子：{npc:248755}会在豺狼人袭击中穿过城堡和庭院，随后奔向码头，自行返回{area:228}。跟紧她，保证她存活；她若死亡，等她回到笼中再接一次任务。",
	["Old Fire-Eye"] = "老火眼",
	["Paladin"] = "圣骑士",
	["The Forsaken paladin's two-handed sword: rescue {quest:91862}, gather three parts, slay {quest:95140}."] = "被遗忘者圣骑士的双手剑：救出{quest:91862}，收集三个零件，杀死{quest:95140}。",
	["The blade is a two-handed sword, and you need the skill to hit a level 25 elite with it. {npc:11870}, the weapon master in the {zone:1458}'s {object:36070}, teaches {spell:202} for a small fee; then swing it on easy mobs until the skill is near its cap (five points per level)."] = "这把剑是双手剑，你需要相应武器技能才能命中25级精英。{zone:1458}的{object:36070}里的武器大师{npc:11870}会以少量费用教授{spell:202}；之后在简单怪物身上反复挥砍，直到技能接近上限（每级5点）。",
	["The naga stand in the flooded ruins and passages around the {area:2797} entrance, just north of Zoram'gar: you do not need to enter the instance (its first naga drop the gem too). Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24) drop the {item:6995}, one in two. All are elite: grouping up is encouraged. Players solo them one at a time, with difficulty; a group of three makes it easy. They heal themselves, run for help at low health, and the Sea Witches cast {spell:122} up close. Some players report no drop while in a raid group."] = "纳迦站在佐拉姆加正北方{area:2797}入口周围被水淹没的废墟和通道里：不必进入副本（副本里第一批纳迦也会掉宝石）。潮汐女祭司（20-21级）、神谕者（21-22级）和海妖（23-24级）掉落{item:6995}，约二分之一。全是精英：建议组队。有玩家逐个单挑，颇有难度；三人小队则很轻松。它们会自我治疗，低血量时逃跑求援，海妖还会近身施放{spell:122}。有玩家反映在团队中不掉落。",
	["The pyre on {area:172}"] = "{area:172}上的火堆",
	["The {item:267361}"] = "{item:267361}",
	["The {item:272448}"] = "{item:272448}",
	["The {item:6995}"] = "{item:6995}",
	["from the {object:566037}"] = "来自{object:566037}",
	["{area:1581} lies under {area:20} in {zone:1436}, Alliance land: a group of five at about 17-24. The way in is the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in Sneed's mast room drop the lumber every time."] = "{area:1581}位于{zone:1436}的{area:20}下方，属联盟领地：约17-24级的五人小队。入口是{area:20}的矿洞。斯尼德桅杆房里的地精木雕师（精英，18-19级）每次都掉木材。",
	["{area:1581}, in the {area:20} mine"] = "{area:1581}，在{area:20}矿洞内",
	["{area:172} lies in the lake north-east of the {area:228}. The gnolls' pyre, with the {object:566037}, is on its shore: click the remains to hand in, and click them again for the next quest. The body is a tauren's, not the elf's."] = "{area:172}位于{area:228}东北的湖中。豺狼人的火葬堆带着{object:566037}，就在岸边：点击遗骸交任务，再点一次接下一个任务。尸体是牛头人的，不是那个精灵的。",
	["{area:236} is the dungeon in south Silverpine, for a group of five in the low to mid 20s. The ingot sits on the table next to {npc:4275} at the very end. A friend's cleared instance works: walk in and run to the table."] = "{area:236}是银松森林南部的副本，适合20级初中期的五人小队。锭放在最深处{npc:4275}旁的桌上。朋友已清过的副本也行：直接走进去跑到桌前。",
	["{item:267361}, on Arugal's table"] = "{item:267361}，在阿鲁高的桌上",
	["{item:267412}, from the Rot Hide gnolls"] = "{item:267412}，来自腐皮豺狼人",
	["{item:267454}: talk to {npc:248840}"] = "{item:267454}：与{npc:248840}交谈",
	["{item:268484} and {item:267369} (Forsaken)"] = "{item:268484}和{item:267369}（被遗忘者）",
	["{npc:248840} stands in the lower part of the {area:228}, below the surface; {npc:259611} keeps watch near the town's entrance."] = "{npc:248840}站在{area:228}的下层，地面之下；{npc:259611}在镇子入口附近放哨。",
	["{npc:259620} waits beside {npc:248840} in the {area:228} (a different {npc:259620} from the one you escorted). For {quest:95034}, click through every line of her story."] = "{npc:259620}在{area:228}的{npc:248840}身旁等候（与你护送的那位{npc:259620}不是同一个）。做{quest:95034}时，把她故事的每一行都点完。",
	["{npc:259620}, the {area:228}"] = "{npc:259620}，{area:228}",
	["{npc:259649} waits at {area:2897} on {zone:1440}'s west coast: from the {zone:1458} take the zeppelin to {zone:1454}, then go north through the {zone:1413} into {zone:1440} and west along the road. Andruk, the outpost's wind rider master, saves you the walk next time. Take {npc:259649}'s quest before you hunt the naga: the Kor Gem only drops while you have it."] = "{npc:259649}在{zone:1440}西海岸的{area:2897}等候：从{zone:1458}乘飞艇到{zone:1454}，再向北穿过{zone:1413}进入{zone:1440}，沿路西行。前哨站的飞行管理员安德鲁克下次能替你省去这段路。猎杀纳迦前先接{npc:259649}的任务：科尔宝石只在你持有任务时掉落。",
	["{npc:3539} gives you {quest:95125}"] = "{npc:3539}给你{quest:95125}",
	["{npc:3539}, the weaponsmith, stands just south of {area:272} in {zone:1424}. Accepting {quest:95125} starts the forging: step back and wait near him until he is done."] = "武器匠{npc:3539}站在{zone:1424}的{area:272}正南。接受{quest:95125}即开始锻造：退后，在他附近等到锻造完成。",
	["{quest:91862} is caged in the basement of {area:235}, at the north end of the isle. The Rot Hide gnolls (level 18-19) fill the keep: they pull in big groups across floors and players report very fast respawns, so clear a path and keep moving. Any of them can carry the {item:267412} (often the first kill); the rare {npc:1944} (22) and Snarlmane (23) can too. If her cage is empty, another player is escorting her: wait for her to come back."] = "{quest:91862}被关在{area:235}地下室的笼子里，位于岛的最北端。腐皮豺狼人（18-19级）遍布城堡：它们会跨楼层拉一大群，玩家反映刷新极快，所以清理出一条路并保持移动。它们任何一个都可能携带{item:267412}（常常是第一个击杀）；稀有的{npc:1944}（22级）和咆哮鬃（23级）也会。若笼子是空的，说明另一名玩家正在护送她：等她回来。",
	["{quest:95140}, with the {item:268484} equipped"] = "{quest:95140}，装备{item:268484}",
}

G["forever/class/paladin/tyrs-watch"] = {
	["At 4 {npc:244808} sends you after a {npc:246143} who fled into the hills west of the church, just south of the bat cave. Talk to her to offer aid: she turns on you, and you have to put her down (level 3, easy)."] = "4级时{npc:244808}让你去追一名{npc:246143}，她逃进了教堂以西的山丘，就在蝙蝠洞南边。与她交谈提出帮助：她会突然翻脸攻击你，你不得不将她击杀（3级，简单）。",
	["At 8 {npc:246152} in {area:159} sends you to the order's keep on the west coast. {quest:91317} in {area:16881} and the crypt under it hit hard at 8-9: come at 10 or later."] = "8级时{area:159}的{npc:246152}派你前往西海岸的骑士团城堡。{area:16881}的{quest:91317}及其下方的地穴在8-9级时很难打：10级或以后再来。",
	["Back to the keep"] = "回到要塞",
	["Back to {area:16602}, across the whole glades: Billmuth downstairs takes the plans, then {npc:246378}, back upstairs in the keep, teaches you {spell:7328}."] = "穿过整片林地回到{area:16602}：楼下的Billmuth收下作战计划，然后回到城堡楼上找{npc:246378}，他会教你{spell:7328}。",
	["Back to {area:16602}. {npc:246378} gives you the {item:6866}; {npc:257655} waits downstairs in the keep. If you lose the symbol, {npc:246378} gives you another."] = "回到{area:16602}。{npc:246378}给你{item:6866}；{npc:257655}在城堡楼下等你。如果弄丢了徽记，{npc:246378}会再给你一个。",
	["Faintly Glowing Bones x6"] = "微光骸骨x6",
	["Follow the road east out of {area:154} to {area:159}. {npc:246152}, the paladin trainer, stands in town; she trains you from here on."] = "沿道路向东出{area:154}前往{area:159}。圣骑士训练师{npc:246152}就在镇中；从现在起由她训练你。",
	["Frightened Paladin"] = "受惊的圣骑士",
	["Heal 5 {npc:259377} with {spell:635}"] = "用{spell:635}治疗5名{npc:259377}",
	["Lumber Piles, in the cellar: the way down is here"] = "木料堆，在地窖里：下去的入口在这里",
	["Paladin"] = "圣骑士",
	["Talk to the {npc:246143}, then defeat her"] = "与{npc:246143}交谈，然后击败她",
	["Tarnished Drudge"] = "锈浊苦工",
	["Tarnished Drudges x8"] = "锈浊苦工x8",
	["Tarnished Zealot"] = "锈浊狂热者",
	["Tarnished Zealots x6"] = "锈浊狂热者x6",
	["The Scarlet Zealots (level 8-9), Friars (9-10) and Tarnished around {area:812} carry the attack plans. They run for help at low health and respawn in five minutes."] = "{area:812}周围的血色狂热者（8-9级）、血色修士（9-10级）和锈浊成员身上带着进攻计划。它们血量低时会逃跑呼救，五分钟后刷新。",
	["The Scarlet attack plans"] = "血色十字军的进攻计划",
	["The Shadowvale Lurchers and Mystics (level 8-10) in the crypt drop the Faintly Glowing Bones: about one in two from Lurchers, more from one kind of Mystic, less from the other."] = "地穴中的影谷蹒跚者和影谷秘法师（8-10级）掉落微光骸骨：蹒跚者大约每两只掉一个，一种秘法师掉得多一些，另一种少一些。",
	["The Vile Fin murlocs (level 9-11) lurk on the bluffs along the road east of the keep and in the camps around the lake to the south-west, on the way down to {area:16881}."] = "邪鳍鱼人（9-11级）潜伏在城堡东边道路旁的峭壁上，以及西南湖边各处的营地里，就在前往{area:16881}的路上。",
	["The cellar is under the village, not on the surface: the way down is inside a burned-out house, where the arrow points. Twelve Lumber Piles (stacked beams) lie in the cellar, each good for one {item:246213}. {npc:260396}, an elite (level 11-13), sits at the far end: leave it alone."] = "地窖在村子地下，不在地表：下去的入口在一座烧毁的房子里，即箭头所指处。十二堆木料堆（堆叠的横梁）放在地窖中，每堆可拿一个{item:246213}。精英怪{npc:260396}（11-13级）守在最里面：别招惹它。",
	["The crypt under {area:16881}"] = "{area:16881}下方的地穴",
	["The {item:286269}, a green crystal, lies on the floor in the left-hand part of the crypt."] = "{item:286269}是一块绿色水晶，就在地穴左半部分的地面上。",
	["The {item:6866}"] = "{item:6866}",
	["Tyr's Watch and {spell:7328} (Forsaken)"] = "提尔守望与{spell:7328}（被遗忘者）",
	["Vile Fin Attacker"] = "邪鳍袭击者",
	["Vile Fin Attackers x8"] = "邪鳍袭击者x8",
	["Vile Fin Seer"] = "邪鳍先知",
	["Vile Fin Seers x8"] = "邪鳍先知x8",
	["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:10181} holds court in the {object:36126}; {npc:257648} begs in the {object:36078}."] = "从{area:159}向南走到{area:153}，再下到{zone:1458}。{npc:10181}在{object:36126}接见臣民；{npc:257648}在{object:36078}乞讨。",
	["{area:16602} stands on the bluffs north-west of the {area:156} (the road west starts near 29,46). {npc:246349} waits at the gate. {npc:246389}, the keep's trainer, and {npc:259190}, its stable master, stand at the forest's edge just south of him. They only have work for you from level 10 and after A Righteous Cause from Leonid at the keep, the end of {npc:267009}'s chain that starts south-east of {area:159}; take their quests when you see them."] = "{area:16602}位于{area:156}西北的峭壁上（向西的路从29,46附近开始）。{npc:246349}在大门等你。城堡的训练师{npc:246389}和兽栏管理员{npc:259190}站在他南边森林的边缘。他们要到10级后、且完成城堡里Leonid的任务“A Righteous Cause”（{npc:267009}任务链的终点，起点在{area:159}东南）后才有工作给你；见到他们的任务就接。",
	["{area:812} is at the far east end of the glades, a long walk. Falgan lies dead among the Scarlet Crusaders there: target his body and use the {item:6866}, then talk to him at once, as he does not stay alive long. If he is already up (another player), just talk to him; if he died again, raise him again."] = "{area:812}在林地最东端，要走很长一段路。Falgan死在那里的血色十字军之中：选中他的尸体使用{item:6866}，然后立刻与他交谈，他活不了多久。如果他已经被复活（其他玩家干的），直接交谈即可；如果他又死了，就再复活一次。",
	["{item:2589} x10"] = "{item:2589}x10",
	["{npc:1569} gives you a {item:282423} after {quest:364}: read it, then bring it to {npc:244808} by the church. He asks you to heal five {npc:259377} lying around {area:154}. {spell:635} hurts a Forsaken paladin a little each time: watch your health."] = "完成{quest:364}后{npc:1569}给你一封{item:282423}：读一下，然后带给教堂旁的{npc:244808}。他要你治疗躺在{area:154}各处的五名{npc:259377}。{spell:635}每次施放都会轻微伤害身为被遗忘者的圣骑士：注意自己的血量。",
	["{npc:246349} gives you a weapon, then sends you round the keep to speak with four of its people: {npc:246389} just south of the gate, {npc:246393} and {npc:246378} inside the keep, and {npc:246394}, the lookout, who walks the road south-east of the keep. Pick the conversation option with each."] = "{npc:246349}给你一件武器，然后让你与城堡的四个人交谈：大门正南的{npc:246389}、城堡内的{npc:246393}和{npc:246378}，以及在城堡东南道路上巡逻的哨兵{npc:246394}。与每人对话时选择对话选项。",
	["{npc:246349}: {item:246164} or {item:246165}"] = "{npc:246349}：{item:246164}或{item:246165}",
	["{npc:246378} hands you {npc:259431}'s head for Sylvanas: keep it in your bags, it is what you hand in."] = "{npc:246378}把{npc:259431}的头颅交给你带给希尔瓦娜斯：放在背包里，这就是你要上交的东西。",
	["{npc:246378} leads the order from inside the keep; {npc:246393} stands beside it. {quest:91317} need level 9."] = "{npc:246378}在城堡内领导骑士团；{npc:246393}站在旁边。{quest:91317}需要9级。",
	["{npc:246378} offers the first Lesson in Divinity at level 12. Bring 10 {item:2589} if you have it: the {zone:1458} asks for it next."] = "12级时{npc:246378}提供第一堂神圣学课程。如果你已有10个{item:2589}就带上：下一步{zone:1458}会用到它。",
	["{npc:246378}, back upstairs: {spell:7328}"] = "{npc:246378}，回到楼上：{spell:7328}",
	["{npc:246389} and {npc:259190}"] = "{npc:246389}和{npc:259190}",
	["{npc:246389} and {npc:259190} wait at the forest's edge south of the gate."] = "{npc:246389}和{npc:259190}在大门南边的森林边缘等你。",
	["{npc:246389}'s bones"] = "{npc:246389}的骸骨",
	["{npc:257648} needs 10 {item:2589}. Humanoids drop it: the Scarlet Zealots and Friars of the glades about three kills in ten. The Undercity Auction House sells it too."] = "{npc:257648}需要10个{item:2589}。人形怪掉落：林地的血色狂热者和血色修士大约每十只掉三个。幽暗城拍卖行也有出售。",
	["{npc:257655}, downstairs"] = "{npc:257655}，在楼下",
	["{npc:259190}'s crystal"] = "{npc:259190}的水晶",
	["{quest:91317} (level 8-9) hold the ruined village of {area:16881} in the {area:16616}, south-west of the keep. Commander {npc:259431} (level 10) stands on the upper floor of a house, with Drudges below him: clear the ground floor first."] = "{quest:91317}（8-9级）占据着城堡西南{area:16616}中已成废墟的{area:16881}村。指挥官{npc:259431}（10级）站在一所房子的二楼，楼下有苦工：先清完一楼。",
	["{spell:7328} to raise fallen allies, plus a weapon and a shield for a new Forsaken paladin."] = "{spell:7328}可复活倒下的盟友，另有一把武器和一面盾牌，给新的被遗忘者圣骑士。",
}

G["forever/class/priest/hex-of-weakness-and-shadowguard"] = {
	["At 10 in the {zone:1458}, {npc:4606}, the priest trainer in the {object:36070}, hands you a {quest:5652} letter for {npc:6018} in {zone:1454} (the zeppelin from the tower outside the {zone:1458})."] = "10级时在{zone:1458}，{object:36070}的牧师训练师{npc:4606}会给你一封{quest:5652}信，让你交给{zone:1454}的{npc:6018}（从{zone:1458}城外的塔楼乘飞艇前往）。",
	["At 10 in {zone:1412}, {npc:11407}, just south-west of {area:222}, hands you a {quest:5652} letter for {npc:6018} in {zone:1454}."] = "10级时在{zone:1412}，{area:222}西南不远处的{npc:11407}会给你一封{quest:5652}信，让你交给{zone:1454}的{npc:6018}。",
	["At 10 in {zone:1456}, {npc:3044}, the priest trainer in the cave under {area:1640}, hands you a {quest:5652} letter for {npc:6018} in {zone:1454}."] = "10级时在{zone:1456}，{area:1640}下方洞穴里的牧师训练师{npc:3044}会给你一封{quest:5652}信，让你交给{zone:1454}的{npc:6018}。",
	["At 10, go to {npc:6018}, the priest trainer in a hut in the {object:172961}, {zone:1454}'s south-west corner: he gives {quest:5652} and takes it back at once. No letter needed."] = "10级时去找{npc:6018}，他是{zone:1454}西南角{object:172961}一间小屋里的牧师训练师：他会发布{quest:5652}并立刻收回，无需信件。",
	["At 10, {npc:3706}, the priest trainer inside the barracks of {area:362} (the first building on the right as you come up the road from the {area:363}), hands you a {quest:5652} letter for {npc:6018} in {zone:1454}. {area:362} is on the road north to the city."] = "10级时，{area:362}兵营（从{area:363}沿路走上来时右手边第一栋建筑）里的牧师训练师{npc:3706}会给你一封{quest:5652}信，让你交给{zone:1454}的{npc:6018}。{area:362}就在向北进城的大路旁。",
	["At 20 in the {zone:1458}, {npc:4606} in the {object:36070} hands you a {quest:5642} letter for {npc:6018} in {zone:1454}."] = "20级时在{zone:1458}，{object:36070}的{npc:4606}会给你一封{quest:5642}信，让你交给{zone:1454}的{npc:6018}。",
	["At 20 in {zone:1456}, {npc:3044} in the cave under {area:1640} hands you a {quest:5642} letter for {npc:6018} in {zone:1454}."] = "20级时在{zone:1456}，{area:1640}下方洞穴里的{npc:3044}会给你一封{quest:5642}信，让你交给{zone:1454}的{npc:6018}。",
	["At 20, {npc:6018} in the {object:172961} teaches {quest:5642} with a quest he gives and takes back at once."] = "20级时，{object:172961}的{npc:6018}会发布一个立刻收回的任务来教你{quest:5642}。",
	["Follow the road north from {area:362} into {zone:1454} and west to the {object:172961}: {npc:6018} takes the letter and teaches {quest:5654}."] = "从{area:362}沿路向北进入{zone:1454}，再向西前往{object:172961}：{npc:6018}收下信件并教你{quest:5654}。",
	["Hand the letter to {npc:6018} in the {object:172961}, {zone:1454} (from {zone:1412}: north through the {zone:1413} and east into {zone:1411}, or fly from {zone:1456} once you know {zone:1454}'s flight path)."] = "把信交给{zone:1454}{object:172961}的{npc:6018}（从{zone:1412}出发：向北穿过{zone:1413}再向东进入{zone:1411}；或开通{zone:1454}航线后从{zone:1456}飞过去）。",
	["Hand the letter to {npc:6018} in the {object:172961}, {zone:1454} (the zeppelin from {zone:1420} lands outside {zone:1454})."] = "把信交给{zone:1454}{object:172961}的{npc:6018}（从{zone:1420}乘飞艇，在{zone:1454}城外降落）。",
	["Priest"] = "牧师",
	["The Troll priest spells: {quest:5652} at 10, {quest:5642} at 20. Free, no objectives."] = "巨魔牧师法术：10级学{quest:5652}，20级学{quest:5642}。免费，无任务目标。",
	["{npc:11407}: take the {quest:5652} letter"] = "{npc:11407}：拿这封{quest:5652}信",
	["{npc:3044}: take his {quest:5642} letter"] = "{npc:3044}：拿他的{quest:5642}信",
	["{npc:3044}: take his {quest:5652} letter"] = "{npc:3044}：拿他的{quest:5652}信",
	["{npc:3706}: take his {quest:5652} letter"] = "{npc:3706}：拿他的{quest:5652}信",
	["{npc:4606}: take her {quest:5642} letter"] = "{npc:4606}：拿她的{quest:5642}信",
	["{npc:4606}: take her {quest:5652} letter"] = "{npc:4606}：拿她的{quest:5652}信",
	["{quest:5642}: {npc:3044}'s letter"] = "{quest:5642}：{npc:3044}的信",
	["{quest:5643}: {npc:4606}'s letter"] = "{quest:5643}：{npc:4606}的信",
	["{quest:5652} and {quest:5642}"] = "{quest:5652}和{quest:5642}",
	["{quest:5654}: {npc:3706}'s letter"] = "{quest:5654}：{npc:3706}的信",
	["{quest:5655}: {npc:11407}'s letter"] = "{quest:5655}：{npc:11407}的信",
	["{quest:5656}: {npc:3044}'s letter"] = "{quest:5656}：{npc:3044}的信",
	["{quest:5657}: {npc:4606}'s letter"] = "{quest:5657}：{npc:4606}的信",
}

G["forever/class/priest/priest-robes-horde"] = {
	["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "5级免费拿一件优秀品质长袍：治疗并加持一名在你第一个镇子附近受伤的卫兵。",
	["At 5, {npc:2123}, the priest trainer in the chapel of {area:154}, sends you to {npc:2129} in {area:159}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "5级时，{area:154}礼拜堂的牧师训练师{npc:2123}派你去{area:159}找{npc:2129}。趁在这里时向他学习{spell:613}（2级）：4级花1银就能学，下一个任务正好需要这个等级。",
	["At 5, {npc:3707}, the priest trainer in the Den in the middle of the {area:363}, sends you to {npc:3706} in {area:362}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "5级时，{area:363}中部兽穴的牧师训练师{npc:3707}派你去{area:362}找{npc:3706}。趁在这里时向他学习{spell:613}（2级）：4级花1银就能学，下一个任务正好需要这个等级。",
	["Back in the {area:362} barracks: {npc:3706} gives you the {item:16606}."] = "回到{area:362}的兵营：{npc:3706}给你{item:16606}。",
	["Back upstairs in the {area:159} inn: Beryl gives you the {item:16607}."] = "回到{area:159}旅店楼上：Beryl给你{item:16607}。",
	["Deathguard Kel"] = "亡灵卫兵凯尔",
	["Follow the road east out of {area:154} to {area:159}. {npc:2129} is upstairs in the inn, {area:2119}."] = "沿道路向东出{area:154}前往{area:159}。{npc:2129}在旅店{area:2119}的楼上。",
	["Follow the road out of the {area:363} north-east to {area:362}. {npc:3706} is inside the barracks, the first building on the right as you come into town."] = "沿道路从{area:363}向东北前往{area:362}。{npc:3706}在兵营里，即进城后右手边第一座建筑。",
	["Grunt Kor'ja"] = "步兵科尔加",
	["Heal and fortify {npc:12428}"] = "治疗并坚韧{npc:12428}",
	["Heal and fortify {npc:12430}"] = "治疗并坚韧{npc:12430}",
	["Priest"] = "牧师",
	["Priest Robes at 5 (Horde)"] = "5级牧师长袍（部落）",
	["{npc:12428} kneels, half-dead, beside the north gate of {area:159}'s graveyard, a short walk north of the inn. Cast {spell:613} (Rank 2) on him first, then {spell:1243}: Fortitude first does not count, nor does Rank 1 of {spell:613}. If an addon gets in the way, cast both from the spellbook."] = "{npc:12428}半死不活地跪在{area:159}墓地北门旁，就在旅店北面不远处。先对他施放{spell:613}（2级），再施放{spell:1243}：先加韧不算数，{spell:613}的1级也不算。如果插件干扰，就从法术书里施放这两个法术。",
	["{npc:12430} kneels behind a group of rocks just off the road, a short walk south of {area:362}. Cast {spell:613} (Rank 2) on her first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook. She leaves once both land and is back in about 5 minutes."] = "{npc:12430}跪在路边的一堆岩石后面，就在{area:362}南边不远处。先对她施放{spell:613}（2级），再施放{spell:1243}。{spell:613}的1级不算数；从法术书里把2级拖到动作条上。两个法术都命中后她就离开，大约5分钟后回来。",
	["{spell:613} (Rank 2), if Duesten did not teach it yet"] = "{spell:613}（2级），如果Duesten还没教你",
	["{spell:613} (Rank 2), if {npc:3707} did not teach it yet"] = "{spell:613}（2级），如果{npc:3707}还没教你",
}

G["forever/class/priest/touch-of-weakness-and-dark-sacrifice"] = {
	["At 10 in {zone:1411}, {npc:3706}, the priest trainer inside the barracks of {area:362}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "10级时在{zone:1411}，{area:362}兵营里的牧师训练师{npc:3706}交给你一封{spell:2652}的信件，要你带给{zone:1458}的{npc:4606}。",
	["At 10 in {zone:1412}, {npc:11407}, just south-west of {area:222}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "10级时在{zone:1412}，{area:222}西南方的{npc:11407}交给你一封{spell:2652}的信件，要你带给{zone:1458}的{npc:4606}。",
	["At 10 in {zone:1454}, {npc:6018} in the {object:172961} hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}. The zeppelin to {zone:1420} leaves from the tower outside {zone:1454}'s front gate."] = "10级时在{zone:1454}，{object:172961}里的{npc:6018}交给你一封{spell:2652}的信件，要你带给{zone:1458}的{npc:4606}。前往{zone:1420}的飞艇从{zone:1454}正门外的塔楼出发。",
	["At 10 in {zone:1456}, {npc:3044}, the priest trainer in the cave under {area:1640}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "10级时在{zone:1456}，{area:1640}下方洞穴里的牧师训练师{npc:3044}交给你一封{spell:2652}的信件，要你带给{zone:1458}的{npc:4606}。",
	["At 10, go to {npc:4606}, the priest trainer in the {zone:1458}'s {object:36070}: she gives {quest:5658} and takes it back at once. No letter needed. From {area:159}, follow the road south to the ruined city of Lordaeron; the {zone:1458}'s lifts are at the back of the throne room. {quest:5658} strikes the next melee attacker for Shadow damage and lowers its melee attack power for 2 minutes."] = "10级时去找{zone:1458}{object:36070}的牧师训练师{npc:4606}：她会给你{quest:5658}并立刻收回，不需要信件。从{area:159}沿路向南走到洛丹伦废墟；{zone:1458}的升降梯在王座厅后面。{quest:5658}会对下一个近战攻击者造成暗影伤害，并使其近战攻击强度降低，持续2分钟。",
	["At 20 in {zone:1454}, {npc:6018} in the {object:172961} hands you a {quest:5644} letter for {npc:4606} in the {zone:1458}."] = "20级时在{zone:1454}，{object:172961}里的{npc:6018}交给你一封{quest:5644}的信件，要你带给{zone:1458}的{npc:4606}。",
	["At 20 in {zone:1456}, {npc:3044} in the cave under {area:1640} hands you a {quest:5644} letter for {npc:4606} in the {zone:1458}."] = "20级时在{zone:1456}，{area:1640}下方洞穴里的{npc:3044}交给你一封{quest:5644}的信件，要你带给{zone:1458}的{npc:4606}。",
	["At 20, {npc:4606} in the {object:36070} teaches {quest:5644} with a quest she gives and takes back at once (its text still speaks of {spell:2944}, which every priest now learns from the trainer)."] = "20级时，{object:36070}的{npc:4606}用一个她给出后立刻收回的任务教你{quest:5644}（任务文本里仍提到{spell:2944}，但现在每个牧师都能直接从训练师处学习）。",
	["Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: the zeppelin from the tower outside {zone:1454} lands in {zone:1420}, a short walk from the {zone:1458}."] = "把信交给{zone:1458}{object:36070}的{npc:4606}：从{zone:1454}城外塔楼出发的飞艇在{zone:1420}降落，步行一小段就到{zone:1458}。",
	["Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: the zeppelin from the tower outside {zone:1454} lands in {zone:1420}."] = "把信交给{zone:1458}{object:36070}的{npc:4606}：从{zone:1454}城外塔楼出发的飞艇在{zone:1420}降落。",
	["Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: travel to {zone:1454} and take the zeppelin to {zone:1420}."] = "把信交给{zone:1458}{object:36070}的{npc:4606}：前往{zone:1454}乘飞艇去{zone:1420}。",
	["Priest"] = "牧师",
	["The Undead priest spells: {spell:2652} at 10, {quest:5644} (new in Forever) at 20. Free, no objectives."] = "亡灵牧师法术：10级学{spell:2652}，20级学{quest:5644}（Forever新增）。免费，无任务目标。",
	["{npc:11407}: take the {spell:2652} letter"] = "{npc:11407}：接过{spell:2652}的信件",
	["{npc:3044}: take his {quest:5644} letter"] = "{npc:3044}：接过他的{quest:5644}信件",
	["{npc:3044}: take his {spell:2652} letter"] = "{npc:3044}：接过他的{spell:2652}信件",
	["{npc:3706}: take his {spell:2652} letter"] = "{npc:3706}：接过他的{spell:2652}信件",
	["{npc:6018}: take his {quest:5644} letter"] = "{npc:6018}：接过他的{quest:5644}信件",
	["{npc:6018}: take his {spell:2652} letter"] = "{npc:6018}：接过他的{spell:2652}信件",
	["{quest:5644}: {npc:3044}'s letter"] = "{quest:5644}：{npc:3044}的信件",
	["{quest:5646}: {npc:6018}'s letter"] = "{quest:5646}：{npc:6018}的信件",
	["{quest:5660}: {npc:3706}'s letter"] = "{quest:5660}：{npc:3706}的信件",
	["{quest:5661}: {npc:11407}'s letter"] = "{quest:5661}：{npc:11407}的信件",
	["{quest:5662}: {npc:6018}'s letter"] = "{quest:5662}：{npc:6018}的信件",
	["{quest:5663}: {npc:3044}'s letter"] = "{quest:5663}：{npc:3044}的信件",
	["{spell:2652} and {quest:5644}"] = "{spell:2652}和{quest:5644}",
}

G["forever/class/rogue/blade-of-cunning-horde"] = {
	["A dagger at 10 from your home town's rogue quests."] = "10级时来自家乡潜行者任务的一把匕首。",
	["At 10 {npc:2130}, the rogue trainer upstairs in the {area:2119} in {area:159}, sends you to {quest:1885} in the {zone:1458}."] = "10级时，{area:159}{area:2119}楼上的潜行者训练师{npc:2130}让你去{zone:1458}做{quest:1885}。",
	["At 10 {npc:3170}, the rogue trainer in {area:362}, sends you to {quest:1859} in {zone:1454}. It is only a pointer: an Orc already in {zone:1454} can skip it and take {quest:1963} from {quest:1859} straight away."] = "10级时，{area:362}的潜行者训练师{npc:3170}让你去{zone:1454}做{quest:1859}。这只是个指引：已经在{zone:1454}的兽人可以跳过它，直接从{quest:1859}那里接{quest:1963}。",
	["Back to {npc:6446}"] = "回到{npc:6446}那里",
	["Back to {npc:6467}"] = "回到{npc:6467}那里",
	["Rogue"] = "潜行者",
	["The {object:36073}"] = "{object:36073}",
	["{item:7208}: Pick Pocket Gamon"] = "{item:7208}：偷窃加摩尔的口袋",
	["{item:7209}, once you have the key"] = "{item:7209}，拿到钥匙后",
	["{item:7295}, from the satchel"] = "{item:7295}，来自挎包",
	["{item:7298} (Horde)"] = "{item:7298}（部落）",
	["{npc:6446}'s reward"] = "{npc:6446}的奖励",
	["{npc:6467} and {npc:2425}"] = "{npc:6467}与{npc:2425}",
	["{npc:6467} sends the ledger on to {npc:2425}, the big demon in the middle of the Hall of the Dark Lady in the {object:36126}, past its elite guards; the way in is the passage off the Apothecarium. If you lose the ledger, take another from {npc:6522}'s bookshelf."] = "{npc:6467}让你把账本送给{npc:2425}——那头大恶魔就在{object:36126}黑暗女士大厅的中央，一路都是精英守卫；入口在炼金房旁边的通道。如果账本弄丢了，从{npc:6522}的书架上再拿一本。",
	["{npc:6494} (level 13, not elite) is a troll pirate on the {area:391} south of {area:392}: he walks the fenced hill path between the lower pirate camp by the beached ship and the upper camp by a big tree. Fight him at the foot of the hill, away from the camps. He always drops his satchel and is back 4 1/2 minutes after a death; one satchel per kill, so two rogues need two kills. Hand the satchel in unopened: picking its lock now destroys it and you must kill him again."] = "{npc:6494}（13级，非精英）是{area:392}南边{area:391}的一名巨魔海盗：他在搁浅船只旁的下层海盗营地与一棵大树旁的上层营地之间，沿带栅栏的山路来回走。在山脚下打他，远离两处营地。他必掉背包，死后4分半刷新；每次击杀只掉一个背包，所以两名潜行者要杀两次。交背包时保持未拆封：现在撬开会毁掉它，只能再杀他一次。",
	["{npc:6497} (level 13) walks the road between the {area:228} and the {zone:1458}, north of the {area:228}. He looks like a friendly traveller with no quest mark. Talk to him and pick both of his answers: he turns hostile. Kill him for the letter (it always drops). Fight him away from guards, who can take the kill and leave no loot; only one rogue per kill gets the letter. He is back 5 minutes after a death."] = "{npc:6497}（13级）在{area:228}与{zone:1458}之间的大路上来回走，位于{area:228}以北。他看上去像个友善的旅人，头上没有任务标记。与他交谈，两个回答选项都点一遍：他就会转为敌对。杀掉他拿信件（必掉）。打他时离守卫远一点，守卫可能抢走击杀而且不掉落；每次击杀只有一名潜行者能拿到信。他死后5分钟刷新。",
	["{npc:6522} is in the Apothecarium, in its biggest room, where two huge guards watch a small bridge. His ledger is on the bookshelf in the back room behind him, not the shelf on the wall next to him."] = "{npc:6522}在炼金房最大的房间里，那里有两名高大的守卫守着一座小桥。他的账本在他身后里屋的书架上，不在他旁边墙上的架子。",
	["{quest:1859} hands the satchel back: now open it. {npc:6466} (level 12) kneels by the innkeeper in the inn in the {object:172982}; stealth up and pick his pocket for {item:7208} (do not kill him: the key almost never drops). Players often kill him, so you may wait up to 5 minutes for him. Then use the key on {item:7209} in your bags. If you have trained {spell:1804}, you can pick the satchel's lock instead."] = "{quest:1859}会把背包还给你：现在打开它。{npc:6466}（12级）跪在{object:172982}旅店的老板身旁；潜行上去偷他的口袋拿{item:7208}（别杀他：钥匙几乎不掉）。玩家经常杀他，所以你可能要等他刷新，最长5分钟。然后对背包里的{item:7209}使用钥匙。如果你已学会{spell:1804}，也可以直接撬开背包的锁。",
	["{quest:1859} stands in the {object:172960}, the canyon under the {object:172982}. Trolls: take {quest:1963} from him at 10."] = "{quest:1859}站在{object:172960}，也就是{object:172982}下方的峡谷里。巨魔：10级时从他那里接受{quest:1963}。",
	["{quest:1885} stands in the {object:36073}."] = "{quest:1885}站在{object:36073}。",
}

G["forever/class/rogue/plundering-the-plunderers"] = {
	["At 16 {npc:3170}, the rogue trainer in {area:362}, sends you to {npc:3401} in {zone:1454}."] = "16级时，{area:362}的潜行者训练师{npc:3170}会让你去找{zone:1454}的{npc:3401}。",
	["At 16 {npc:6467} in the {object:36073} sends you to {npc:3401} in {zone:1454}. Take {quest:1998} from him too; it is done in {zone:1421} at the end of this guide."] = "16级时，{object:36073}的{npc:6467}会让你去找{zone:1454}的{npc:3401}。同时从他那里接受{quest:1998}；它在本指南最后于{zone:1421}完成。",
	["Back to {npc:6467}"] = "回到{npc:6467}处",
	["Back to {npc:7161}"] = "回到{npc:7161}处",
	["Fly or walk to {area:392} on the {zone:1413} coast. {npc:7161} stands in a small shed near the bank, up the hill to the left before the docks. His Gizmotronic Apparatus beside him hands out what the job needs: take an {item:7970} and {item:5060} ({spell:1804} does not work without the tools in your bags)."] = "飞往或走到{zone:1413}海岸的{area:392}。{npc:7161}站在银行附近的一间小棚子里，在码头前面上坡左转。他身旁的精巧装置会发放任务所需工具：拿一个{item:7970}和{item:5060}（包里没有工具时{spell:1804}无法使用）。",
	["Follow the coast south from {area:392} to the first beached pirate ship, the Tide Razor, and climb aboard up its bow. On the middle deck the Buccaneer's Strongboxes come back fast: pick them until your Lockpicking is about 30 (a few are trapped with a frost nova or turn you into a rat; picking still works as a rat). Keep picking while they still give skill: the poisons job at 20 ends at a lockbox that needs about 75, and these boxes are the closest practice. Then go down to the bottom hold and pick the lock of {object:123462}: it is empty, but opening it calls a giant level 50 {npc:7168} into the next room. Stay stealthed, put the {item:7970} on your action bar, target {npc:7168} and use it: the parrot shrinks to level 18. Kill it for the {item:7968}."] = "从{area:392}沿海岸向南走到第一艘搁浅的海盗船“潮汐剃刀号”，从船头登船。中层甲板上的海盗保险箱刷新很快：一直开锁练到开锁技能30左右（有几个箱子带冰霜新星陷阱或会把你变成老鼠；变成老鼠也能继续开锁）。只要还给技能点就继续练：20级的制毒任务最后要开一个需要约75点开锁的箱子，而这些箱子是最近的练习对象。然后下到最底层船舱，撬开{object:123462}的锁：箱子是空的，但打开它会在隔壁房间召出一只巨大的50级{npc:7168}。保持潜行，把{item:7970}放到动作条上，选中{npc:7168}并使用：鹦鹉会缩成18级。杀掉它拾取{item:7968}。",
	["If you have no {item:5060} left, ask {npc:6566}, the outfitter in the {object:36073}."] = "如果{item:5060}用完了，找{object:36073}里的供应商{npc:6566}。",
	["Rogue"] = "潜行者",
	["Take the zeppelin from {zone:1454} to the {zone:1458} and head south into Silverpine. {quest:1998} (level 16) stands alone on the old ferry dock on {area:1338}, north-east of the {area:228}. His Uppercut knocks you back, so do not fight him at the dock's edge. He always drops his head and is back 4 1/2 minutes after a death."] = "从{zone:1454}乘飞艇到{zone:1458}，再向南进入银松森林。{quest:1998}（16级）独自站在{area:1338}的旧渡船码头上，位于{area:228}东北。他的上勾拳会把你击退，所以别在码头边缘与他战斗。他必掉头颅，死后4分半刷新。",
	["Ten {item:7676}, the rogue energy drink, from the Horde lockpicking jobs at 16."] = "十份{item:7676}——潜行者的能量饮料，来自16级的部落开锁任务。",
	["The Kirin Tor keep their reports in walled {area:233}, in south-east Silverpine. Facing the town hall, take the building on the right: the {object:103815} is in a corner room upstairs (any Lockpicking opens it; the {item:5060} must be in your bags). Three casters of level 19-20 guard that floor and see through stealth, one walking in and out of the strongbox room: time it or fight them one at a time."] = "肯瑞托把报告存放在银松森林东南部带围墙的{area:233}。面对市政厅，走右边那栋建筑：{object:103815}在楼上的拐角房间里（任何开锁技能都能开；{item:5060}必须在背包里）。三名19-20级的法系怪守着那层楼且能看破潜行，其中一个会进出保险箱房间：掐好时机，或者逐个击破。",
	["Undead take the zeppelin from the towers outside the {zone:1458} to {zone:1411}. {npc:3401} and {quest:2379} stand in the {object:172960}, the canyon under the {object:172982}. Train {spell:1804} from {npc:3401} (or any rogue trainer) now if you lack it: this job is a lockpicking test."] = "亡灵从{zone:1458}城外的塔楼乘飞艇前往{zone:1411}。{npc:3401}和{quest:2379}站在{object:172960}，即{object:172982}下方的峡谷里。如果还没学{spell:1804}，现在就找{npc:3401}（或任何潜行者训练师）学习：这个任务就是一场开锁考试。",
	["{item:7968}: {npc:7168}, after the {item:7970}"] = "{item:7968}：{npc:7168}，使用{item:7970}之后",
	["{npc:3401} and {quest:2379}"] = "{npc:3401}和{quest:2379}",
	["{npc:7161}: ten {item:7676}"] = "{npc:7161}：十份{item:7676}",
}

G["forever/class/rogue/poisons-horde"] = {
	["/salute {npc:3401}"] = "对{npc:3401}使用/salute",
	["Back to {npc:3401}"] = "回到{npc:3401}处",
	["Fly back to {zone:1454} ({area:392} or the {area:380}; dying at the tower and taking the spirit healer's way back to the {area:380} is quicker). Keep {item:8072} afterwards. Before you leave the {area:263}, buy {item:2928} and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of {item:6947} takes one of each."] = "飞回{zone:1454}（{area:392}或{area:380}；在塔楼那里死掉、走灵魂医者的路线回到{area:380}更快）。之后留着{item:8072}。离开{area:263}之前，向雷库尔购买{item:2928}和空瓶：希诺特教会你毒药后，每批{item:6947}都要各消耗一个。",
	["Fly to the {area:380} and head north to the Venture Co. tower above the {area:382}. Fizzule stands under a tree east of the tower, outside it, and is hostile until signalled. Target him from about 50 yards and fire the {item:8051} twice, then walk up in front of him and /salute. In any other order he attacks. Lost the {item:8051}? Abandon and retake from {npc:3401}."] = "飞到{area:380}，向北前往{area:382}上方风险投资公司的塔楼。菲祖尔站在塔楼东侧的一棵树下、塔外，在收到信号前是敌对的。在约50码外选中他，发射{item:8051}两次，然后走到他面前 /敬礼。顺序不对他就会攻击。弄丢了{item:8051}？放弃任务，再找{npc:3401}重新接取。",
	["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "在 Forever 里，毒药是通过这条任务链学会的，训练师不教；{item:7676}的配方也随任务一并获得。",
	["Inside, floor by floor (everything comes back after 4 1/2 minutes): the Mutated Venture Co. Drones (level 25) on the ground floor die to one Ambush with a dagger; the Patrollers on the second floor take half their health from a one-point {spell:1943}; the Lookouts on the open third floor from a one-point {spell:2098}. {npc:7288} waits on the top floor: a level 23 elite, back 10 minutes after a kill. Open with Ambush (about half his health), then {spell:1776}, {spell:5277}, a healing potion and {item:7676}; a friend makes it easy. One head per kill. Then pick {object:129127} beside him for the cache: it poisons you with the {spell:9810}, which weakens your stealth and agility until {npc:2391} cures it."] = "里面逐层推进（全部4分半钟后刷新）：一楼的变异风险投资公司雄蜂（25级）用匕首一次伏击就能解决；二楼的巡逻者用一点{spell:1943}打掉一半血；露天三楼的瞭望员用一点{spell:2098}。{npc:7288}在顶层等着：23级精英，被杀后10分钟刷新。先手伏击（约打掉他一半血），然后{spell:1776}、{spell:5277}、一瓶治疗药水和{item:7676}；有朋友帮忙就很轻松。每杀一次掉一个头颅。然后撬开他旁边的{object:129127}取宝箱：它会用{spell:9810}使你中毒，削弱你的潜行和敏捷，直到{npc:2391}为你解毒。",
	["Keep {item:8066} in your bags and use it on him every time you come near, or he turns hostile. {npc:7287} (level 22) walks by the tower: hug the wall, stealth up behind him and {spell:921} the key. Killing him does not give it; if his pockets are empty, kill him and wait 4 1/2 minutes for him to come back."] = "把{item:8066}放在包里，每次靠近他时就对他使用，否则他会转为敌对。{npc:7287}（22级）在塔楼旁走动：贴着墙，潜行到他背后用{spell:921}偷钥匙。杀他不会得到钥匙；如果他身上没东西，就杀了他，等4分半钟刷新。",
	["Lockpicking about 75: pick the Buccaneer's Strongboxes on the Tide Razor"] = "开锁技能约75：撬开潮汐剃刀号上的海盗保险箱",
	["Lockpicking practice"] = "开锁练习",
	["Mutated Venture Co. Drone"] = "变异的风险投资公司雄蜂",
	["Poisons (Horde)"] = "毒药（部落）",
	["Rogue"] = "盗贼",
	["Take the zeppelin from {zone:1454} to the {zone:1458} and follow the road south through {zone:1421} into {area:287}, to {area:272}. {npc:2391} works in the building next to the flight path, beside {npc:2216}, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from {npc:3401}. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make {item:6947} from Rekkul's dust and vials, and use it on your weapon."] = "从{zone:1454}乘飞艇到{zone:1458}，沿路向南穿过{zone:1421}进入{area:287}，到达{area:272}。{npc:2391}在飞行点旁边的那栋建筑里工作，门外是{npc:2216}的马车。如果弄丢了赞吉尔混合物样本，就放弃任务并找{npc:3401}重新接取。在他调配解药时守在旁边约一分钟；如果一直没完成，就放弃并向他重新接取。然后打开法术书里的毒药，用雷库尔的粉尘和空瓶制作{item:6947}，涂在你的武器上。",
	["The Venture Co. tower"] = "风险投资公司的塔楼",
	["Tide Razor"] = "潮汐剃刀号",
	["Venture Co. Lookout"] = "风险投资公司瞭望员",
	["Venture Co. Patroller"] = "风险投资公司巡逻者",
	["Wait for the cure"] = "等待解药",
	["{item:8051}, twice, at Fizzule"] = "{item:8051}，对菲祖尔使用两次",
	["{item:8072}: Pick Pocket Foreman Silixiz"] = "{item:8072}：对工头西利克兹使用偷窃",
	["{item:8074}: {npc:7288} (elite)"] = "{item:8074}：{npc:7288}（精英）",
	["{item:8095}: clears the {spell:9810}"] = "{item:8095}：解除{spell:9810}",
	["{npc:2391}: Poisons"] = "{npc:2391}：毒药",
	["{npc:3401} stands in the {object:172960}, the canyon under the {object:172982}. Take the quest and wait: he speaks three lines and salutes you. After his third line, target him and type /salute. If it does not count, abandon the quest and take it again. The tower job ahead is built around Ambush, which needs a dagger: if you have none, Kareth, the blade merchant in the {object:172960}, sells a Jambiya."] = "{npc:3401}站在{object:172960}里，也就是{object:172982}下方的峡谷。接取任务后等着：他会说三句话，然后向你敬礼。等他说完第三句，选中他并输入 /敬礼。如果没算数，就放弃任务重新接取。前面的塔楼任务围绕伏击展开，需要匕首：如果没有匕首，{object:172960}里的武器商人卡雷斯出售一把詹比亚弯刀。",
	["{object:129127} at the end of the tower job needs Lockpicking of about 70-75. Train {spell:1804} from Gest or {npc:3401} in the {object:172960} if you lack it, carry {item:5060}, and pick the Buccaneer's Strongboxes on the middle deck of the Tide Razor, the beached pirate ship south of {area:392}: they come back fast. Your cap rises 5 per level."] = "塔楼任务最后的{object:129127}需要约70-75点开锁。如果不会，就找{object:172960}里的盖斯特或{npc:3401}学习{spell:1804}，带上{item:5060}，去撬潮汐剃刀号中层甲板上的海盗保险箱——那是{area:392}以南一艘搁浅的海盗船：刷新很快。你的开锁上限每级提高5点。",
	["{quest:2458}: keep the {item:8051}"] = "{quest:2458}：保留{item:8051}",
}

G["forever/class/shaman/call-of-air-horde"] = {
	["At 30 Skyborne shamans get their own {quest:96136}. {npc:259119} waits where the airship from Zephras Isle lands, in northern {zone:1412} beside {zone:1456}. Your level 30 air totems need the Air Totem Prate Cloudseer gives. If she has nothing for you, head up to {npc:5906} in {zone:1456} (next step): the trainers' {quest:96136} is open to Skyborne and gives the same totem."] = "30级时，天裔萨满可以接取自己的{quest:96136}。{npc:259119}在{zone:1412}北部、{zone:1456}旁等待，那里是来自泽弗拉斯岛的飞艇降落处。你的30级空气图腾需要普雷特·望云给的空气图腾。如果她这里没有你的任务，就去{zone:1456}的{npc:5906}那里（下一步）：训练师的{quest:96136}对天裔开放，给的是同一个图腾。",
	["At 30 {npc:5892} in the {object:172957} sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} she gives."] = "30级时，{object:172957}里的{npc:5892}派你去{zone:1441}找{npc:5905}。你的30级空气图腾（根基图腾、{spell:10596}）需要她给的{item:5178}。",
	["At 30 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the Air Totem Prate gives. Already carry {npc:5892}'s {quest:1531} from {zone:1454}? It goes to {npc:5905} too: skip {npc:5906}."] = "30级时，{zone:1456}内{area:1640}上的萨满训练师{npc:5906}派你去{zone:1441}找{npc:5905}。你的30级空气图腾（根基图腾、{spell:10596}）需要普雷特给的空气图腾。已经带着来自{zone:1454}的{npc:5892}的{quest:1531}？它也是交给{npc:5905}：跳过{npc:5906}。",
	["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "五个畸变空气图腾。{zone:1443}西部{area:2408}以北和东北的玛洛丁半人马（36-40级）携带它们；斥候几乎每两次击杀就掉一个。驯兽者会撒网和缴械，逐风者会治疗，风暴者会投掷{spell:9654}：一次拉一个。刷新约五分钟。",
	["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "五个畸变大地图腾。{zone:1435}中{area:75}以北和东北的失落者（鱼人，34-39级）携带它们；大多数受伤时会逃跑求援。",
	["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "五个畸变火焰图腾。{zone:1418}中{area:338}以南的石穹穴居怪（碎颅者、碎骨者和萨满，37-41级）携带它们；萨满会放下火焰新星图腾和一个{npc:3560}，碎骨者受伤时会逃跑求援。刷新约五分钟。",
	["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "五个畸变水图腾。{zone:1445}北部{area:496}东北的泥鳍鱼人（35-38级）携带它们。",
	["Fly to {area:484}. {npc:5905} stands on a ledge above a cave mouth in the canyon wall north-east of the post, not inside the cave: climb the slope beside it. She also gives you an hour of faster attacks and running."] = "飞往{area:484}。{npc:5905}站在哨站东北峡谷壁上一个洞口上方的平台上，不在洞里：从旁边的斜坡爬上去。她还会给你一小时的攻击和奔跑加速。",
	["Shaman"] = "萨满祭司",
	["The steam pools"] = "蒸汽池",
	["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "获得能放置空气图腾的{item:5178}，然后在40级自选一把武器。",
	["Twisted Air Totems"] = "扭曲的空气图腾",
	["Twisted Earth Totems"] = "扭曲的大地图腾",
	["Twisted Fire Totems"] = "扭曲的火焰图腾",
	["Twisted Water Totems"] = "扭曲的水之图腾",
	["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717}是{zone:1413}南缘的五人副本（箭头指向它的入口）；{npc:4421}（33级精英）是最终首领。她会施放{spell:8292}、对盟友施放{spell:139}和纯净；{item:274463}只有她会掉落。",
	["{item:212792}, from the {npc:216474}"] = "{item:212792}，来自{npc:216474}",
	["{item:274463}, from {npc:4421}"] = "{item:274463}，来自{npc:4421}",
	["{npc:4722} stands at {area:484}."] = "{npc:4722}站在{area:484}。",
	["{npc:5905} hands you the {item:268582}. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "{npc:5905}把{item:268582}交给你。在{area:484}西北的蒸汽池放上{item:268582}，召唤被腐蚀的元素，然后是{npc:216474}；仪式进行时钢鬃野猪人会加入战斗。这是组队任务：至少带一两个朋友。{item:212792}大约每两次击杀掉落一次，队里每个人都能拾取。",
	["{npc:5905}: your {item:5178}"] = "{npc:5905}：你的{item:5178}",
	["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}; the {item:280696} shield comes with it."] = "{npc:6176}在{zone:1416}东部的废墟扎营：从{area:272}沿镇子东边的河向北进入丘陵。任选武器：{item:280607}、{item:280605}或{item:280604}；还会附带{item:280696}盾牌。",
	["{npc:6176}: the {item:280696} and your weapon"] = "{npc:6176}：{item:280696}和你的武器",
	["{quest:1531} and the Tempest's Weapons (Horde)"] = "{quest:1531}和风暴武器（部落）",
}

G["forever/class/shaman/call-of-earth-horde"] = {
	["Any Al'Aketh cultist can carry the {item:251924}: the Converts (level 2-3) around the standing stones just east of the village, or the Brutes and Neophytes (level 4) in the camp beyond {npc:252095}, south-west of the village. Keep killing until one drops it."] = "任何Al'Aketh教派的信徒都可能携带{item:251924}：村子正东巨石阵周围的皈依者（2-3级），或村子西南{npc:252095}之外营地里的壮汉和新信徒（4级）。一直杀到有人掉落为止。",
	["Back to Boro in {area:16635}. He hands you the {quest:1462}: do not drink it yet."] = "回到{area:16635}的博罗。他会交给你{quest:1462}：先别喝。",
	["Back to the Seer in {area:221}. She hands you the {quest:1462}: do not drink it yet."] = "回到{area:221}的先知。她会交给你{quest:1462}：先别喝。",
	["Back to {npc:5887} outside the Den. She hands you the {quest:1462}: do not drink it yet."] = "回到洞穴外的{npc:5887}。她会交给你{quest:1462}：先别喝。",
	["Bring the {item:6656} back to Boro. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "把{item:6656}带回给博罗。把{item:5175}永久留在包里：每个大地图腾都要用它。",
	["Bring the {item:6656} back to the Seer. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "把{item:6656}带回给先知。把{item:5175}永久留在包里：每个大地图腾都要用它。",
	["Bring the {item:6656} back to {npc:5887} outside the Den. Keep the {item:5175} she gives you in your bags for good: every earth totem needs it."] = "把{item:6656}带回给洞穴外的{npc:5887}。把她给你的{item:5175}永久留在包里：每个大地图腾都要用它。",
	["Felstalker Hooves"] = "恶魔猎犬蹄",
	["Felstalkers (level 3-4) prowl the slope below the {area:365}, the cave in the north of the valley, and just inside its mouth among the Vile Familiars. Nearly every {npc:3102} drops a hoof (four kills in five); they respawn in a little over three minutes."] = "恶魔猎犬（3-4级）在山谷北部洞穴{area:365}下方的斜坡上游荡，也出现在洞口内侧的邪恶魔宠之间。几乎每只{npc:3102}都会掉落一只蹄子（五次击杀有四次）；它们三分钟多一点刷新。",
	["Lost the {quest:1462}?"] = "丢了{quest:1462}？",
	["Lost the {quest:1463}?"] = "丢了{quest:1463}？",
	["Only if the {quest:1462} is gone from your bags: the Seer gives you another."] = "仅当{quest:1462}已从包里消失时：先知会再给你一个。",
	["Only if the {quest:1463} is gone from your bags (drunk away from the rock, or sold): {npc:5887} gives you another."] = "仅当{quest:1463}已从包里消失时（在岩石外喝掉或卖掉）：{npc:5887}会再给你一个。",
	["Shaman"] = "萨满",
	["The Bristleback Shamans (level 3-4) stand among the quilboar huts of {area:358}, east of the camp, and throw the odd {spell:403}. Four kills in five drop a salve; they respawn in about four minutes."] = "刺背萨满（3-4级）站在营地东边{area:358}的野猪人棚屋之间，偶尔会扔{spell:403}。五次击杀有四次掉落药膏；它们约四分钟刷新。",
	["The {area:16988}"] = "{area:16988}",
	["The {area:16988} is the hilltop shrine north-east of Boro: the path up starts on the hill just above the clearing where the flies were. Drink the {item:6635} beside the shrine and speak to the {npc:251166} before it fades."] = "{area:16988}是博罗东北的山顶祭坛：上山的路径从苍蝇出没的空地上方那座小山开始。在祭坛旁喝下{item:6635}，趁效果消失前和{npc:251166}交谈。",
	["Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4."] = "你的{item:5175}：没有它就无法施放任何大地图腾。4级时会连同{spell:8071}一起获得。",
	["it hands you the {item:6656}: keep it"] = "它会交给你{item:6656}：留着它",
	["the level 4 shaman spells"] = "4级萨满法术",
	["{area:637} is a small pillar on a low mound due east of {npc:2991}'s well, east of the camp; it only shows from about fifteen yards away, and hostile boars graze around it. Stand beside it and drink the {item:6635}, then speak to the {npc:5891} before it fades (drink again if it does)."] = "{area:637}是营地东边{npc:2991}的水井正东一座矮丘上的小石柱；它只有在大约十五码内才看得见，周围还有敌对的野猪在吃草。站到它旁边喝下{item:6635}，趁效果消失前和{npc:5891}交谈（若效果消失就再喝一次）。",
	["{area:639} sits on a ledge in the hills just south of the Den. The {area:638} up starts at the foot of the hills south-west of the Den, between two idle peons; it climbs south-west into the hills, then bends back east to the rock. Stand right beside the stone and drink the {item:6635}: the {npc:5891} appears for a short while, so speak to it at once (walk almost under it if it does not answer). Coming back, you can drop down the ledge towards the Den instead of walking the path."] = "{area:639}位于洞穴正南丘陵中的一处台地上。上山的路{area:638}从洞穴西南的山脚开始，就在两个闲着的苦工之间；它向西南爬进丘陵，然后折回东边通向那块岩石。紧挨着石头站好，喝下{item:6635}：{npc:5891}会短暂出现，所以要马上和它交谈（如果它没有反应，就走到几乎贴着它下方）。回程时可以从台地朝洞穴方向跳下去，不必走原路。",
	["{item:6635}, beside the shrine"] = "{item:6635}，在祭坛旁",
	["{item:6635}, beside {area:637}"] = "{item:6635}，在{area:637}旁",
	["{item:6635}, beside {area:639}"] = "{item:6635}，在{area:639}旁",
	["{npc:251374}, the shaman trainer, stands in {area:16635}. The quest opens at level 3."] = "萨满训练师{npc:251374}站在{area:16635}。该任务3级开放。",
	["{npc:251374}: {spell:8071} and your {item:5175}"] = "{npc:251374}：{spell:8071}和你的{item:5175}",
	["{npc:5887} stands just outside the Den, the cave in the middle of the {area:363}. The quest opens at level 4."] = "{npc:5887}站在洞穴外，也就是{area:363}中间的那个山洞。该任务4级开放。",
	["{npc:5887}: a new {quest:1463}"] = "{npc:5887}：新的{quest:1463}",
	["{npc:5887}: {spell:8071} and your {item:5175}"] = "{npc:5887}：{spell:8071}和你的{item:5175}",
	["{npc:5888} stands in {area:221}. She may show no quest mark over her head: speak to her anyway. The quest opens at level 4."] = "{npc:5888}站在{area:221}。她头上可能不显示任务标记：还是去和她说话。该任务4级开放。",
	["{npc:5888}: a new {quest:1462}"] = "{npc:5888}：新的{quest:1462}",
	["{npc:5888}: {spell:8071} and your {item:5175}"] = "{npc:5888}：{spell:8071}和你的{item:5175}",
	["{quest:1516} (Horde)"] = "{quest:1516}（部落）",
}

G["forever/class/shaman/call-of-fire-horde"] = {
	["At 10 {npc:252382}, the shaman trainer beside {npc:251968} in {area:16638}, hands you the {item:6653} ({npc:254082} offers the same quest). Already left the isle? A {quest:97243} sends you back to them: take the skycutter from the cliffs south of {area:17045}, north of {zone:1456}. Learn {spell:8050} from her now: {npc:268605}, later in the chain, only takes fire damage."] = "10级时，{area:16638}里{npc:251968}身旁的萨满训练师{npc:252382}交给你{item:6653}（{npc:254082}提供同一个任务）。已经离岛了？{quest:97243}会把你送回去：在{zone:1456}以北、{area:17045}以南的悬崖乘天艇。现在就向她学习{spell:8050}：任务链后面的{npc:268605}只吃火焰伤害。",
	["At 10 {npc:3066}, the shaman trainer in {area:222}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5906}'s letter from {zone:1456}? It goes to {npc:5907} too: skip Narm."] = "10级时，{area:222}的萨满训练师{npc:3066}让你去{zone:1413}找{npc:5907}。已经带着{zone:1456}{npc:5906}的信了？那封信也是给{npc:5907}的：不必再跑纳姆这一趟。",
	["At 10 {npc:3173}, the shaman trainer on the east side of {area:362}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5892}'s letter from {zone:1454}? It goes to {npc:5907} too: skip {npc:3173}."] = "10级时，{area:362}东侧的萨满训练师{npc:3173}让你去{zone:1413}找{npc:5907}。已经带着{zone:1454}{npc:5892}的信了？那封信也是给{npc:5907}的：跳过{npc:3173}。",
	["Back east over the bridge, then south along the {zone:1411} bank of the river to where the mountains meet the water. The trail up starts at the foot of the mountain beside a small dark stone carved with symbols, near the quilboar camp; it is narrow, and a slip costs fall damage. {npc:5900} keeps the shrine at the top."] = "向东过桥折返，再沿河的{zone:1411}一岸向南，走到群山与水面相接的地方。上山的小径从山脚开始，旁边有一块刻着符号的黑色小石，离野猪人营地很近；路很窄，失足会摔伤。{npc:5900}守在山顶的神龛。",
	["Back to {npc:268592} at the Shrine of Flames."] = "回火焰神龛找{npc:268592}。",
	["Back to {npc:268592}. Accept the last quest, then wait by the {npc:268762} while he performs the ritual; when the fire spirits light the {object:148418}, hold the torch to it. From then you have six minutes: carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638}, with no detours or fights. Timer out? Abandon the quest and take it again from {npc:268592}."] = "回到{npc:268592}处。接最后一个任务，然后在{npc:268762}旁等他完成仪式；等火灵点亮{object:148418}，就把火把凑上去点着。从那一刻起你有六分钟：把火焰径直送到{area:16638}{npc:252382}身旁的{npc:268679}那里，不许绕路、不许战斗。超时了？放弃任务，重新找{npc:268592}接。",
	["Back up the trail to {npc:5900}. He makes the {quest:1464} from the tar and the pouch and hands it to you with the torch: keep both."] = "沿小径回到{npc:5900}那里。他用焦油和袋子做出{quest:1464}，连同火把一起交给你：两样都收好。",
	["Click the {object:61934} on the plateau with the torch in your bags to place the ember, then click it a second time: the next quest does not open by itself. It gives you the lit {item:277329}."] = "背包里带着火把，点击高地上的{object:61934}放下余烬，然后再点一次：后续任务不会自己弹出来。它会把点燃的{item:277329}给你。",
	["Down the trail, back over the bridge to {npc:5907} by his tower. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "走下小径，过桥回到高塔旁的{npc:5907}那里。把{item:5176}永远留在背包里：每根火焰图腾都离不开它。",
	["Drink the {item:6636} beside the {object:63674}, the big grey stone just below the summit, then climb to the plateau. Of the fire elementals there only the one in the middle can be attacked: it is level 12, immune to fire and grows stronger the longer the fight lasts, so open at once with {spell:8017} and {spell:8042} and leave the others alone. Its {item:6655} drops every time."] = "在峰顶正下方那块大灰石{object:63674}旁喝下{item:6636}，然后爬上高地。那里的一群火元素里只有中间那只能打：12级，火焰免疫，战斗拖得越久它越强，所以一开打就用{spell:8017}和{spell:8042}，其他的别碰。它每次都掉{item:6655}。",
	["Keep the {item:5176} in your bags for good: every fire totem needs it."] = "把{item:5176}永远留在背包里：每根火焰图腾都离不开它。",
	["Lost the {quest:1464}?"] = "{quest:1464}弄丢了？",
	["Only if the {quest:1464} is gone from your bags: {npc:5900} gives you another."] = "只有当{quest:1464}不在你背包里时：{npc:5900}会再给你做一个。",
	["Shaman"] = "萨满祭司",
	["The Burning Blade Cultists (level 10-11, they call imps and cast {spell:348}) live deep in {area:371} north of {area:362}: climb the ramp just north-east of town and stay on the high ground above the ravines. The orcs at the cave mouth are not cultists; the cultists are further in, off to the left. Three kills in four drop a pouch. {area:817} by {zone:1454} is the wrong cave."] = "火刃教徒（10-11级，会召小鬼、施放{spell:348}）盘踞在{area:362}以北{area:371}的深处：从镇子东北边的坡道爬上去，一直走在沟壑上方的高地上。洞口的兽人不是教徒；教徒在更深处，进去后靠左走。大约四次击杀掉三个袋子。{zone:1454}旁边的{area:817}是错的洞。",
	["The Razormane casters north-east of the {area:380} drop the {item:5026} three times in four: Water Seekers and Thornweavers (level 10-11), Geomancers (level 12-13, they throw Fireballs and run for help when hurt) and Mystics (level 13-14, they heal themselves at low health). Pull them one at a time."] = "{area:380}东北方的刺背部落施法者约四次击杀掉三个{item:5026}：寻水者和织棘者（10-11级）、地卜师（12-13级，会扔火球，受伤就逃跑喊人）和秘法师（13-14级，血量低时会治疗自己）。一次拉一只打。",
	["The Shrine of Flames hides on the island's outer rim south-west of {area:16638}, just south-east of {area:16663}: {npc:268592} keeps it."] = "火焰神龛藏在{area:16638}西南方、岛屿的外缘，就在{area:16663}东南方：由{npc:268592}看守。",
	["The {npc:5893}"] = "{npc:5893}",
	["The {object:148418}"] = "{object:148418}",
	["The {object:61934}"] = "{object:61934}",
	["Your {item:5176} for every fire totem, {spell:3599} with it, and Forever's {item:263412}."] = "每根火焰图腾要用的{item:5176}、配合它的{spell:3599}，还有Forever的{item:263412}。",
	["the ritual, then the {npc:268679} in {area:16638}"] = "仪式，然后送去{area:16638}的{npc:268679}",
	["{item:6636}, beside the {object:63674}"] = "{item:6636}，在{object:63674}旁",
	["{npc:252382}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:252382}：{spell:3599}、你的{item:5176}和{item:263412}",
	["{npc:268602} (level 10, a turncoat Windshaper with a single spawn) holds the farm north-east past {area:16638}, just south of the {area:16629}, on the hill west of the falls north of the {area:17675}. Kill him and take his heart."] = "{npc:268602}（10级，变节的塑风者，只有一个刷新点）占着{area:16638}东北边的那座农场，就在{area:16629}以南、{area:17675}以北瀑布西侧的山丘上。杀掉他，取他的心脏。",
	["{npc:5900}: a new {quest:1464}"] = "{npc:5900}：一个新的{quest:1464}",
	["{npc:5907} hands you the {item:6653}: keep it until the end of the chain."] = "{npc:5907}交给你{item:6653}：一直留到任务链结束。",
	["{npc:5907} is not in the {area:380}: take the road north from the {area:380} and fork east towards {zone:1411}; past {area:1704} he paces by a tall tower east of the road (from {zone:1411}: over the Southfury bridge, past {area:379}). If you reach {zone:1440} you went too far."] = "{npc:5907}不在{area:380}：从{area:380}沿路向北，在岔口向东朝{zone:1411}走；过了{area:1704}，他就在大路东侧一座高塔旁踱步（从{zone:1411}出发：过南怒河大桥，经过{area:379}）。要是走到{zone:1440}，说明你走过头了。",
	["{npc:5907}: {npc:3066}'s letter"] = "{npc:5907}：{npc:3066}的信",
	["{npc:5907}: {npc:3173}'s letter"] = "{npc:5907}：{npc:3173}的信",
	["{npc:5907}: {npc:5892}'s letter"] = "{npc:5907}：{npc:5892}的信",
	["{npc:5907}: {npc:5906}'s letter"] = "{npc:5907}：{npc:5906}的信",
	["{npc:5907}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:5907}：{spell:3599}、你的{item:5176}和{item:263412}",
	["{object:660848} is the twisted stump on the hilltop by the Shen'dar Highlands Anchor Pylon, west of {area:16638}, in the hills south of the Windsong Crawlers' lakes. Knock on it to call {npc:268605} (level 10). The spirit shrugs off most magic: only fire hurts it, so keep {spell:8050} on it. Take its wooden mask."] = "{object:660848}是{area:16638}以西、辛达尔高地锚定塔旁边山顶上的那截扭曲树桩，在风歌爬行者湖泊南边的丘陵里。敲击树皮召唤{npc:268605}（10级）。这个精魂几乎不吃魔法：只有火焰能伤到它，所以全程保持{spell:8050}。拿走它的木制面具。",
	["{object:660848}: knock on the bark"] = "{object:660848}：敲击树皮",
	["{quest:1522} (Horde)"] = "{quest:1522}（部落）",
}

G["forever/class/shaman/call-of-water-horde"] = {
	["At 20 {npc:5892} in the {object:172957} sends you to {npc:5901} in the {zone:1413}. (Swart in {area:362} gives the same letter: carry either.)"] = "20级时，{object:172957}中的{npc:5892}派你去找{zone:1413}的{npc:5901}。（{area:362}的斯瓦特也会给同样的信：拿哪一封都行。）",
	["At 20 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5901} in the {zone:1413}. ({npc:3066} in {area:222} gives the same letter: carry either.)"] = "20级时，{zone:1456}的{area:1640}上的萨满训练师{npc:5906}派你去找{zone:1413}的{npc:5901}。（{area:222}的{npc:3066}也会给同样的信：拿哪一封都行。）",
	["Back to {npc:5899}. She gives you the {item:7810} for {npc:5901}."] = "回到{npc:5899}处。她会把要交给{npc:5901}的{item:7810}给你。",
	["Back to {npc:5901} south of {area:392}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "回到{area:392}南边的{npc:5901}处。把{item:5177}永久留在背包里：每个水图腾都要用它。",
	["Click the {object:113791} to place the bracers and the drops. A few seconds later the pure {npc:5895} rises on the stone in the middle of the pool: speak to it while the {spell:8202} lasts (drink again by the stone if it has worn off). It gives you the {item:7813} for {npc:5901}. Gone before you could speak to it? Back at {npc:5901} ask for {quest:63} (a fresh {quest:972} for {npc:7007}, who stands just west of the shrine): hand it to Tiev, stay close while he calls the spirit back, then speak to it."] = "点击{object:113791}，放上护腕和掉落物。几秒后，纯净的{npc:5895}会浮现在水池中央的石头上：趁着{spell:8202}还在，跟它对话（如果效果消失了，就在石头旁再喝一次）。它会给你要交给{npc:5901}的{item:7813}。还没轮到说话它就消失了？回到{npc:5901}处要{quest:63}（一封给{npc:7007}的新{quest:972}，他就站在神龛西边）：把信交给蒂耶夫，在他召回幽灵的过程中保持靠近，然后再跟幽灵对话。",
	["Fly to the {area:228}. The shrine lies in a hollow just south-west of it: go round the back of the crypt to the thick tree between the two hills, hop past it onto the rocks and drop west down the slope to the pool (each drop costs a little health). Drink the {item:6637} beside the tall standing stone by the pool: several water elementals appear, and only the corrupt one near the middle can be attacked (Tab picks it). The {npc:5894} is level 22 and casts {spell:8056} and {spell:122}; if someone just killed it, it is back in about three minutes. Its bracers always drop."] = "飞到{area:228}。神龛就在它西南边的一处洼地里：绕到墓穴后面，走到两座山丘之间那棵粗树，跳过它落到岩石上，再往西下坡跳到水潭（每次下落都会掉一点生命值）。在水潭旁的高立石边喝下{item:6637}：会出现几个水元素，只有中间附近那个堕落的水元素可以攻击（按 Tab 选中）。{npc:5894}是22级，会施放{spell:8056}和{spell:122}；如果刚有人杀了它，大约三分钟后就刷新。它的护腕必掉。",
	["Lost the {quest:972}?"] = "把{quest:972}弄丢了？",
	["Only if the {quest:972} is gone from your bags: {npc:5901} gives you another."] = "只有当{quest:972}从背包里消失时才需要：{npc:5901}会再给你一封。",
	["Shaman"] = "萨满",
	["The muddy pond below {npc:5899}'s hut. Step right into the puddle before you use the {item:7766} (too far away and it refuses). Filling it calls a hostile {npc:3456} (level 20): kill it, and watch for the quilboar hunter by the pond, who may start shooting afterwards."] = "{npc:5899}的小屋下方的泥水塘。使用{item:7766}前要先踏进泥水里（离得太远它会拒绝）。装满会召来一个敌对的{npc:3456}（20级）：杀掉它，同时留意水塘边的野猪人猎人，之后他可能会开始射击。",
	["The right fountain stands in a ring of standing stones on the island of the small green lake south of {area:415}, west of Lake Mystral (not the island in Lake Mystral itself). From the {zone:1413} take the road north through the {area:1703} and on west. Water elementals and walking treants guard the lake and root you in place; an elite {npc:12836} roams {zone:1440} and can pass close by. Use the {item:7767} beside the fountain."] = "正确的喷泉在{area:415}南边、米斯特拉尔湖以西的小绿湖岛上立石环中（不是米斯特拉尔湖里的那座岛）。从{zone:1413}沿路向北穿过{area:1703}，再往西走。水元素和会行走的树人守着湖泊，会把你定在原地；一个精英{npc:12836}在{zone:1440}游荡，可能会靠近。在喷泉旁使用{item:7767}。",
	["The {item:5177} that lets you place water totems, and {spell:5394} with it."] = "让你能放置水图腾的{item:5177}，以及随之而来的{spell:5394}。",
	["The {npc:5895}"] = "纯净的{npc:5895}",
	["The {object:107045}"] = "{object:107045}",
	["The {object:107045} stands in the middle of {area:272}, just outside the church. From the {zone:1413}: the zeppelin from {zone:1454} to {zone:1420}, then south past the {zone:1458} and through {zone:1421} (or fly once you have the {area:272} flight path). {area:287} is contested: Alliance players may attack. Stand beside the well and use the {item:7768}."] = "{object:107045}位于{area:272}中央、教堂外。从{zone:1413}出发：坐飞艇从{zone:1454}到{zone:1420}，然后向南经过{zone:1458}，穿过{zone:1421}（有了{area:272}的飞行点时可以直接飞过去）。{area:287}是争夺区域：联盟玩家可能会攻击。站在井边使用{item:7768}。",
	["The {object:107046}"] = "{object:107046}",
	["The {object:113791}"] = "{object:113791}",
	["the {item:7810}, for {npc:5901}"] = "{item:7810}，交给{npc:5901}",
	["{item:6637}, beside the standing stone"] = "{item:6637}，在立石旁",
	["{item:7766}, standing in the puddle"] = "{item:7766}，站在泥水中",
	["{item:7767}, beside the fountain"] = "{item:7767}，在喷泉旁",
	["{item:7768}, beside the well"] = "{item:7768}，在井旁",
	["{npc:5899} lives in the southern {zone:1413}, south of {area:378}: her hut sits on a hilltop of {area:1701} with a spinning windmill beside it, and the way up is the ridge by the lone tree. Quilboar camp all around the hill; Stormhides, thunderhawks and hyenas roam the plains on the way."] = "{npc:5899}住在{zone:1413}南部、{area:378}以南：她的小屋在{area:1701}的一座山顶上，旁边有转动的风车，上山的路是孤树旁的山脊。山丘周围到处是野猪人营地；途中的平原上有风暴皮野猪人、雷鹰和鬣狗游荡。",
	["{npc:5901} hands you the {item:6637} and the {item:7811}: take everything she offers before you leave for Silverpine, or you will be back for more."] = "{npc:5901}会给你{item:6637}和{item:7811}：出发去银松森林前把她给的东西全拿上，否则你还得再跑一趟。",
	["{npc:5901} is not in {area:392}: take the small coast road south from {area:392} past the pirate camp and over a low hill; her fishing hut, with a shark strung up outside, stands by the water before the pirate ship. If you reach the ship you went too far."] = "{npc:5901}不在{area:392}：从{area:392}沿小海岸路向南海边走去，经过海盗营地，翻过一座矮丘；她的钓鱼小屋就在海盗船之前的水边，门外挂着一条鲨鱼。走到海盗船就说明走过头了。",
	["{npc:5901}: Narm's letter"] = "{npc:5901}：纳姆的信",
	["{npc:5901}: Swart's letter"] = "{npc:5901}：斯瓦特的信",
	["{npc:5901}: a new {quest:972}"] = "{npc:5901}：新的{quest:972}",
	["{npc:5901}: your {item:6637}"] = "{npc:5901}：你的{item:6637}",
	["{npc:5901}: {npc:5892}'s letter"] = "{npc:5901}：{npc:5892}的信",
	["{npc:5901}: {npc:5906}' letter"] = "{npc:5901}：{npc:5906}的信",
	["{npc:5901}: {spell:5394} and your {item:5177}"] = "{npc:5901}：{spell:5394}和你的{item:5177}",
	["{quest:63} (Horde)"] = "{quest:63}（部落）",
}

G["forever/class/shaman/darkreaver"] = {
	["200 Horde reputation"] = "200点部落声望",
	["A five-player dungeon event: {area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}. In the {object:179746}'s basement, first clear every mob in the room, then use the {item:18746} at its centre: four waves of spirits follow, each closing with an Aspect mini-boss (the first wave weak and slow, the rest elite). Fight in a corner so nothing else joins, and drink between waves: it is long. Then {npc:14516} (level 62 elite) appears: he Cleaves, casts {spell:686} and {spell:6958}, and Dominates a player's mind against the group. His head always drops."] = "一个五人地下城事件：{area:2057}位于{zone:1422}东南方岛屿城镇{area:2298}的地下。在{object:179746}的地下室里，先清光房间里所有小怪，然后在中央使用{item:18746}：随后会有四波精魂来袭，每波以一个化身小首领收尾（第一波又弱又慢，其余都是精英）。贴着墙角打，免得引到别的怪，每波之间喝水恢复：战斗很长。然后{npc:14516}（62级精英）现身：他会顺劈斩，施放{spell:686}和{spell:6958}，还会控制一名玩家的心智反过来对付队伍。他必掉脑袋。",
	["A {area:2057} fight at 60 for Horde reputation; the {item:20134} may be gone in Forever."] = "60级的{area:2057}战斗，奖励部落声望；{item:20134}在Forever可能已移除。",
	["At 58 {npc:13417}, the shaman trainer in the {object:172957}, asks for two rare diamonds; every Horde shaman goes to him. Skyborne: Forever's quest page lists this quest for Orcs, Tauren and Trolls only: ask before you buy the diamonds."] = "58级时，{object:172957}里的萨满训练师{npc:13417}要两颗稀有钻石；每个部落萨满都找他。空裔注意：Forever的任务页面将此任务列为仅兽人、牛头人和巨魔可接：买钻石前先确认。",
	["Both diamonds are rare: the auction house is the quick way. Miners find the {item:12800} in about one Thorium vein in a hundred (the Small Thorium Veins north of {area:2418} in the {zone:1428} respawn every five minutes). The {item:18335} drops from high-level elites at about one in a hundred, best from the rare elite Revanchion (about one in nine)."] = "两颗钻石都很稀有：拍卖行是最快的途径。矿工大约每一百座瑟银矿脉能挖出一颗{item:12800}（{zone:1428}{area:2418}以北的小型瑟银矿脉每五分钟刷新一次）。{item:18335}从高等级精英身上掉落，掉率约百分之一，最高的是稀有精英雷万奇恩（约九分之一）。",
	["Shaman"] = "萨满祭司",
	["Two diamonds"] = "两颗钻石",
	["he hands you the {item:18746}"] = "他会交给你{item:18746}",
	["{npc:13417}: 200 Horde reputation; the {item:20134} may be gone"] = "{npc:13417}：200点部落声望；{item:20134}可能已移除",
	["{quest:7668} needs level 60."] = "{quest:7668}需要60级。",
}

G["forever/class/shaman/spirit-totem"] = {
	["A five-player dungeon: needs a group of five, about level 50-55. Fly to {area:75} and ride east. The {area:1417} ({area:1477}) stands in the middle of the {area:74}: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. Two feathers of each colour, one from each of six elite troll mini-bosses (level 51-52) on the balconies around the temple's great round room, every kill, and each player on the quest loots their own: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Mijan heals the others ({spell:139}, a {npc:3560}): kill him first; Hukku summons guardians and throws Shadow Bolt Volleys."] = "一个五人地下城：需要五人小队，等级约50-55级。飞到{area:75}后向东骑。{area:1417}（{area:1477}）矗立在{area:74}中央：从废墟南侧的台阶上去，潜入被水淹没的大厅，向下游穿过去，沿台阶和通道一路向下走到传送门。每种颜色的羽毛要两根，分别出自神殿环形大厅周围阳台上的六个精英巨魔小首领（51-52级），每次击杀必掉，且每个接了任务的玩家各自拾取：加什尔和琥珀色的{npc:5716}、胡库和蓝色的米詹、佐洛和绿色的洛若。米詹会治疗其他首领（{spell:139}，一个{npc:3560}）：先杀他；胡库会召唤守卫并投掷暗影箭雨。",
	["At 50 {npc:13417}, the shaman trainer in the {object:172957}, asks for the four elements for {npc:6176}."] = "50级时，{object:172957}里的萨满训练师{npc:13417}要你为{npc:6176}收集四种元素。",
	["At 50 {npc:3032}, a shaman trainer on {area:1640} in {zone:1456}, asks for the four elements for {npc:6176}. Skyborne: Forever's quest page lists {quest:8410} and {quest:8412} for Orcs, Tauren and Trolls only; if {npc:3032} has nothing for you, {npc:6176}'s own {quest:8411} is open to every Horde race, but {quest:8412} after it may still turn you away."] = "50级时，{zone:1456}{area:1640}上的萨满训练师{npc:3032}要你为{npc:6176}收集四种元素。空裔注意：Forever的任务页面把{quest:8410}和{quest:8412}列为仅兽人、牛头人和巨魔可接；如果{npc:3032}不给你任务，{npc:6176}自己的{quest:8411}对所有部落种族开放，但后续的{quest:8412}仍可能拒绝你。",
	["Eight of each. Fly or ride to the {area:813} and on to the west edge of the {zone:1422}, north-west of {area:3197}: the Venom Mist Lurkers (level 50-51, they poison) give the {item:20610} and the Diseased Black Bears (level 51-52, {spell:3427}) the {item:20611}, one kill in five each; the two Carrion Vultures there drop either. The bigger Diseased Grizzlies and Plague Lurkers further east almost never drop them. A few bears and lurkers also roam south-east of {area:159} in Tirisfal."] = "每种要八个。飞或骑到{area:813}，再前往{zone:1422}西缘、{area:3197}西北方：毒雾潜伏者（50-51级，带毒）掉{item:20610}，染病黑熊（51-52级，{spell:3427}）掉{item:20611}，都是五次击杀出一件；那里的两种食腐秃鹫两种都会掉。更东边个头更大的染病灰熊和瘟疫潜伏者几乎不掉。提瑞斯法{area:159}东南方也有少量熊和潜伏者游荡。",
	["Experience and gold"] = "经验和金币",
	["Experience and gold at 50, ending in the {area:1417}; the Classic item choice may be gone in Forever."] = "50级的经验和金币奖励，任务链在{area:1417}收尾；经典旧世的物品选择奖励在Forever可能已移除。",
	["One each of {item:7069}, Fire, Earth and Water; all four trade, so the auction house is quickest. To farm them, {zone:1417} has the exiles near {area:320} (level 38-39, about one kill in eight to ten, respawn under seven minutes): Thundering Exiles south-east of it (air), Rumbling Exiles south-west (earth), Burning Exiles far to the north-west (fire), and the {npc:2794} far to the south-west (water, about one in seven). Water comes easier from the Patches of Elemental Water in {zone:1447} (two in five) or {npc:14269} by {area:69} in Redridge."] = "{item:7069}、火焰、大地、流水各一份；四种都可以交易，所以拍卖行最快。要刷的话，{zone:1417}{area:320}附近有流放者元素（38-39级，约八到十次击杀出一件，刷新不超过七分钟）：东南方的雷霆流放者（空气）、西南方的轰鸣流放者（大地）、远西北方的燃烧流放者（火焰），以及远西南方的{npc:2794}（流水，约七分之一）。流水更容易从{zone:1447}的元素之水洼（五分之二）或赤脊山{area:69}旁的{npc:14269}获得。",
	["Shaman"] = "萨满祭司",
	["Spider eye and bear claw"] = "蜘蛛眼和熊爪",
	["The four elements"] = "四种元素",
	["The {area:1417}"] = "{area:1417}",
	["{item:20606}: Gasher, {npc:5716}"] = "{item:20606}：加什尔、{npc:5716}",
	["{item:20607}: Hukku, Mijan"] = "{item:20607}：胡库、米詹",
	["{item:20608}: Zolo, Loro"] = "{item:20608}：佐洛、洛若",
	["{item:7067}: Rumbling Exiles"] = "{item:7067}：{npc:2592}",
	["{item:7068}: Burning Exiles"] = "{item:7068}：{npc:2760}",
	["{item:7069}: Thundering Exiles"] = "{item:7069}：{npc:2762}",
	["{item:7070}: the {npc:2794}, or {zone:1447}'s water patches"] = "{item:7070}：{npc:2794}，或{zone:1447}的水洼",
	["{npc:6176} camps in the ruins of the east of {zone:1416}: from {area:272} follow the river east of town north into the hills."] = "{npc:6176}在{zone:1416}东部的废墟中扎营：从{area:272}沿城镇东侧的河流向北进入丘陵。",
	["{npc:6176}: the old item choice may be gone, count on the experience"] = "{npc:6176}：旧版物品选择奖励可能已移除，指望经验就好",
	["{quest:8412} and {quest:8413}"] = "{quest:8412}与{quest:8413}",
}

G["forever/class/warlock/felhunter-horde"] = {
	["At 30 {npc:5675}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}. Take only one {quest:2996}: if {npc:6251} offers nothing, drop the duplicate from your log."] = "30级时，{object:36082}里的{npc:5675}会派你去找{area:392}的{npc:6251}。从{zone:1420}的飞艇飞往{zone:1411}。只接一个{quest:2996}：如果{npc:6251}不提供任务，就把多出来的那个从日志里放弃。",
	["At 30 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:6251} in {area:392}."] = "30级时，{object:172982}下方{object:172960}的{npc:5875}会让你去{area:392}找{npc:6251}。",
	["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "回到{area:392}找{npc:6251}。接受任务后，他会画出召唤法阵，他的助手们会在上面引导一个更大的法阵：在塔里等到两个法阵都完成。然后在法阵上使用{quest:1804}。地狱犬（30级，非精英）会沉默并吸取法力，两分钟后消失：先放出你的虚空行者，立刻挂上持续伤害，让虚空行者负责扛。如果你死了或它赢了，放弃{quest:1795}，再从{npc:6251}那里重新接。留着那本书：{npc:6251}会把它收回去。",
	["Back to {npc:6293}"] = "回到{npc:6293}",
	["Felhunter (Horde)"] = "地狱猎犬（部落）",
	["Rods of Channeling"] = "导能魔棒",
	["Rods of Channeling, from the Dragonmaw casters"] = "导能法杖，由龙喉施法者掉落",
	["Summoned Felhunter"] = "召唤的地狱犬",
	["The Dragonmaw hold {area:1036} in the hills east of the road through the {zone:1437}, south of the {area:881} you cross from {zone:1417}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "龙喉的据点{area:1036}位于穿过{zone:1437}那条路以东的山丘里，在你从{zone:1417}穿过来的{area:881}以南。只有施法者掉导能法杖，大约五只掉四只：白骨守卫（27级，带骷髅宠物）和暗影守卫（28级）。中央灵魂医者以北的一条陡峭小路能直接进营地，绕过大部分战士。",
	["The centaur cave opens in the cliffs north of {area:484}. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "半人马的洞穴在{area:484}以北的崖壁上。进去后每个岔路都往右，穿过小瀑布旁的水池，打开靠墙在大箱子旁边的小黑箱：大的那个是错的。只有接了任务才能打开它。出来时半人马会在你身后刷新。",
	["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "地狱猎犬，对付施法者的恶魔，外加一个用来装灵魂碎片的{item:22244}。",
	["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "那本书是一本灰蓝色的小书，躺在{area:271}西南海岸一处鱼人营地的沙地上，靠近水边。六七只鱼人守着它，水下还藏着一批：它们成群出现，所以恐惧一只，让虚空行者对付其余的。走到水边才能点它；从山坡上点会被木箱挡住光标。",
	["Warlock"] = "术士",
	["{area:392}'s flight point is a short flight from {zone:1454}'s. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6293} in the {zone:1458}."] = "{area:392}的飞行点离{zone:1454}的飞行点只有一小段航程。{npc:6251}站在镇上的山丘上，工程师小屋后面，他那座小塔旁边；{npc:6266}和两名助手跟他在一起。他派你去找{zone:1458}的{npc:6293}。",
	["{item:6931}, from the {quest:1803} on the sand"] = "{item:6931}，出自沙地上的{quest:1803}",
	["{item:6997}, in the {object:92423}"] = "{item:6997}，在{object:92423}里",
	["{npc:6293} is in the {object:36082} of the {zone:1458}. He wants two lost pieces of the {quest:1801}: one on the {area:287} coast, one in {zone:1441}."] = "{npc:6293}在{zone:1458}的{object:36082}里。他需要{quest:1801}的两件失落部件：一件在{area:287}海岸，一件在{zone:1441}。",
	["{npc:6293} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "{npc:6293}把书拼合起来，交给你{item:7006}：留着它，{npc:6251}会连同导能法杖一起收走。",
	["{quest:1804}, on the circle"] = "{quest:1804}，在法阵上",
}

G["forever/class/warlock/imp-horde"] = {
	["Imp (Horde)"] = "小鬼（部落）",
	["Rattlecage Skulls"] = "响骨骷髅头",
	["The Rattlecage Skeletons (level 2-3) stand around the old smithy buildings just north of {area:154}, often right against the walls. Four kills in five drop a skull, so plan on about five; twenty of them spawn there and each comes back after five minutes."] = "响骨骷髅（2-3级）聚集在{area:154}北边废弃的铁匠铺周围，常常紧贴墙边。五次击杀中有四次会掉骷髅头，所以按五次计划；那里一共刷二十只，每只五分钟后回来。",
	["The {quest:1485} (level 3-4) swarm the {area:365}, the cave north of the Den, inside and around its mouth. Almost every kill drops a head (80%), so about eight kills does it; they throw small fireballs, so pull them one at a time. They respawn in just over three minutes. Other classes hunt the same imps for their own {quest:1485} quest."] = "{quest:1485}中要求的魔仆（3-4级）成群盘踞在{area:365}，也就是巢穴北边的洞穴，洞内和洞口周围都有。几乎每只都掉头颅（80%），所以大约八只就够了；它们会扔小火球，所以一次拉一只。三分钟多一点就会刷新。其他职业也会为了自己的{quest:1485}任务猎杀同样的魔仆。",
	["Vile Familiar Heads"] = "邪恶魔仆头颅",
	["Warlock"] = "术士",
	["Your first demon at level 1-4: the imp, with a starter blade or staff for Orcs and Trolls."] = "1-4级时的第一个恶魔：小鬼，兽人和巨魔还会拿到一把起始剑或法杖。",
	["Your first letter ({item:9578}, from {npc:1569} after The Mindless Ones) points you to Maximillion, the warlock trainer in {area:154}. {npc:5667} waits inside the building beside him and asks for three Rattlecage Skulls."] = "你的第一封信（{item:9578}，完成前置任务后由{npc:1569}给你）指向{area:154}的术士训练师马克西米利安。{npc:5667}就在他旁边的屋子里等你，要三个响骨骷髅头。",
	["Your first letter ({item:9579} for Orcs, {item:282346} for Trolls, from Gornek after Cutting Teeth) points you to Nartok, the warlock trainer in the Den. {npc:5765} stands just outside the Den in the {area:363} and asks for six Vile Familiar Heads."] = "你的第一封信（兽人是{item:9579}，巨魔是{item:282346}，完成前置任务后由格奈克给你）指向巢穴里的术士训练师纳托克。{npc:5765}就站在巢穴外{area:363}，要六颗邪恶魔仆头颅。",
	["{npc:5667} (Undead)"] = "{npc:5667}（亡灵）",
	["{npc:5667} teaches you {spell:688} when you hand in the skulls: summon it right away, it costs nothing and fights beside you."] = "交上骷髅头后{npc:5667}会教你{spell:688}：马上召唤它，不消耗任何东西，还会和你并肩作战。",
	["{npc:5765} (Orcs and Trolls)"] = "{npc:5765}（兽人与巨魔）",
	["{npc:5765} teaches you {spell:688} when you hand in the heads: summon it right away, it costs nothing and fights beside you. Then speak with {npc:3145} a few steps away for a starter weapon."] = "交上头颅后{npc:5765}会教你{spell:688}：马上召唤它，不消耗任何东西，还会和你并肩作战。然后再走几步找{npc:3145}领起始武器。",
}

G["forever/class/warlock/incubus-horde"] = {
	["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers start these demons, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one; this guide follows whichever {quest:1472} you took. {npc:5909} offers both of {zone:1454}'s branches: take both."] = "20级时，{object:172982}下方{object:172960}里的{npc:5875}让你去找几步之外的{npc:5909}。开启这两个恶魔任务的训练师有两位：这里的{npc:5875}和{zone:1458}的{npc:5675}，你只能选一个；本攻略适用于你所接的那条{quest:1472}路线。{npc:5909}提供{zone:1454}的两条分支：都接。",
	["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "20级：魅魔和Forever新增的雄性双子——男魅魔，各自附带一个装碎片的灵魂袋。",
	["Back to {npc:5675} with Dalin's and Corma's hearts. He hands you the {item:6286}: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, {npc:5675} takes them back."] = "带着达林和科尔玛的心脏回到{npc:5675}处。他把{item:6286}交给你：走到他下方的召唤法阵，站上去使用心脏。先召唤你的虚空行者，并把战斗控制在法阵上，否则守卫可能杀掉她且不算你的击杀。如果她赢了，再用一次心脏；留着心脏，{npc:5675}会收回。",
	["Back to {npc:5675} with the lovers' hearts, then place the {item:190181} on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: {npc:5675} takes them back."] = "带着恋人的心脏回到{npc:5675}处，然后把{item:190181}放到同一个法阵上，击败它们召唤出的男魅魔（20级，非精英；会魅惑你）。留着心脏：{npc:5675}会收回。",
	["Back to {npc:5875} with the pendant. He hands you {item:6626}: take it across the {object:172960} to {npc:3216}'s tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: {npc:5875} takes it back."] = "带着坠饰回到{npc:5875}处。他把{item:6626}交给你：拿着它穿过{object:172960}到{npc:3216}的帐篷，站上紫色法阵并使用。先召唤你的虚空行者让它抗住：魅魔（20级，非精英）会魅惑还会鞭打；持续给她挂持续伤害法术。如果她赢了，再用一次坠饰。留着坠饰：{npc:5875}会收回。",
	["Back to {npc:5875} with the scarf, then use the {item:190232} on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: {npc:5875} takes it back."] = "带着围巾回到{npc:5875}处，然后在尼鲁帐篷里的同一个法阵上使用{item:190232}，让你的虚空行者抗住，击败它召唤出的男魅魔（20级，非精英）。留着围巾：{npc:5875}会收回。",
	["Corma Villard"] = "科尔玛·维拉德",
	["Corma Villard (level 22, not elite; Comar in older records) wanders the north of the {zone:1437} just past the {area:881}, to the right as you come off the bridge. From the {zone:1458} head through {area:287} and {zone:1417}, where the mobs are 30 and up. Attacking her flags you for PvP."] = "科尔玛·维拉德（22级，非精英；旧资料中写作科马尔）在{zone:1437}北部{area:881}以北游荡，下桥后向右转。从{zone:1458}出发要穿过{area:287}和{zone:1417}，那里的怪物都在30级以上。攻击她会开启你的PvP状态。",
	["Corma's Heart"] = "科尔玛的心脏",
	["Silverpine hearts"] = "银松心脏",
	["Succubus and Incubus (Horde)"] = "魅魔与男魅魔（部落）",
	["Summoned Incubus"] = "被召唤的男魅魔",
	["Summoned Succubus"] = "被召唤的魅魔",
	["Take the road west from the {area:380} into {zone:1442} and, just past the border, the faint trail up to the left (south): {area:2539} cannot be reached from the main road. {npc:4197} hands you her draught for {npc:5911}."] = "从{area:380}沿大路向西进入{zone:1442}，刚过边界就走左边（南边）那条模糊的上山小径：{area:2539}无法从主路到达。{npc:4197}把她调制的药剂交给你带给{npc:5911}。",
	["Warlock"] = "术士",
	["the incubus"] = "男魅魔",
	["the succubus"] = "魅魔",
	["{area:422} lies in southern {zone:1440}, south-west of {area:431}. The Shadethicket Stone Movers and Bark Rippers (level 25-26) around the lake drop the {item:190232} about one time in twenty, and the lone {npc:3931} (30) can drop it too: plan on a good number of kills, so come at 25 or later (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in {zone:1440}. They respawn in five minutes."] = "{area:422}在{zone:1440}南部、{area:431}西南方。湖边的影棚移石者和影棚裂皮者（25-26级）约每二十次击杀掉一次{item:190232}，落单的{npc:3931}（30级）也可能掉：预计要杀不少，所以25级或以后再来（Forever把这个任务调成了27级）；魅魔已经到手的话，可以留到你在{zone:1440}练到20多级时再做。它们五分钟刷新。",
	["{item:6286}, on the circle below {npc:5675}"] = "{item:6286}，在{npc:5675}下方的法阵上",
	["{item:6626}, on the circle in Neeru's tent"] = "{item:6626}，在尼鲁帐篷里的法阵上",
	["{npc:185333} (level 22) works as a tailor for the {area:279} wizards at {area:233}, in eastern Silverpine: the wizards around her are hostile. {npc:5682} (level 20, not elite) patrols near the {area:230} in the far south. Both are Alliance-friendly humans: attacking them can flag you for PvP. Each drops her or his heart."] = "{npc:185333}（22级）在银松森林东部的{area:233}给{area:279}的法师们当裁缝：她周围的法师是敌对的。{npc:5682}（20级，非精英）在最南边{area:230}附近巡逻。两人都是亲联盟的人类：攻击他们会开启你的PvP状态。各掉她或他的心脏。",
	["{npc:185334} (level 22) works in {area:392}, on the {zone:1413} coast, at one of two spots in town: take the zeppelin to {zone:1411} and head south, or fly from {zone:1454}. He is an Alliance-friendly human: attacking him can flag you for PvP."] = "{npc:185334}（22级）在{zone:1413}海岸的{area:392}干活，出没于镇上的两个地点之一：乘飞艇到{zone:1411}再向南走，或从{zone:1454}飞过去。他是亲联盟的人类：攻击他会开启你的PvP状态。",
	["{npc:185335}, at the circle below {npc:5675}"] = "{npc:185335}，在{npc:5675}下方的法阵处",
	["{npc:185335}, at the circle in Neeru's tent"] = "{npc:185335}，在尼鲁帐篷里的法阵处",
	["{npc:3363} keeps {object:173018} on the main street east of the {object:172960}. He asks you to look for his mate Krilge in {zone:1440}."] = "{npc:3363}在{object:172960}东边的大街上经营{object:173018}。他请你到{zone:1440}寻找他的伴侣克里尔格。",
	["{npc:3464} waits in front of the inn at the {area:380}. He sends you on to {npc:4197} at {area:2539}, in {zone:1442}."] = "{npc:3464}在{area:380}的旅店门前等你。他让你去{zone:1442}的{area:2539}找{npc:4197}。",
	["{npc:5910} lives in a hut up on the cliffs on the west side of the city, above the {object:172982}: climb the wind rider tower, cross the bridge at its top to the west and turn right off it. She sends you to the {area:380}."] = "{npc:5910}住在城西悬崖上的一座小屋里，就在{object:172982}上方：爬上双足飞龙塔，在塔顶过桥向西，下桥后右转。她让你去{area:380}。",
	["{npc:5911} stands at {area:378}, south down the road from the {area:380}. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for {npc:5875}. Keep it."] = "{npc:5911}站在{area:378}，从{area:380}沿路向南。他让你向北去关押多格兰的野猪人营地：认准两座小屋并排的那座营地，它西北方还有一座小屋分开的诱饵营地。偶尔有一只稀有的22级精英野猪人守着小屋：让虚空行者先上，必要时牺牲它，然后与多格兰交谈。他给你一个交给{npc:5875}的坠饰。收好它。",
	["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} close by. {npc:5693} shows you an image of each quarry and offers both branches: take both."] = "{object:1661}的版本，适用于接了{npc:5675}的{quest:1472}而非{npc:5875}的术士。20级时，{object:36082}里的{npc:5675}让你去找附近的{npc:5693}。{npc:5693}给你看每个猎物的影像，并提供两条分支：都接。",
	["{quest:1474}: succubus ({zone:1458})"] = "{quest:1474}：魅魔（{zone:1458}）",
	["{quest:1513}: succubus ({zone:1454})"] = "{quest:1513}：魅魔（{zone:1454}）",
	["{quest:65597}: incubus ({zone:1458})"] = "{quest:65597}：男魅魔（{zone:1458}）",
	["{quest:65604}: incubus ({zone:1454})"] = "{quest:65604}：男魅魔（{zone:1454}）",
}

G["forever/class/warlock/voidwalker-horde"] = {
	["At 10 {npc:3294} sends you to {npc:5875}. He stands outside at the back of {area:362}'s barracks, the big building on the east side of town (not the inn), a few steps from {npc:3172}, the warlock trainer. {npc:5875} stands with the senior warlocks in the {object:172960}, the cavern under {zone:1454}'s {object:172982}. An Orc or Troll leveling in {zone:1420} can take the {zone:1458} version from {npc:5724} in {area:159} instead (the {zone:1458} steps below): you can do only one of the two."] = "10级时{npc:3294}让你去找{npc:5875}。他站在{area:362}兵营的后门外，兵营是镇子东侧的大建筑（不是旅店），离术士训练师{npc:3172}只有几步。{npc:5875}与资深术士们一起站在{object:172960}里，即{zone:1454}{object:172982}下方的洞窟。在{zone:1420}练级的兽人或巨魔也可以改从{area:159}的{npc:5724}那里接{zone:1458}版本（下面列出的{zone:1458}步骤）：两者只能做一个。",
	["At 10 {npc:5724}, upstairs in the {area:2119} in {area:159}, sends you to {npc:5675}: the version for the Undead, and for Orcs and Trolls who level in {zone:1420} instead of taking {npc:5875}'s. {npc:5675} stands in the {zone:1458}'s {object:36082}, by the Temple of the Damned."] = "10级时，{area:159}{area:2119}楼上的{npc:5724}让你去找{npc:5675}：这个版本面向亡灵，以及在{zone:1420}练级、不接{npc:5875}版本的兽人和巨魔。{npc:5675}站在{zone:1458}的{object:36082}里，就在诅咒神庙旁。",
	["Back to {npc:5675}. He hands you the {item:6284}: go down the stairs from him to the summoning circle and use them while standing on it. Fight the voidwalker (level 10, not elite) on the circle: if it wanders off, the city guards may kill it and the kill does not count. {spell:14868}, Corruption and {spell:348} with your imp tanking bring it down; it hits harder below 30%. If you lose, use the runes again. Keep the runes: {npc:5675} takes them back."] = "回到{npc:5675}处。他把{item:6284}交给你：从他那里下楼梯到召唤法阵，站在法阵上使用符文。在法阵上与虚空行者（10级，非精英）战斗：如果它跑出法阵，城市守卫可能杀掉它且不算你的击杀。让你的小鬼抗住，用{spell:14868}、腐蚀术和{spell:348}把它打死；它血量低于30%时伤害更高。如果你输了，再用一次符文。留着符文：{npc:5675}会收回。",
	["Back to {npc:5875}. He hands you the {item:7464}: take them across the {object:172960} to {npc:3216}'s tent, stand on the purple circle on its floor and use them. The voidwalker (level 10, not elite) hits hard at 30% health and leaves after three minutes, so start at once: {spell:14868}, Corruption and {spell:348}, send your imp in, and Fear it when you need a breather. If it beats you or leaves, the glyphs are not used up: use them again on the circle. Keep the glyphs: {npc:5875} takes them back."] = "回到{npc:5875}处。他把{item:7464}交给你：拿着它们穿过{object:172960}到{npc:3216}的帐篷，站在帐内的紫色法阵上使用。虚空行者（10级，非精英）血量30%时打得很疼，且三分钟后就会消失，所以立刻开打：{spell:14868}、腐蚀术和{spell:348}，派小鬼上，需要喘息时就恐惧它。如果它击败你或消失了，铭文不会被消耗：在法阵上再用一次。留着铭文：{npc:5875}会收回。",
	["Summoned Voidwalker"] = "被召唤的虚空行者",
	["The Scarlet tower stands in the fields west of the {zone:1458}'s ruins (not the tower near {area:154}). The grimoire is in the small chest on the ground floor, under the stairs; ignore the chest upstairs. {npc:1662} (level 9) and a {npc:1537} guard it: kill them, or Fear the zealot while you deal with Perrine. Scarlet Missionaries and Zealots (level 7-9) walk the fields around the tower. The chest is back three seconds after anyone opens it."] = "血色十字军的塔楼矗立在{zone:1458}废墟以西的田野里（不是{area:154}附近那座）。魔典在一楼楼梯下的小箱子里；楼上那个箱子不用管。{npc:1662}（9级）和一名{npc:1537}守着它：杀掉他们，或者在你对付佩林时恐惧狂热者。血色传教士和血色狂热者（7-9级）在塔周围的田野里走动。任何人开过箱子三秒后它就会刷新。",
	["Voidwalker (Horde)"] = "虚空行者（部落）",
	["Warlock"] = "术士",
	["Your tank demon at 10: the voidwalker, after a stolen book and a fight at a summoning circle."] = "10级的坦克恶魔：虚空行者——先偷一本书，再在召唤法阵上打一场。",
	["{area:817} is the cave in the cliffs just east of {zone:1454}'s gate. Inside, take the right-hand ramp up and follow it to the top: the {object:58595} sits on that upper ledge, which cannot be reached from the lower floor. The cave is packed with Burning Blade Apprentices and Fanatics (level 9-11, many with voidwalkers) that respawn quickly, and {npc:3204}, a level 14 Burning Blade warlock, stands near the stash. Old notes call him elite; Forever's data lists him as normal. At 10 it is hard alone: pull one pack at a time and Fear the extra, wait for 11, or go with a friend. The stash always holds the tablet."] = "{area:817}是{zone:1454}城门正东悬崖上的洞穴。进洞后走右侧的坡道一路向上到顶：{object:58595}就在上层岩台上，从下层走不上去。洞里挤满了火刃学徒和火刃狂热者（9-11级，很多带着虚空行者），刷新很快；{npc:3204}是一名14级火刃术士，就站在储物点旁。旧资料把他标为精英；Forever的数据把他列为普通怪。10级时单人很难打：一次只拉一波并恐惧多余目标，或者等到11级，或者找个朋友一起去。储物点必定藏有那块石板。",
	["{item:6284}, on the circle below {npc:5675}"] = "{item:6284}，在{npc:5675}下方的法阵上",
	["{item:6285}, in {object:37098}"] = "{item:6285}，在{object:37098}里",
	["{item:6535}, in the {object:58595}"] = "{item:6535}，在{object:58595}里",
	["{item:7464}, on the circle in Neeru's tent"] = "{item:7464}，在尼鲁帐篷里的法阵上",
	["{npc:5724}, upstairs in the {area:159} inn"] = "{npc:5724}，在{area:159}旅店楼上",
	["{quest:1506} (Orcs and Trolls)"] = "{quest:1506}（兽人和巨魔）",
}

G["forever/class/warrior/brutal-armor"] = {
	["At 20, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6394} in {area:378}."] = "20级时，{zone:1456}的战士训练师{npc:3041}会让你去找{area:378}的{npc:6394}。",
	["At 20, {npc:3354} in the {object:172958} sends you to {npc:6394} in {area:378}."] = "20级时，{object:172958}的{npc:3354}会让你去找{area:378}的{npc:6394}。",
	["At 20, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6394} in {area:378}."] = "20级时，{zone:1458}的战士训练师{npc:4595}会让你去找{area:378}的{npc:6394}。",
	["Back to {npc:5878} on {area:1699}. {quest:1848} is the first piece; he then sends you to three crafters, one per piece: take all three."] = "回去找{area:1699}上的{npc:5878}。{quest:1848}是第一部分；之后他会派你去找三个工匠，每人负责一件：三个都接。",
	["Fly to {area:378}. {npc:6394} stands in the hut with the leatherworking and tailoring trainers."] = "飞到{area:378}。{npc:6394}和制皮、裁缝训练师一起待在那间小屋里。",
	["Four armor pieces at 30 (hauberk, helm, gauntlets, legguards) and a shield on the way."] = "30级的四件护甲（锁甲、头盔、护手、护腿），途中还有一面盾牌。",
	["Hillsbrad Miners"] = "{npc:2269}",
	["Iron Bars"] = "铁锭",
	["Iron Bars: {npc:8673}"] = "铁锭：{npc:8673}",
	["Roogug in {area:1717}"] = "{area:1717}中的鲁古格",
	["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, his guards come with him. Inside take the left path at the first fork, cross the vine bridge over the pig pens, go past the room with the big cauldron: he waits in the room on the right. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "鲁古格是{zone:1413}南端地下城{area:1717}里的精英野猪人（28级）；这是五人地下城：需要五人小队，他的卫兵会跟他一起来。进去后在第一个岔路走左边，穿过猪圈上方的藤桥，经过有大锅的房间：他在右边的房间里等着。他会施放{spell:403}并召唤大地轰响者。药瓶必掉。",
	["Take the zeppelin from {zone:1454} to {zone:1420}; {npc:6411} works in the {zone:1458}'s {object:36078}. She wants 8 Sturdy Dragonmaw Shinbones."] = "从{zone:1454}乘飞艇到{zone:1420}；{npc:6411}在{zone:1458}的{object:36078}里工作。她需要8根结实的龙喉胫骨。",
	["The Dragonmaw orcs (level 26-30) camp in the middle of the {zone:1437}; from {area:321} in Arathi head south over the {area:881} ({area:150} is Alliance). Every Raider, Swamprunner, Centurion, Shadowwarder and Bonewarder drops a {item:7131}: right-click it to test it, and about one in four comes out sturdy, the rest break, so expect 30 or more kills for 8. You can test while moving or fighting. The orcs run for help at 15%; Raiders net you, Centurions shield-bash, Shadowwarders cast {spell:686}, Bonewarders raise skeletons."] = "龙喉兽人（26-30级）在{zone:1437}中部扎营；从阿拉希的{area:321}向南翻过{area:881}（{area:150}属于联盟）。每个袭击者、沼泽行者、百夫长、守影者和守骨者都会掉落{item:7131}：右键点击来检验，大约四分之一是结实的，其余会断裂，所以8根预计要杀30只以上。移动或战斗时也能检验。兽人血量到15%会跑去求援；袭击者会用网，百夫长会盾击，守影者会施放{spell:686}，守骨者会召唤骷髅。",
	["The satyrs of {area:430}, north-east of {area:431} ({area:429}, level 28-30), and the Felmusk satyrs north-west of the post (25-27) drop a hoof four kills in five. A {area:429} satyr at 15% health may cast {spell:6925} and heal to full: finish it fast or stun it. Hellcallers throw Fireballs from 40 yards; Felmusk satyrs reek in melee and run for help at 15%."] = "{area:431}东北{area:430}的萨特（{area:429}，28-30级）以及哨站西北的邪麝萨特（25-27级）五次击杀有四次掉落蹄子。{area:429}的萨特血量到15%时可能施放{spell:6925}并回满血：快速解决或击晕它。地狱召唤者会从40码外扔火球；邪麝萨特近战很臭，血量到15%会跑去求援。",
	["The {npc:6167} (level 28, not elite, larger than the young ones around her) roams the south edge of the {area:465} in south-west Stonetalon, near the road to {zone:1443}. She is the only one: she returns 5 minutes after dying and drops the {item:6840} four kills in five. She spits {spell:3396} from 30 yards."] = "{npc:6167}（28级，非精英，比周围的小家伙大）在石爪山西南部{area:465}的南缘游荡，靠近通往{zone:1443}的路。只有这一只：死亡后5分钟重新出现，五次击杀有四次掉落{item:6840}。她会从30码外喷吐{spell:3396}。",
	["Warrior"] = "战士",
	["You have 30 minutes, and each {item:7119} rots 15 minutes after you loot it, so take the quest only when ready (logging out does not stop the clock). The Silithid Mounds dot the {area:390} south of {area:378}; every silithid drops an antenna. Creepers (level 20-21) and Grubs are the easiest: Swarmers (21-22) call small swarms and Creepers lay eggs that hatch adds. The eastern part of the field has plenty of Creepers. {item:7120}, a shield, is the reward."] = "你有30分钟，每个{item:7119}在你拾取后15分钟就会腐烂，所以准备好再接任务（下线不会停表）。异种虫巢散布在{area:378}南边的{area:390}上；每只异种虫都会掉落一根触角。爬行者和幼虫最容易：群集者（21-22级）会召唤小虫群，爬行者会产卵孵化出援兵。场地东部的爬行者很多。奖励是一面盾牌{item:7120}。",
	["You need 10 Iron Bars. Miners smelt them from {item:2772} (one ore a bar, {spell:3307} at {skill:186} 125); everyone else buys them at the auction house in {zone:1454}."] = "你需要10块铁锭。矿工用{item:2772}熔炼（一块矿石一块锭，{skill:186}技能125时用{spell:3307}）；其他人则在{zone:1454}的拍卖行购买。",
	["You need 10 {item:7127}. The Hillsbrad Miners (level 26-27) work the mine in the hills west of {area:271} and drop the azurite four kills in five; they fight in {spell:71}, sunder your armor and run for help at 30% health. Fly to {area:272} and head south-west."] = "你需要10个{item:7127}。希尔斯布莱德矿工（26-27级）在{area:271}西面山中的矿洞里干活，五次击杀有四次掉落蓝铜矿；他们会用{spell:71}战斗，破你的甲，并在血量30%时跑去求援。飞到{area:272}，然后往西南走。",
	["You need 15 Smoky Iron Ingots. The {area:2160} lies at the east end of {area:461}, east of {area:460}; every Windshear kobold (level 19-23) drops an ingot four kills in five. Stonecutters, Geomancers and Overlords run for help when low; Geomancers cast {spell:116}."] = "你需要15块烟熏铁锭。{area:2160}位于{area:461}的东端、{area:460}以东；每只风剪狗头人（19-23级）五次击杀有四次掉落一块铁锭。切石者、地卜师和霸主在血量低时会跑去求援；地卜师会施放{spell:116}。",
	["from the Dragonmaw orcs: right-click to test it"] = "来自龙喉兽人：右键点击检验",
	["{item:6840}, from the {npc:6167}"] = "{item:6840}，来自{npc:6167}",
	["{item:6841}, from Roogug"] = "{item:6841}，来自鲁古格",
	["{item:7119}, from the silithid"] = "{item:7119}，来自异种虫",
	["{item:7126}, from the Windshear kobolds"] = "{item:7126}，来自风剪狗头人",
	["{item:7127}, from the Hillsbrad Miners"] = "{item:7127}，来自希尔斯布莱德矿工",
	["{npc:5878}'s hut sits on top of {area:1699}, east of the {area:380}: climb the broad ridge on the north or east side. {quest:1838} is a level 30 quest; take it now and gather on the way. {item:7587} list where each material comes from."] = "{npc:5878}的小屋位于{area:1699}顶上、{area:380}以东：从北侧或东侧的宽山脊爬上去。{quest:1838}是30级任务；现在就接，路上顺便收集。{item:7587}列出了每种材料的来源。",
	["{npc:6408} is in {area:367} on the {zone:1411} coast. He wants 7 Uncloven Satyr Hooves."] = "{npc:6408}在{zone:1411}海岸的{area:367}。他需要7只未分裂的萨特之蹄。",
	["{npc:6410} works on {zone:1456}'s lowest level, close to the blacksmith."] = "{npc:6410}在{zone:1456}的最下层工作，靠近铁匠。",
}

G["forever/class/warrior/heirloom-weapon"] = {
	["At 10, {npc:2131}, the warrior trainer inside the inn of {area:159}, sends you to {npc:1496} by the graveyard on {area:159}'s west edge. This road and {npc:5810}'s exclude each other: drop {quest:1505} or {quest:1498} from your log if you hold one."] = "10级时，{area:159}旅店里的战士训练师{npc:2131}派你去{area:159}西缘墓地旁的{npc:1496}。这条路线与{npc:5810}的路线互斥：任务栏里若有{quest:1505}或{quest:1498}，放弃其中一个。",
	["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "10级时，{npc:252377}和训练师们站在{area:16638}西门旁。邪教徒{npc:257196}在{area:16629}拿着她家族的盾牌。",
	["At 10, {npc:3063}, the warrior trainer of {area:222}, sends you to {npc:5810} in the {zone:1413}. {npc:3041} in {zone:1456} offers it too."] = "10级时，{area:222}的战士训练师{npc:3063}派你去{zone:1413}的{npc:5810}。{zone:1456}的{npc:3041}也提供这个任务。",
	["At 10, {npc:3169}, the warrior trainer in the barracks of {area:362}, sends you to {npc:5810} in the {zone:1413}. Sorek in {zone:1454}'s {object:172958} offers it too. Any Horde warrior may take one of the two roads, never both: heading to {zone:1420} at 10 anyway? {npc:2131} in {area:159}'s inn offers the other: one fight by {area:159}'s graveyard for the same stance, then the Agamand crypt for an heirloom weapon."] = "10级时，{area:362}兵营里的战士训练师{npc:3169}派你去{zone:1413}的{npc:5810}。{zone:1454}的{object:172958}里的索瑞克也提供这个任务。任何部落战士只能走两条路线中的一条，绝不能都走：10级反正要去{zone:1420}？{area:159}旅店里的{npc:2131}提供另一条：在{area:159}墓地旁打一场就能拿到同样的姿态，然后去阿加曼德墓穴拿传家宝武器。",
	["Back to {npc:1500}"] = "回到{npc:1500}那里",
	["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:5810}'s road below still gives a weapon later, once you reach Kalimdor."] = "回到{area:16638}找{npc:252377}。她教你{spell:71}，并给你{item:275290}，一面配合它使用的盾牌。下面{npc:5810}的路线在你到达卡利姆多后仍会给一把武器。",
	["Back to {npc:5810} under his tree west of {area:379}."] = "回到{npc:5810}身边，他在{area:379}以西的树下。",
	["Dillinger stands by the graveyard on {area:159}'s west edge. An Orc, Troll, Tauren or Skyborne who took {quest:1818} from {npc:2131} instead of {npc:5810}'s road is led through {area:159} from here."] = "迪林格站在{area:159}西缘的墓地旁。兽人、巨魔、牛头人或天裔如果在{npc:2131}那里接了{quest:1818}而不是走{npc:5810}的路线，就会从这里被引导穿过{area:159}。",
	["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "从{area:16638}向西北前往{area:16629}。{npc:257196}站在神殿通道的西侧，混在教派的守卫者、唤灵者和剑师中间：先一个一个拉掉他们，再动他。他掉落{item:263993}。",
	["Singed Scales in {area:369}"] = "{area:369}的烧焦的鳞片",
	["The four Agamand Weapon Racks are inside the {area:158} at the north end of {area:157}, north of {area:159}, one rack per room: one in the lowest room, two in the pair of rooms up the stairs, one in the room above those. The axe rack stands in a dark corner. The crypt's undead come in packs of three or more and return quickly; the ones in the top room are not linked. The axe, dagger and mace racks take 15 minutes to refill after someone loots them."] = "四个阿加曼德武器架在{area:157}北端的{area:158}内，位于{area:159}以北，每个房间一个：最低的房间一个，楼梯上那对房间两个，它们上面那间一个。斧架立在黑暗的角落。墓穴里的亡灵三只以上成群出现且回来得很快；顶层的那些不联动。斧、匕首和锤架被拾取后要15分钟才会补满。",
	["The {area:158}"] = "{area:158}",
	["The {object:58369} stands by a broken wagon in the Razormane camp north-west of {npc:5878}, north-east of the {area:380}. Two Razormanes guard it and their hunters pull more quilboar: clear them one at a time, then open the chest (it refills within seconds, so a friend can loot it too)."] = "{object:58369}立在{npc:5878}西北、{area:380}东北的钢鬃营地中一辆破车旁。两个钢鬃野猪人守着它，他们的猎人还会引来更多野猪人：一个一个清掉，然后打开箱子（几秒内就会补满，所以朋友也能拾取）。",
	["Ulag the Cleaver"] = "劈砍者乌拉格",
	["Warrior"] = "战士",
	["You need five Singed Scales. Thunder Lizards (level 9-10) and Lightning Hides (10-11) live down in the {area:369} crevasse in north-west {zone:1411}, south of {zone:1454}: from the {zone:1413} bridge turn left and follow the river north into it. Both drop a scale about four kills in five; both cast {spell:5401}."] = "你需要五个烧焦的鳞片。雷霆蜥蜴（9-10级）和闪电皮蜥蜴（10-11级）生活在{zone:1411}西北{area:369}的裂隙里，位于{zone:1454}以南：从{zone:1413}的桥向左转，沿河向北进入。两者大约五次击杀掉四片鳞；都会施放{spell:5401}。",
	["Zaal Stormshield"] = "扎尔·风盾",
	["{item:263993}, from {npc:257196}"] = "{item:263993}，来自{npc:257196}",
	["{item:6486}, from the lizards"] = "{item:6486}，来自蜥蜴",
	["{item:6534}, from the {object:58369}"] = "{item:6534}，来自{object:58369}",
	["{npc:1500} is in the {area:2119}, the inn on {area:159}'s east side."] = "{npc:1500}在{area:2119}，即{area:159}东侧的旅店。",
	["{npc:252377} in {area:16638}"] = "{area:16638}的{npc:252377}",
	["{npc:5810} at {area:379}"] = "{area:379}的{npc:5810}",
	["{npc:5810} is easy to miss: he stands under a small canopy by a large tree just west of {area:379}, below the road's south side, with the post in sight to his east. Going straight south from the post does not lead to him. From {zone:1411} cross the bridge west; from {zone:1412} head north past the {area:380}."] = "{npc:5810}很容易错过：他站在{area:379}正西一棵大树下的小棚子里，位于道路南侧下方，向东能看见哨站。从哨站直接往南走找不到他。从{zone:1411}向西过桥；从{zone:1412}向北经过{area:380}。",
	["{npc:5878}'s hut sits on top of {area:1699}, east of the {area:380}. Most slopes are too steep: climb the broad ridge on the north or east side."] = "{npc:5878}的小屋在{area:1699}顶上，位于{area:380}以东。大多数坡太陡：从北侧或东侧宽阔的山脊爬上去。",
	["{npc:6390} sleeps in the mausoleum in the graveyard just north of Dillinger. To wake him, click the flat skull plaque on the ground, left of the path to the mausoleum door; the seal lifts and {npc:6390} (level 11, not elite) walks out. Start at full health."] = "{npc:6390}睡在迪林格正北方墓地的陵墓里。要唤醒他，点击通往陵墓门口的小路左侧地面上那块扁平的头骨石板；封印会解除，{npc:6390}（11级，非精英）会走出来。满血再开始。",
	["{spell:71} and a Weapon (Horde)"] = "{spell:71}和一把武器（部落）",
	["{spell:71} at 10 and a one-hand weapon of your choice: {npc:5810}'s road, {area:159}'s crypt, or the Skybreaker shield."] = "10级时拿到{spell:71}和一把自选的单手武器：{npc:5810}的路线、{area:159}的墓穴，或破天者盾牌。",
}

G["forever/collectibles/mounts/horde/black-war-mounts"] = {
	["Black War Mounts"] = "黑色战斗坐骑",
	["PvP rank 11"] = "PvP 军衔11",
	["{item:18247}, {spell:18995}, 100g"] = "{item:18247}，{spell:18995}，100金",
	["{item:18248}, {spell:10906}, 100g"] = "{item:18248}，{spell:10906}，100金",
	["{npc:12796} sells the mounts by the {area:2917} in {zone:1454}'s {object:172958}, beside the other honor quartermasters. The Forever client lists each at 100g. Each one also needs its kind's riding: Orcs ride the wolf, Trolls the raptor, Tauren the kodo, Undead the skeletal warhorse. A Skyborne, or anyone choosing another race's mount, first needs that riding from its trainer (Exalted with the race's city)."] = "{npc:12796}在{zone:1454}的{object:172958}中{area:2917}旁出售坐骑，和其他荣誉军需官在一起。Forever 客户端标价每匹100金。每种坐骑还需要对应种族的骑术：兽人骑狼，巨魔骑迅猛龙，牛头人骑科多兽，亡灵骑骷髅战马。天裔或选择其他种族坐骑的人，须先从对应训练师处学会该骑术（与那种族的城市达到崇拜）。",
	["{npc:14329}, {spell:825}, 100g"] = "{npc:14329}，{spell:825}，100金",
	["{npc:14330}, {spell:10861}, 100g"] = "{npc:14330}，{spell:10861}，100金",
	["{spell:1299382} come from battlegrounds, PvP quests and the season's weekly tasks, with a weekly cap; {spell:436438} (rank 11) unlocks the Black War mounts. The Player vs. Player tab of your character pane shows your rank and what you may buy. {skill:762} one at full speed needs Journeyman {skill:762} (level 60). Polestar cannot read your rank, so this step waits for level 60 and Journeyman {skill:762}."] = "{spell:1299382}来自战场、PvP任务和当季的每周任务，有每周上限；{spell:436438}（11级军衔）解锁黑色战争坐骑。角色面板的“玩家对战”标签页会显示你的军衔和可购买内容。要让{skill:762}达到全速需要中级{skill:762}（60级）。Polestar 无法读取你的军衔，因此这一步要等到60级和中级{skill:762}。",
}

G["forever/collectibles/mounts/horde/frostwolf-howler"] = {
	["The Forever client lists it at 200g and level 60. It runs at full speed, so riding it needs Journeyman {skill:762}; any Horde race can ride it."] = "Forever客户端标价200金、60级。它以全速奔跑，因此骑乘需要中级{skill:762}；任何部落种族都可骑乘。",
	["{area:2839} (level 51+) raises {faction:729}: win, capture towers and graveyards, and hand in the battleground's turn-ins; the Alterac Valley Reputation guide shows the fastest way. {npc:13219} waits at the Horde end of {zone:1416} outside the battleground; {npc:13218} inside {area:2839} sells the same mount."] = "{area:2839}（51级以上）提升{faction:729}：获胜、占领塔和墓地、交战场任务物品；奥特兰克山谷声望指南有最快路线。{npc:13219}在战场外{zone:1416}的部落一端等候；{area:2839}内的{npc:13218}出售同样的坐骑。",
	["{npc:13219}, 200g"] = "{npc:13219}，200金",
}

G["forever/collectibles/mounts/horde/great-kodo"] = {
	["Any Horde race can buy these kodos, but riding one also takes {spell:18995}, which only Tauren get with {skill:762}. {npc:3690} teaches it to other races once they are Exalted with {faction:81} (the Thunder Bluff Reputation guide shows the way). Until then, don't buy a kodo for this character."] = "任何部落种族都能买这些科多兽，但骑乘还需要{spell:18995}，只有牛头人随{skill:762}获得。其他种族在与{faction:81}达到崇拜后，{npc:3690}才会教（雷霆崖声望指南里有说明）。在此之前，不要给这个角色买科多兽。",
	["Great Kodo"] = "大型科多兽",
	["Journeyman {skill:762}"] = "中级{skill:762}",
	["Pick a colour"] = "选择颜色",
	["{item:18793}, 200g"] = "{item:18793}，200金",
	["{item:18794}, 200g"] = "{item:18794}，200金",
	["{item:18795}, 200g"] = "{item:18795}，200金",
	["{npc:3685} sells the other colours (200g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:3685}出售其他颜色（Forever 客户端中每个200金）。想要就买，如果喜欢获赠的那匹也可以不买。",
	["{npc:3690} and {npc:3685}'s kodos are in {area:222}, {zone:1412}. At 60 {npc:3690} teaches Journeyman {skill:762} to Tauren for 1,000g (10% less at Honored with {faction:81}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each great kodo costs 200g here."] = "{npc:3690}和{npc:3685}的科多兽都在{zone:1412}的{area:222}。60级时，{npc:3690}以1,000金教牛头人中级{skill:762}（与{faction:81}达到尊敬时便宜10%）；暴雪说它会附带一匹坐骑。其他种族在自己种族的骑术训练师处学习。这里每匹大型科多兽售价200金。",
	["{npc:3690}, riding trainer"] = "{npc:3690}，骑术训练师",
	["{spell:18995} for other races"] = "其他种族所需的{spell:18995}",
}

G["forever/collectibles/mounts/horde/kodo"] = {
	["Any Horde race can buy these kodos, but riding one also takes {spell:18995}, which only Tauren get with {skill:762}. {npc:3690} teaches it to other races once they are Exalted with {faction:81} (the Thunder Bluff Reputation guide shows the way). Until then, don't buy a kodo for this character."] = "任何部落种族都能买这些科多兽，但骑乘还需要{spell:18995}，只有牛头人能随{skill:762}一并获得。其他种族需在{faction:81}达到崇拜后由{npc:3690}传授（雷霆崖声望指南有详细方法）。在此之前，别给这个角色买科多兽。",
	["Kodo"] = "科多兽",
	["Learn to ride"] = "学习骑术",
	["Pick a colour"] = "选择颜色",
