G["forever/collectibles/mounts/horde/pack-kodo"] = {
	["6,000 Merchant's Favor"] = "6,000 Merchant's Favor",
	["The camp stands just outside the west gate of the {area:380} in the {zone:1413}. {npc:256400} sells the {npc:10636} only once you are Exalted with {faction:2587}, and it costs 6,000 Merchant's Favor. Crates pay only Favor (about 15 a crate return); the reputation comes from Craftsman's Writs and the one-time {item:280179}, so follow the Supply Factions Reputation guide and keep 6,000 Favor aside."] = "营地就在{zone:1413}的{area:380}西门外。只有当你在{faction:2587}的声望达到崇拜后，{npc:256400}才出售{npc:10636}，价格为6,000点商人的恩惠。交板条箱只给恩惠（每次交还约15点）；声望来自工匠令状和一次性的{item:280179}，所以请参照补给声望指南进行，并预留出6,000点恩惠。",
	["The reins need level 60 and Journeyman Riding to ride (Forever client); you can buy them earlier."] = "缰绳需要60级和中级骑术才能骑乘（Forever 客户端）；可以提前购买。",
	["{faction:2587} camp"] = "{faction:2587}营地",
}

