G["forever/collectibles/pets/black-tabby"] = {
	["The {npc:1920}, a rare level 21 mage at {area:233} in southern {zone:1421}, drops the {npc:7383} about once in 6 kills. It has a single spot and can take hours to come back, so check it whenever you pass. While it is down, the Dalaran Shield Guards, Theurgists and Summoners (level 31-35) at the {area:279} crater, where {zone:1416} meet {zone:1424}, drop it too, but only about once in 500 kills. The cat can be traded: look at the Auction House as well."] = "{npc:1920}是{zone:1421}南部{area:233}的稀有21级法师，每6次击杀约有一次掉落{npc:7383}。它只有一个刷新点，可能要几小时才回来，所以路过就去看看。它没刷新的时候，{zone:1416}与{zone:1424}交界处{area:279}巨坑里的达拉然盾卫、咒术师和召唤师（31-35级）也会掉落，但约500次击杀才出一次。这只猫可以交易：也看看拍卖行。",
	["{area:279} mages"] = "{area:279}的法师",
}

G["forever/collectibles/pets/excitable-slime"] = {
	["Buy {item:278265} from {npc:4612} in the {zone:1458} canals first (25 copper for a stack of 5): you hand it in as soon as the slime offers its quest."] = "先在{zone:1458}运河边的{npc:4612}处买{item:278265}（25铜一组5个）：软泥一给任务就立刻交。",
	["Find an {npc:269452}, a little critter in the canal water beside {npc:4612}, target it and /dance at it, again and again, until it dances back and offers {quest:97583}; this takes many tries. Hand in the sludge right away. If the slime seems tired, /dance with it again before you hand in."] = "找到{npc:4612}旁运河水中的小生物{npc:269452}，选中它并反复对它/跳舞，直到它回舞并提供{quest:97583}；这要试很多次。立刻交泥浆。若软泥看起来累了，交之前再和它/跳舞一次。",
	["{item:278265}: {npc:4612}, in the canals"] = "{item:278265}：运河边的{npc:4612}",
}

