	["{object:3646}; below ground"] = "{object:3646}；在地下",
	["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}是一头巨大的鱼龙，在{area:391}外的浅水中游动，位于{npc:3388}东边。",
}

G["forever/horde/07-ashenvale"] = {
	["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "向南回到营地，然后上到{zone:1456}，飞往{area:378}。",
	["Back south-west to {area:421}. Befouled Water Elementals drift around its shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "向西南回到{area:421}。污浊的水元素在湖岸周围漂浮；瞭望台在岛上，俯瞰着联盟的前哨站。",
	["Back to {area:484}"] = "回到{area:484}",
	["Back west to Zoram'gar before heading east for good."] = "向西回到佐拉姆加前哨站，然后再彻底向东出发。",
	["Befouled Water Elemental"] = "被污染的水元素",
	["Below ground"] = "地下",
	["Broodmother Valraxx"] = "巢母瓦拉克斯",
	["Cairne Bloodhoof"] = "凯恩·血蹄",
	["Class trainer"] = "职业训练师",
	["Climb the path to the top of {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "沿小路爬上{area:2097}顶部。{npc:10646}被囚禁在{npc:10896}（29级）旁边：先清掉守卫和{npc:10896}，再救出她并在下山路上保护她；途中会有恐怖图腾伏击者袭击你。",
	["East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold.\nCareful: A Shaman at 15% health or lower runs off to find help, which can pull extra furbolgs."] = "佐拉姆加以东，蓟皮熊怪占据了村庄和据点周围的山丘。\n注意：生命值降到15%或更低的萨满会跑去求援，可能带回更多熊怪。",
	["Felmusk satyrs"] = "魔草萨特",
	["Fly to {area:1638} if you know the flight path. If not, fly to {area:378}, head west into {area:215} past {area:222} to {area:1638} and take its flight path from {npc:2995} on the central rise."] = "如果已开通飞行路线，直接飞到{area:1638}。否则先飞到{area:378}，向西进入{area:215}，经{area:222}到{area:1638}，在中央高地上找{npc:2995}开飞行点。",
	["Fly to {area:2897}"] = "飞到{area:2897}",
	["Fly to {area:378}"] = "飞到{area:378}",
	["Fly to {area:378}. {npc:5899}'s hut stands on the ridge above the quilboar watering hole south of the camp, on the road to the {area:485}."] = "飞到{area:378}。{npc:5899}的小屋在营地以南野猪人饮水处上方的山脊上，就在通往{area:485}的路上。",
	["Follow the canyon east out of the mesas onto the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "沿峡谷向东离开石柱区，来到盐滩。{area:2240}的地精和侏儒是中立的，为两个阵营提供任务。",
	["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "沿主路向东经过{area:415}（联盟据点：别离开道路）。{npc:12678}是一头巨大的灰熊，在道路南边、{area:421}西边的{area:418}游荡。它的爪子可以开始下一个狩猎任务。",
	["Galak Scout"] = "加拉克斥候",
	["Galak Windchaser"] = "加拉克逐风者",
	["Galak Wrangler"] = "加拉克牧者",
	["Galak centaurs"] = "加拉克半人马",
	["Gazebo"] = "瞭望台",
	["Gloomrise Hatchling"] = "格鲁姆莱斯雏龙",
	["Gloomrise Soldier"] = "格鲁姆莱斯士兵",
	["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "暮升毒液样本，从{npc:264096}获取",
	["His crate is for Stranglethorn, later on the route"] = "他的箱子要送去荆棘谷，在路线后面",
	["If you skipped {quest:5151}, grind here to level 29.49 to stay on the route's plan."] = "如果跳过了{quest:5151}，在这里刷到29.49级，以保持在路线计划内。",
	["Inside the hold, Troll Chests lie along the tunnels. {npc:12818} is held deep inside: free him and protect him all the way out, then he runs home to {area:428}.\nCareful: Two scripted ambushes occur, each made up of three Thistlefurs (a Shaman, a Pathfinder and an Avenger, Ursa or Den Watcher): the first when you come back to the tunnel's fork inside the cave, the second just beyond the gate where {npc:3987} roams."] = "据点里，巨魔箱子散落在隧道沿途。{npc:12818}被关在最深处：救出他并一路护送到外面，然后他会跑回{area:428}。\n注意：会有两次剧情伏击，每次由三只蓟皮熊怪组成（一个萨满、一个探路者和一个复仇者、乌尔萨或巢穴看守）：第一次在洞内回到隧道岔路时，第二次在{npc:3987}游荡的大门之外。",
	["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "继续沿道路向东。{npc:12858}在战歌伐木营地西南等候。他和他的步兵会猛攻{area:2360}：让他们吸引仇恨，跟着{npc:12858}直到{npc:12860}死去。",
	["Kill the {npc:10720} that comes for {npc:10638}"] = "杀死前来袭击{npc:10638}的{npc:10720}",
	["Level 29.49"] = "29.49级",
	["Naga brazier"] = "纳迦火盆",
	["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} sits at the north end: her {item:273658} starts {quest:96294}."] = "在营地北边，蜘蛛占据了{area:17044}的墓地。对{npc:264096}使用{npc:264074}的{item:273015}；那里的蜘蛛掉落{item:273181}。{npc:264082}在北端：她的{item:273658}可以开始{quest:96294}。",
	["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns."] = "在碎木岗哨西北，魔草萨特在树林里扎营。每个萨特都可能掉落角。",
	["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "乘升降梯下去，然后沿道路向东穿过峡谷前往{area:484}，那是一座建在石柱顶上的牛头人村庄。它的升降梯在北侧。",
	["Sapphires of Aku'Mai"] = "阿库麦尔蓝宝石",
	["Screeching Harpy"] = "尖啸鹰身人",
	["Screeching Roguefeather"] = "尖啸盗羽",
	["Screeching Windcaller"] = "尖啸唤风者",
	["South of Darkcloud, the harpies of {area:487}. {npc:4490} (31) walks among them: thin out the harpies around her before you pull her. The Screeching Harpies, Roguefeathers and Windcallers there are {npc:4877}'s."] = "在黑云峰南边是{area:487}的鹰身人。{npc:4490}（31级）在它们中间走动：引她之前先清掉她周围的鹰身人。那里的尖啸的鹰身人、尖啸的游荡者和尖啸的唤风者是{npc:4877}要的。",
	["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "与{area:1638}的{npc:3057}交谈：{quest:93739}",
	["Take a lift down from {zone:1456}. The Earthen Ring camp stands north of the bluffs: {npc:264074}, {npc:264072} and {npc:259118}."] = "从{zone:1456}乘升降梯下去。大地之环的营地在高崖北边：{npc:264074}、{npc:264072}和{npc:259118}。",
	["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "乘升降梯下去。蛋在峡谷底部的一个巢里，位于三个地点之一：石柱东南（52.3,55.2）、东边（56.4,50.4）或西南（37.6,56.1）。",
	["Talk to {npc:3057}"] = "与{npc:3057}交谈",
	["The Earthen Ring"] = "大地之环",
	["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "污林熊怪占据着{area:421}东边、道路南边的树林。把{item:16972}放在{object:178206}上并守护它：熊怪会来摧毁它。{npc:12918}最后出现；他的图腾会掉进篮子里。",
	["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks between the camps: kill him when you meet him, his note starts a quest for {area:2237}."] = "加拉克半人马的营地遍布乱风岗北边的峡谷；每个营地都有加拉克斥候、加拉克争斗者和加拉克逐风者。一个落单的{npc:10617}在营地之间走动：遇到就杀死他，他的信件可以开始一个{area:2237}的任务。",
	["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "阿库麦尔蓝宝石是通往{area:2797}传送门的坑道墙壁上的蓝色水晶，位于地下、副本之外：从坑里潜下去，从墙下游进洞穴。坑道里的萨特和纳迦是精英：建议组队。水晶刷新很快，不用深入。",
	["The Wanted poster beside {npc:10537}"] = "{npc:10537}旁的通缉告示",
	["The fountain stands in the middle of the {area:418}: use the {item:7767} there."] = "喷泉在{area:418}中央：在那里使用{item:7767}。",
	["The next guide flies on from here to {zone:1454}."] = "下一个指南从这里飞往{zone:1454}。",
	["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "去阿库麦尔蓝宝石的路要穿过海滩北端沉没的废墟：沿台阶下到坑里。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:10992} is a level 30 elite: most classes solo it at level 32, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人来一起做。{npc:10992}是30级精英：大多数职业32级可以单挑，但可能需要帮忙。如果只有你一个人就跳过：路线会安排你刷怪补经验。",
	["Thistlefur Avenger"] = "蓟皮复仇者",
	["Thistlefur Hold"] = "蓟皮熊怪的巢穴",
	["Thistlefur Shaman"] = "蓟皮萨满",
	["Underwater"] = "水下",
	["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "在乱风岗西边，恐怖图腾的营地在{area:2097}下方。密信在东南、西南和西北营地的文件箱里。",
	["West of Whitereach the wyverns nest on the {area:482} cliffs; the eggs lie in the nests. {npc:10427} waits on the east side of the nesting grounds: free him and keep him alive on the walk back to {area:2237}.\nCareful: Wyverns at level 28-29 fly overhead and can be pulled without warning. A group of three wyverns can ambush you once you pass the first pillar at the bottom."] = "白脊以西，双足飞龙在{area:482}的崖壁上筑巢；蛋就在巢里。{npc:10427}在巢区东侧等着：救出他，并在一路走回{area:2237}的途中保护他。\n注意：28-29级的双足飞龙会从头顶飞过，可能毫无征兆地被拉进战斗。你过了底部的第一根石柱后，可能会被一群三只飞龙伏击。",
	["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "在这里时：找{npc:11869}学习{spell:199}（10银）；战士用双手武器升级最快。",
	["for {npc:5901}, south of {area:392}: next guide"] = "交给{area:392}南边的{npc:5901}：见下一个指南",
	["grind on {npc:4101}"] = "刷{npc:4101}",
	["{area:17044}: kill these as you meet them"] = "{area:17044}：遇到就杀",
	["{area:2240}: kill these as you meet them"] = "{area:2240}：遇到就杀",
	["{area:2797} ruins"] = "{area:2797}废墟",
	["{area:2897} flight master"] = "{area:2897}飞行管理员",
	["{area:378} flight master"] = "{area:378}飞行管理员",
	["{area:392} flight master"] = "{area:392}飞行管理员",
	["{area:418} fountain"] = "{area:418}的喷泉",
	["{area:483}: kill these as you meet them"] = "{area:483}：遇到就杀",
	["{area:484} flight master"] = "{area:484}飞行管理员",
	["{item:273181}, from Gloomrise Spinners"] = "{item:273181}，从{npc:264081}获取",
	["{item:273658}, from {npc:264082}"] = "{item:273658}，从{npc:264082}获取",
	["{npc:10377}, by the wind rider master"] = "{npc:10377}，在双足飞龙管理员旁边",
	["{npc:10428}'s next quest, Sacred Fire, ends in {zone:1456}, off this route. Skip it."] = "{npc:10428}的下一个任务（生命圣火）在{zone:1456}结束，不在本路线上。跳过它。",
	["{npc:10645}, inside"] = "{npc:10645}，在里面",
	["{npc:12676}, a big nightsaber, prowls the woods south-east of the Warsong lumber camp. Her claw starts the next hunt quest."] = "{npc:12676}是一只巨大的夜刃豹，在战歌伐木营地东南的树林里潜行。它的爪子可以开始下一个狩猎任务。",
	["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}是一只暗影豹，在魔草萨特营地西边的{area:426}周围的树林里潜行。它的头颅可以开始下一个狩猎任务。",
	["{npc:12717} walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead."] = "{npc:12717}沿着海滩向北走到一个纳迦火盆旁。熄灭火盆，然后在纳迦一波波来袭时保护他，直到鞭笞者沃尔沙死去。",
	["{npc:12717}: starts his escort at once"] = "{npc:12717}：立即开始护送",
	["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}：仅当你带着手册书页时",
	["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736}接下来会提供一个{area:2797}任务；除非你有队伍，否则别接。",
	["{npc:12759}, a corrupted water elemental, drifts in {area:421}. Her {item:16408} starts a quest for Splintertree."] = "{npc:12759}是一个被腐化的水元素，在{area:421}里漂浮。它掉落的{item:16408}可以开始一个碎木岗哨的任务。",
	["{npc:12818}, below ground"] = "{npc:12818}，地下",
	["{npc:12837}, inside"] = "{npc:12837}，在里面",
	["{npc:210995} may not offer these to every class; if he doesn't, carry on.; walks around {area:1276}: the map marks where to look"] = "{npc:210995}可能不会对每个职业提供这些任务，若没有就继续。；他在{area:1276}一带走动：地图上标出了查看位置",
	["{npc:210995}, a Forever addition, stands on the west shore of {area:421} with three quick Dragonslayer quests."] = "{npc:210995}是Forever新增的NPC，站在{area:421}西岸，有三个简短的屠龙者任务。",
	["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986}站在加拉克营地东边的一座石柱顶上。做{quest:1149}时，从他旁边的木板尽头走下去：你会安全落地。",
	["{npc:2986}, below ground"] = "{npc:2986}，地下",
	["{npc:4454}: his letter goes to Martek in the {zone:1418}, around level 38"] = "{npc:4454}：他的信要交给{zone:1418}的马特克，大约38级时",
	["{npc:4499}, a hard-hitting rock elemental, walks the cliffs of {area:482}. {npc:4499} is elite: grouping up is advised."] = "{npc:4499}是一个攻击力很高的石元素，在{area:482}的悬崖上走动。{npc:4499}是精英：建议组队。",
	["{npc:4877}, inside"] = "{npc:4877}，在里面",
	["{npc:4877}, the trade supplies vendor: the Screeching harpies of {area:487}; inside"] = "{npc:4877}，补给品商人：{area:487}的尖啸鹰身人；在里面",
	["{object:176344}, north-west camp"] = "{object:176344}，西北营地",
	["{object:176344}, south-east camp"] = "{object:176344}，东南营地",
	["{object:176344}, south-west camp"] = "{object:176344}，西南营地",
	["{object:19868} lies all over the flats north of the raceway. Scorpid Reavers roam the north half; keep to it, away from the Saltstone Basilisks, Crystalhides and Gazers (32-35) west of the track, in the middle and the far south."] = "{object:19868}散布在赛道以北的平地上。蝎子掠夺者游荡在北半部；就待在那片区域，远离赛道以西、中间和远南方向32-35级的盐石蜥蜴、水晶皮蜥蜴和凝视者。",
	["{zone:1456} flight master"] = "{zone:1456}飞行管理员",
}

G["forever/horde/30-40/01-desolace"] = {
	["Back at {area:609}, every Kolkar can drop an ear.\nCareful: Kolkar Battle Lords call nearby allies within 30 yd once they fall to 20% health."] = "回到{area:609}，每个科尔卡都可能掉落耳朵。\n注意：科尔卡战斗领主血量降到20%时会呼叫30码内附近的同伴。",
	["Back to {area:1637}"] = "回到{area:1637}",
	["Back to {area:272}"] = "返回{area:272}",
	["Below ground"] = "地下",
	["Clam beds"] = "蚌床",
	["Daggerspine naga"] = "刺脊纳迦",
	["Daggerspine shore"] = "刺脊海岸",
	["Dalaran Summoner"] = "达拉然召唤师",
	["Do your shopping in the {zone:1458} first, then fly to the {area:228}. The {object:113791} stands on the hill just south-west of it: beat the Corrupt Manifestation of Water beside it, place its bracers in the brazier, speak to the {npc:5895} and keep the {item:7813} for {npc:5901}. Fly on to {area:272} from the {area:228}."] = "先在{zone:1458}买好补给，然后飞往{area:228}。{object:113791}就在它西南的小山上：击败旁边的堕落水之化身，把它的护腕放进火盆，与{npc:5895}交谈，并把{item:7813}留给{npc:5901}。然后从{area:228}飞往{area:272}。",
	["Elemental Slave"] = "元素奴隶",
	["Fly from {zone:1454} to {area:1638} and train with {npc:3033} on {area:1639}, then fly back to {zone:1454}."] = "从{zone:1454}飞往{area:1638}，在{area:1639}找{npc:3033}训练，然后飞回{zone:1454}。",
	["Fly to {area:1497}"] = "飞往{area:1497}",
	["Fly to {area:1637}"] = "飞往{area:1637}",
	["Fly to {area:272}"] = "飞往{area:272}",
	["Fly to {area:392}. {npc:5901} camps on the coast a short walk south of the town."] = "飞往{area:392}。{npc:5901}在镇子南边不远处的海岸扎营。",
	["Fly to {area:460}"] = "飞往{area:460}",
	["Fly to {area:484}. {npc:5905} hides in a small cave in the canyon wall north-east of the post."] = "飞往{area:484}。{npc:5905}躲在哨站东北峡谷崖壁上的一个小山洞里。",
	["Fly to {zone:1454}"] = "飞往{zone:1454}",
	["Follow the road north out of {area:272} into the Alterac foothills. {quest:535} waits by the Syndicate camp; hand him the stout."] = "沿道路向北离开{area:272}，进入奥特兰克山麓。{quest:535}在辛迪加营地旁等候；把南海镇烈酒交给他。",
	["Follow the shore west past {area:271}'s bay; the Torn Fin murlocs camp on the beaches beyond it."] = "沿海岸向西经过{area:271}的海湾；碎鳍鱼人在海湾另一边的海滩上扎营。",
	["Hatefury Betrayer"] = "憎怒背叛者",
	["Hatefury Felsworn"] = "憎怒邪誓者",
	["Hatefury Hellcaller"] = "憎怒唤狱者",
	["Hatefury Rogue"] = "憎怒潜行者",
	["Head back east to {area:272}."] = "向东返回{area:272}。",
	["Head back north to {area:272}, keeping west of {area:271}."] = "向北返回{area:272}，保持在{area:271}以西。",
	["Head back north to {area:272}."] = "向北返回{area:272}。",
	["Head back south to the post."] = "向南返回岗哨。",
	["Head back south to {area:272}."] = "向南返回{area:272}。",
	["Head north past {quest:535}'s camp to {area:280}, the Syndicate-held village (35-37). {npc:2431} carries the {item:3704}; {quest:503} sits in a cage in the house on the north side.\nCareful: Stealthed Syndicate spies roam {area:280}, and the buildings hold many Syndicate mobs, mages among them."] = "向北经过{quest:535}的营地前往{area:280}，即辛迪加占据的村庄（35-37级）。{npc:2431}身上有{item:3704}；{quest:503}关在北边房子里的笼子里。\n注意：潜行的辛迪加间谍在{area:280}游荡，建筑里有许多辛迪加怪物，其中有法师。",
	["Head north up the coast. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach; open each clam in your bags for its meat."] = "沿海岸向北走。巨型软壳蚌躺在浅水区，狂暴暗礁爬行者走在海滩上；在背包里打开每个蚌取肉。",
	["Head north-east to {area:609}. {quest:1365} (35) walks among the tents on the east side with a Battle Lord or two (32-33): clear around him, then pull him alone at full health."] = "向东北前往{area:609}。{quest:1365}（35级）和一两名战斗领主（32-33级）在东边的帐篷之间走动：先清掉他周围的怪，然后满状态单独拉他。",
	["Head south, east of {area:271}, down to the coast. The Daggerspine naga line the shore south-east of the town."] = "向南走，在{area:271}以东，一直到海岸。匕鳞纳迦排列在城镇东南的岸边。",
	["Head south-east to the post."] = "向东南前往岗哨。",
	["Head south-west to the troll village on the coast, keeping clear of the {area:606} on the way."] = "向西南前往海岸边的巨魔村庄，途中避开{area:606}。",
	["Head west along the foot of the mountains to the violet dome of {area:279}. {npc:2411}, {npc:2412} and {npc:2413} (33-34) stand together inside the crater's eastern rim, {npc:2414} (35) a little west of them; each carries one Bloodstone piece. The Shield Guards and Theurgists (31-32) around them drop the Worn Stone Tokens.\nCareful: Many guards stand in linked pairs and others patrol alone around the camp."] = "沿山脚向西前往{area:279}的紫罗兰色穹顶。{npc:2411}、{npc:2412}和{npc:2413}（33-34级）一起站在环形山口的东缘内，{npc:2414}（35级）在他们西边一点；每人各带一块血石碎片。周围的盾卫和神术师（31-32级）掉落磨损的石质徽记。\n注意：许多守卫成对联动站位，其余则单独在营地周围巡逻。",
	["Head west to {area:599}. Beat a Burning Blade cultist down, then use the {item:6436} on it before it dies to fill one {item:6435}. They also drop a {item:20310} now and then (1-5%); if one drops, read it."] = "向西前往{area:599}。把一名燃刃信徒打到残血，在它死掉之前使用{item:6436}，即可灌满一个{item:6435}。它们偶尔也掉落{item:20310}（1-5%）；如果掉了，读一下。",
	["Inside"] = "室内",
	["Keep north to {area:598}. The Oracles stand among the other naga at its north end; pull one at a time."] = "继续向北前往{area:598}。滑刃智者站在北端的其他纳迦中间；一次引一只。",
	["Kolkar ears"] = "半人马的耳朵",
	["North along the eastern hills, the satyrs hold the ruins of {area:603}. The Shadowstalkers walk unseen; the four kinds you need do not.\nCareful: Hatefury Rogues use Hide when they spawn, so they are stealthed until you find them."] = "沿东边的山丘向北，萨特占据着{area:603}的废墟。影行者无形无踪；你需要的四种怪不会。\n注意：憎怒潜行者刷新时会使用隐藏，所以在你发现它们之前一直处于潜行状态。",
	["Paladin trainer"] = "圣骑士训练师",
	["Place the {object:1729} on the {object:1728} beside the inn; upstairs"] = "把{object:1729}放到旅店旁的{object:1728}上；在楼上",
	["Shadowstalker scalp"] = "巡影者的头皮",
	["Shindigger keg"] = "矿工烈酒酒桶",
	["Slitherblade Myrmidon"] = "滑刃侍从",
	["Slitherblade Naga"] = "滑刃纳迦",
	["Slitherblade Oracles"] = "滑刃智者",
	["Slitherblade Sorceress"] = "滑刃女巫",
	["South-west, the Cave and Ferocious Yetis (30-31) fill the caves in the hills west of {area:272}; about one in sixteen carries the rod."] = "在西南，洞穴雪人和凶恶的雪人（30-31级）占满了{area:272}西边山丘里的洞穴；大约十六分之一带着魔棒。",
	["Syndicate missives"] = "辛迪加信件",
	["Thaivand's next task ends at {area:271}'s graveyard and the magus offers a dungeon errand: leave both."] = "塞万德的下一个任务在{area:271}的墓地结束，而那位魔导师提供的是一个地下城差事：两个都别接。",
	["The Hatefury Shadowstalkers at {area:603} walk unseen until they strike; about one in three carries a scalp."] = "{area:603}的怨怒巡影者在攻击前都是隐形的；大约三分之一带着头皮。",
	["The Syndicate Footpads and Thieves (32-33) around the camps west of the road carry the missives; about one in three drops one."] = "道路西边营地周围的辛迪加劫匪和辛迪加窃贼（32-33级）携带信件；大约三分之一会掉落。",
	["The keg stands with a few others at the Syndicate camp on the south-east coast of {area:287}."] = "酒桶和另外几个酒桶一起放在{area:287}东南海岸的辛迪加营地里。",
	["The {area:279} traitors"] = "{area:279}的叛徒",
	["To {area:484}"] = "前往{area:484}",
	["Torn Fin beach"] = "碎鳍海滩",
	["Torn Fin murlocs"] = "碎鳍鱼人",
	["Train"] = "训练",
	["Train your new spells."] = "训练你的新法术。",
	["Underwater"] = "水下",
	["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702} in the graveyard and walk the tamed kodo back to {npc:11596}. Five kodos, one at a time."] = "对坟场里的老迈的科多兽、濒死的科多兽或{npc:4702}使用{npc:11596}的{item:13892}，把驯服的科多兽带回{npc:11596}那里。共五头，一次一头。",
	["Zeppelin to {zone:1458}"] = "乘飞艇前往{zone:1458}",
	["for {npc:5901}: from Stranglethorn, next guide"] = "交给{npc:5901}：从荆棘谷前往，见下一个指南",
	["grind on {npc:12347}"] = "刷{npc:12347}",
	["grind on {npc:4670}"] = "刷{npc:4670}",
	["grind on {npc:4674}"] = "刷{npc:4674}",
	["grind on {npc:4718}"] = "刷{npc:4718}",
	["{area:17707}: kill these as you meet them"] = "{area:17707}：遇到就杀",
	["{area:228} flight master"] = "{area:228}飞行管理员",
	["{area:2408} flight master"] = "{area:2408}的飞行管理员",
	["{area:272} flight master"] = "{area:272}飞行管理员",
	["{area:484} flight master"] = "{area:484}飞行管理员",
	["{item:3388}: auction house or an alchemist, for {quest:515}."] = "{item:3388}：拍卖行或炼金术士，用于{quest:515}。",
	["{item:3703}, for {npc:2333}"] = "{item:3703}，交给{npc:2333}",
	["{npc:11863} waits in the ruined tower of {area:2405}, inland to the south-east."] = "{npc:11863}在内陆东南方{area:2405}的废塔里等候。",
	["{npc:11877}: for {npc:715} in Stranglethorn"] = "{npc:11877}：交给荆棘谷的{npc:715}",
	["{npc:2216}, inside"] = "{npc:2216}，室内",
	["{npc:2229}, inside"] = "{npc:2229}，室内",
	["{npc:2229}: for the {zone:1413}, later on the route"] = "{npc:2229}：交给{zone:1413}，路线后面会去",
	["{npc:2410}, inside"] = "{npc:2410}，室内",
	["{npc:2437}, inside"] = "{npc:2437}，室内",
	["{npc:246344} in {zone:1456}; {zone:1454} has no paladin trainer"] = "{npc:246344}在{zone:1456}；{zone:1454}没有圣骑士训练师",
	["{npc:260093} trains Paladins in the {zone:1458}."] = "{npc:260093}在{zone:1458}训练圣骑士。",
	["{npc:2770}: for {area:321} in Arathi, later on the route"] = "{npc:2770}：交给阿拉希高地的{area:321}，路线后面会去",
	["{npc:4711}, 130 yd north-west"] = "{npc:4711}，西北方130码",
	["{npc:4712}, 130 yd west"] = "{npc:4712}，西方130码",
	["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}，在格罗玛什要塞，如果你带着它",
	["{npc:5395} stands in the post; {npc:5641} and {npc:4498} wait on the rise west of it, above the {area:596}."] = "{npc:5395}站在哨站里；{npc:5641}和{npc:4498}在哨站西边的高地上等候，俯瞰{area:596}。",
	["{npc:5639} waits in the Drag; {npc:5640} stands in the {object:172961} on the west side of the city. Skyborne: {npc:4949} waits in Grommash Hold, in the {object:172957}."] = "{npc:5639}在暗巷区等候；{npc:5640}站在城西侧的{object:172961}。天裔：{npc:4949}在{object:172957}的格罗玛什要塞里等候。",
	["{npc:5641}'s next errand sends you after a demon lord with an elite guard: skip it."] = "{npc:5641}的下一个差事要你去对付一个带着精英护卫的恶魔领主：跳过它。",
	["{npc:5641}'s next {quest:1431} sends you back to {zone:1454} for nothing: leave it."] = "{npc:5641}的下一个任务{quest:1431}让你白跑一趟{zone:1454}：别接。",
	["{npc:5892} stands in the {object:172957}."] = "{npc:5892}站在{object:172957}。",
	["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905}还会开始元素援助（{area:1717}），这是通往风暴武器的33-40级任务线：见萨满祭司职业指南“空气的召唤和风暴武器（部落）”。",
	["{npc:5905}: your {item:5178}"] = "{npc:5905}：你的{item:5178}",
	["{quest:503}, on the top floor"] = "{quest:503}，在顶楼",
	["{quest:515} needs a {item:3388}, an {skill:171} item: buy one at the auction house here if you can (or ask an alchemist). No potion: skip the Elixir steps in {area:287}."] = "{quest:515}需要一瓶{item:3388}，这是{skill:171}物品：如果可以，在这里的拍卖行买一瓶（或找炼金术士）。没有药水：跳过{area:287}的药剂步骤。",
	["{zone:1454} class quests"] = "{zone:1454}职业任务",
	["{zone:1454} flight master"] = "{zone:1454}飞行管理员",
	["{zone:1456} flight master"] = "{zone:1456}飞行管理员",
	["{zone:1458} flight master"] = "{zone:1458}飞行管理员",
}

G["forever/horde/30-40/02-stranglethorn-vale"] = {
	["Back north to the camp."] = "向北回到营地。",
	["Back to {object:3202}."] = "返回{object:3202}。",
	["East of the ogres, Shadowmaw Panthers (37-38) stalk unseen until they strike; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}.\nCareful: Shadowmaw Panthers (level 37-38) and Elder Shadowmaw Panthers (level 42-43) use Sneak while out of combat, so they remain hidden until you get near them."] = "食人魔以东，影颚黑豹（37-38级）潜行跟踪直到出手；荆棘谷母虎在同一片地方游荡，偶尔掉落一枚完好的獠牙。断颚鳄鱼排列在丛林正西的河边；把它们的皮留给{npc:2495}。\n注意：影颚黑豹（37-38级）和老年影颚黑豹（42-43级）在脱战时使用潜行，所以直到你靠近才会现身。",
	["Elder Stranglethorn Tiger"] = "老年荆棘谷虎",
	["Elder tigers and Lashtail raptors"] = "老年猛虎和鞭尾迅猛龙",
	["Fly to {area:1497}"] = "飞往{area:1497}",
	["Fly to {area:1637}"] = "飞往{area:1637}",
	["Fly to {area:35}"] = "飞往{area:35}",
	["Fly to {object:3202}"] = "飞往{object:3202}",
	["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. From here on, keep every page of {quest:338} you loot: {npc:716} asks for them later."] = "沿道路向北离开{object:3202}；奈辛瓦里的狩猎营地在河东北边的山上。从现在起，留着拾取到的每一页{quest:338}：{npc:716}之后会要。",
	["Follow the road south to {area:35} at the southern tip of the vale and enter through the tunnel in the cliffs. Stay on the road: the jungle beside it is well above your level. {npc:2858}, the Horde flight master, waits on the upper deck."] = "沿道路向南前往山谷南端的{area:35}，从悬崖上的隧道进入。别离开道路：路旁丛林里的怪物比你高得多。部落飞行管理员{npc:2858}在上层甲板等候。",
	["Follow the road south to {object:3202}."] = "沿道路向南前往{object:3202}。",
	["Green Hills pages"] = "荆棘谷的青山书页",
	["Head north past Nesingwary's camp to the lake. The Venture Co. Geologists (34-36) work the camps along its western shore; they carry the Tumbled Crystals."] = "向北经过奈辛瓦里营地到湖边。风险投资公司地质学家（34-36级）在湖西岸的营地干活；他们携带滚落的水晶。",
	["Head south down the coast to {object:3202} and fly to {area:35}."] = "沿海南下到{object:3202}，然后飞往{area:35}。",
	["Lashtail Raptor"] = "鞭尾迅猛龙",
	["Level 36"] = "36级",
	["Mosh'Ogg Brute"] = "莫什奥格蛮兵",
	["Mosh'Ogg Witch Doctor"] = "莫什奥格巫医",
	["Mosh'Ogg camp"] = "莫什奥格营地",
	["Nesingwary's camp"] = "奈辛瓦里的营地",
	["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "{area:104}位于格罗姆高营地西北的近海水下。{item:4094}躺在沉没废墟旁的海底；注意呼吸和鱼人。",
	["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. {npc:716} takes the chapters later in this guide."] = "{item:2755}的每一页从血顶巨魔和劈颅巨魔身上的掉率约为1%；留着拾取到的每一页，其余的去拍卖行找。{npc:716}会在本指南稍后收取各章节。",
	["Panther"] = "黑豹",
	["Shadowmaw Panther"] = "影颚黑豹",
	["Shadowmaw panthers"] = "深喉猎豹",
	["Stranglethorn Raptor"] = "荆棘谷迅猛龙",
	["Stranglethorn Tiger"] = "荆棘谷虎",
	["Stranglethorn Tigers and Panthers (32-33) roam the hills east of the camp, along the lake shore."] = "荆棘谷猛虎和黑豹（32-33级）在营地东边沿湖岸的山丘上游荡。",
	["Take the {area:1637} zeppelin from the tower on the west side of {object:3202} and fly to {area:392}. {npc:5901} camps on the coast a short walk south of it."] = "在{object:3202}西侧的塔乘{area:1637}飞艇，然后飞往{area:392}。{npc:5901}在往南走一小段路的海岸扎营。",
	["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads.\nThe Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of {quest:338}."] = "海岸村庄里的血顶猎头者（36-37级）携带萎缩的头颅。\n血顶巨魔占据礁石以北沿岸的废墟和更远处的村庄；每一个都可能掉落{item:3915}。继续拾取{quest:338}的书页。",
	["The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp; the Lashtail Raptors (35-36) hunt further south, towards {object:3202}.\nCareful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly."] = "老年荆棘谷虎（34-35级）在营地西南的丘陵游荡；鞭尾迅猛龙（35-36级）在更南边、朝{object:3202}方向狩猎。\n注意：巨魔营地离虎区很近，鲁莽拉怪会让巨魔加入战斗。",
	["The Lashtail Raptors (35-36) hunt the jungle just north-east of {object:3202}."] = "鞭尾迅猛龙（35-36级）在{object:3202}东北不远的丛林里捕猎。",
	["The Mosh'Ogg ogres camp in the hills just east of {object:3202}. Kill one Brute and one Witch Doctor (36-37); pull them one at a time."] = "莫什奥格食人魔在{object:3202}正东的丘陵扎营。杀一个蛮兵和一个巫医（36-37级）；一次拉一个。",
	["The Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way."] = "深喉猎豹（37-38级）在莫什奥格山丘东边和东北方通往湖泊的丛林里潜行；它们会从潜行中发动攻击。沿途拾取你找到的每一页荆棘谷的青山。",
	["The Shadowmaw Panthers come much later, by {object:3202}"] = "深喉猎豹要很久以后才会遇到，在{object:3202}附近",
	["The camp by the river"] = "河边的营地",
	["The zeppelin lands at the tower on the west side of the camp."] = "飞艇降落在营地西侧的塔上。",
	["Top up here to level 36 before the hand-ins at {area:321}: they take you to level 37."] = "在去{area:321}交任务前在这里补到36级：那些任务会把你带到37级。",
	["Underwater"] = "水下",
	["Upstairs"] = "楼上",
	["Venture Co. camp"] = "风险投资公司营地",
	["West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear.\n{npc:729}, a level 37 tiger, prowls the hilltop south-west of the camp.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults."] = "营地以西，晶脊蜥蜴（34-35级）趴在岩石上；更远处村庄里的每个血顶巨魔都可能掉落耳朵。\n{npc:729}是一头37级的老虎，在营地西南的山顶游荡。\n注意：迅猛龙巢里有幼龙，你攻击成年龙时它们会加入战斗。",
	["Young Panther"] = "幼年黑豹",
	["Young Stranglethorn Tiger"] = "幼年荆棘谷虎",
	["Young Stranglethorn Tigers prowl west of the camp, Young Panthers south and east of it.\nHead west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it.\nCareful: The troll camps have many patrolling mobs, so other trolls often join a fight."] = "幼年荆棘谷虎在营地以西游荡，幼年黑豹在营地以南和以东。\n向西经过营地。荆棘谷迅猛龙（33-34级）在林间空地狩猎，血顶巨魔占据海岸的废墟：每个血顶巨魔都可能掉落獠牙。{item:4614}是它们身上极稀有的掉落：掉出来就读一读。\n注意：巨魔营地有很多巡逻怪，所以常有其他巨魔加入战斗。",
	["Zeppelin to {object:3202}"] = "乘飞艇前往{object:3202}",
	["for later: the {zone:1425}, around level 48"] = "以后再去：{zone:1425}，大约48级",
	["grind on {npc:1142}"] = "刷{npc:1142}",
	["grind on {npc:684}"] = "刷{npc:684}",
	["{area:100}: kill these as you meet them"] = "{area:100}：遇到就杀",
	["{area:102}: kill these as you meet them"] = "{area:102}：遇到就杀",
	["{area:272} flight master"] = "{area:272}飞行管理员",
	["{area:301}: kill these as you meet them"] = "{area:301}：遇到就杀",
	["{area:35} flight master"] = "{area:35}飞行管理员",
	["{area:392} flight master"] = "{area:392}飞行管理员",
	["{item:3915} on the way"] = "{item:3915}，途中",
	["{item:4106} on the way"] = "{item:4106}，途中",
	["{npc:1142} on the way"] = "{npc:1142}，途中",
	["{npc:1144} on the way"] = "{npc:1144}，途中",
	["{npc:2495}, inside"] = "{npc:2495}，在里面",
	["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}：交给阿拉希高地，路线后面会去",
	["{npc:2498}, inside"] = "{npc:2498}，在里面",
	["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}：{npc:3527}和你的{item:5177}",
	["{npc:683} on the way"] = "{npc:683}，途中",
	["{npc:684} on the way"] = "{npc:684}，途中",
	["{npc:737}, upstairs"] = "{npc:737}，楼上",
	["{npc:773}'s missing hunters' camp is Nesingwary's: walk among its tents and the investigation completes. River Crocolisks lie along the river below the camp."] = "{npc:773}失踪猎人的营地就是奈辛瓦里的营地：在帐篷间走一圈，调查就会完成。淡水鳄趴在营地下方的河边。",
	["{npc:773}, upstairs"] = "{npc:773}，楼上",
	["{zone:1434}: kill these as you meet them"] = "{zone:1434}：遇到就杀",
}

G["forever/horde/30-40/03-arathi-highlands"] = {
	["Back to {area:321}"] = "回到{area:321}",
	["Below ground"] = "在地下",
	["Boulderfist Brute"] = "石拳蛮兵",
	["Boulderfist Enforcer"] = "石拳执行者",
	["Boulderfist Magus"] = "石拳法师",
	["Boulderfist Ogre"] = "石拳食人魔",
	["Boulderfist camp"] = "石拳营地",
	["Cast {spell:18960} and take {npc:11798}'s flight to {area:1638}; {npc:3033} trains you on {area:1639}. Then fly to {zone:1454} and take the {zone:1458} zeppelin from the tower outside the main gate."] = "施放{spell:18960}，乘{npc:11798}的航班前往{area:1638}；{npc:3033}在{area:1639}训练你。然后飞往{zone:1454}，从主城门外的塔楼乘飞艇去{zone:1458}。",
	["Daggerspine Raider"] = "刺脊袭击者",
	["Daggerspine Sorceress"] = "刺脊女巫",
	["Each {object:180105} is a ring of standing stones; the key sits on the stone at its heart. The eastern circle is on the hills north-west of {area:321}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "每处{object:180105}都是一圈立石，钥匙就放在正中的石头上。东部的法阵在{area:321}西北的丘陵上。\n小心：每块中心石都有约三个接近39级的元素生物看守，不清掉它们就点石头会引来围攻：西部是燃烧流放者，外部是雷霆流放者，东部是巨浪流放者。",
	["Escort the professor down to the shore. Two Daggerspine naga ambush him on the way: stay close.\nCareful: The ambush is two level 40 water elementals, and they are immune to frost. If the fight happens inside the cave, the professor joins in instead of working and further elementals keep appearing; holding the elementals at the cave entrance, away from him, lets him finish with only the first two to deal with."] = "护送教授下到岸边。途中两名刺脊纳迦会伏击他：跟紧。\n小心：伏击者是两个40级水元素，且免疫冰霜。若战斗发生在洞穴内，教授会放下工作参战，水元素还会不断出现；把水元素拦在洞口、远离教授，他就只需应付最初两个，能顺利完工。",
	["Every rock elemental in the {zone:1418} drops {npc:6868}'s shards: the Lesser Rock Elementals (37) on the flats west of {npc:2921}'s camp are the safe ones, about one kill in five. Only the Greater Rock Elementals (42-44, well above you) in the south-western gulches drop {npc:2921}'s bracers, also about one kill in five: pull one at a time and rest between fights, or leave them. Keep killing coyotes and buzzards you still need on the way."] = "{zone:1418}的每个岩石元素都掉落{npc:6868}要的碎片：{npc:2921}营地以西平地上的次级岩石元素（37级）最安全，约五杀出一。只有西南部峡谷里的巨型岩石元素（42-44级，远高于你）掉落{npc:2921}要的护腕，同样约五杀出一：一次拉一只，打完休息，或者放弃它们。路上继续击杀还需要的土狼和秃鹫。",
	["Fleshstalker raptors"] = "猎兽龙",
	["Fly to {area:272}"] = "飞往{area:272}",
	["Fly to {area:380}"] = "飞往{area:380}",
	["Fly to {object:3202}"] = "飞往{object:3202}",
	["Head back south down the road, past the {area:1877}."] = "沿路折返向南，经过{area:1877}。",
	["Head east out of {area:272} through {area:1857} and follow the road east. The Boulderfist Ogres and Enforcers (32-34) camp south of the road, south-east of {area:313}."] = "向东穿过{area:1857}出{area:272}，沿路向东。石拳食人魔和石拳执行者（32-34级）在路以南、{area:313}东南扎营。",
	["Head north back to {area:340}. {npc:5394} stands on {area:340}'s upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart."] = "向北返回{area:340}。{npc:5394}站在{area:340}上层，远高于飞行管理员：走斜坡上去，箭头分不清楼层。",
	["Head north up the road from the {area:380} to the {area:386}; {npc:3389} keeps watch on the rise above the water."] = "从{area:380}沿路向北到{area:386}；{npc:3389}在水面上方的高地瞭望。",
	["Head north; the outer circle stands in the middle of the highlands."] = "向北走；外部法阵在高地中部。",
	["Head south-west out of Arathi over {area:880}, south through the {zone:1437} (keep clear of {area:150}) and east into {zone:1432}; the road leaves {zone:1432} to the south into the {zone:1418}. Follow it south to the goblin camp in the {area:1877}."] = "向西南经{area:880}离开阿拉希，向南穿过{zone:1437}（避开{area:150}），再向东进入{zone:1432}；道路从{zone:1432}南端通入{zone:1418}。沿路向南到{area:1877}的地精营地。",
	["Head south-west to the goblins' cove on the southern coast. {npc:2766} keeps watch on the cliff above it."] = "向西南前往南部海岸的地精海湾。{npc:2766}在海湾上方的悬崖上瞭望。",
	["Head west along the road; {npc:2921}'s camp sits in the {area:1878} halfway to {area:340}."] = "沿路向西；{npc:2921}的营地在{area:1878}，位于去{area:340}的中途。",
	["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "高地猎兽龙（36-37级）在南部高地狩猎，一群在{area:316}北边，另一群在其西边的平原上。一次拉一只。",
	["Highland Striders roam the hills all around {area:321}; both they and the Thrashers further west drop the eyes."] = "高地阔步龙在{area:321}四周的山丘上游荡；它们和更西边的高地长尾龙都会掉落眼睛。",
	["Highland raptors"] = "高地迅猛龙",
	["Into the {zone:1418}"] = "进入{zone:1418}",
	["Keep north on the road; the chest lies in the {area:1517} dig site, at the foot of the ruins north-west of the road."] = "继续沿道路向北；箱子在{area:1517}挖掘场，位于道路西北方的废墟脚下。",
	["Lesser Rock Elementals"] = "次级石元素",
	["North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "落锤镇东北，枯须狗头人在峡谷中采矿；洞口的狗头人和深处的挖掘者、勘测员都掉落密斯莱尔之尘。\n小心：每种狗头人残血时都会跑去呼救（狗头人30%，勘测员和挖掘者15%），可能引来更多。",
	["Stonevault troggs"] = "石窟穴居人",
	["The Boulderfist Brutes camp outside the ogres' hall south of {area:321}; the Magus stand among them. Pull them one at a time."] = "石拳蛮兵在{area:321}南边食人魔大厅外扎营；石拳法师站在它们中间。一次拉一个。",
	["The Elder Crag Coyotes and Giant Buzzards roam the basin south of the {area:1878}. Coyotes drop both the jawbones and the fangs; only the buzzards drop wings and gizzards.\nThe bigger Rock Elementals stand on the slopes north-west of the {area:1878}; each one drops a slab."] = "老峭壁土狼和巨型秃鹫在{area:1878}以南的盆地游荡。土狼同时掉落颚骨和尖牙；只有秃鹫掉落翅膀和砂囊。\n更大的岩石元素站在{area:1878}西北的斜坡上，每个都掉落一块石板。",
	["The Stonevault troggs dig around the cave mouths south of the {area:1877}, on the way to {area:345}; the Bonesnappers and Shamans drop the flakes."] = "石窟穴居人在{area:1877}以南、去{area:345}途中的洞口附近挖掘；石窟断骨者和石窟萨满掉落碎片。",
	["The Witherbark trolls hold the village in the south-eastern hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village.\nCareful: All three troll types flee for help at 15% health, which can pull more trolls from the nearby camps."] = "枯木巨魔盘踞在东南部丘陵的村庄里。掷斧者守着外围茅屋，巫医和猎头者占据村子中心。\n小心：这三种巨魔在15%血量时都会逃跑呼救，可能从附近营地引来更多巨魔。",
	["The inner circle lies south of the western circle, east of Stromgarde."] = "内部法阵在西部法阵南边、激流堡东边。",
	["The orc stronghold at the eastern end of the road. {npc:2851}, the wind rider master, stands by the gate."] = "道路东端的兽人要塞。双足飞龙管理员{npc:2851}站在大门旁。",
	["The small elementals drift across the flats just west of {npc:2921}'s camp. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards: keep them."] = "小型元素在{npc:2921}营地正西的平地上飘荡。这个地区的每个石元素都可能掉落{npc:6868}要的石元素的碎片：留着它们。",
	["The stone's next task needs Fozruk, a level 42 elite: leave it."] = "石头的下一个任务需要击败42级精英弗兹鲁克：放着别管。",
	["The violet shards glow just off the road a short way west of {area:321}."] = "紫色碎片在{area:321}西边不远处的路旁发光。",
	["The western circle is near {area:1857}, where you came in.\nThe Syndicate hold the walled manor and its farm in the north-west; their Highwaymen, Mercenaries and Pathstalkers carry the Bloodstone Amulets.\nCareful: Highwaymen (level 30-31) can be in Sneak, so they may be hidden when you approach."] = "西部法阵就在你进来时的{area:1857}附近。\n辛迪加占据着西北部带围墙的庄园及其农场，他们的强盗、雇佣兵和探路者身上带着血石护符。\n小心：强盗（30-31级）可能处于潜行状态，你靠近时他们也许是隐形的。",
	["The {object:138492}"] = "{object:138492}",
	["The {object:2690}"] = "{object:2690}",
	["The {object:2691}"] = "{object:2691}",
	["The {object:2701} lie at the far end of the gorge."] = "{object:2701}在峡谷最深处。",
	["The {object:2702}"] = "{object:2702}",
	["Theldurin sits among the dwarven ruins at {area:345}, south of the {area:1877}."] = "塞尔杜林坐在{area:1877}南边{area:345}的矮人废墟中。",
	["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "趁在{zone:1458}时训练：训练师在{object:36070}、{object:36073}和{object:36082}（圣骑士：{npc:260093}）。",
	["Underwater"] = "水下",
	["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "海湾西边，刺脊袭击者和刺脊巫师（38-40级）占据海岸：一次拉一个。两艘沉船在近海浅水中，海图和日志在船里；宝石在沉船周围的海底。",
	["Witherbark Axe Thrower"] = "枯木掷斧者",
	["Witherbark Headhunter"] = "枯木猎头者",
	["Witherbark Witch Doctor"] = "枯木巫医",
	["Your trainer is in {area:1638}, one flight from {zone:1454}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly on to the {area:380} from there."] = "你的训练师在{area:1638}，从{zone:1454}飞一次即到：{area:1639}的{npc:3033}（德鲁伊），{npc:246344}（圣骑士）。然后从那里飞往{area:380}。",
	["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
	["Zeppelin to {zone:1458}"] = "乘飞艇去{zone:1458}",
	["for Helgrum in {area:75}, around level 42"] = "交给{area:75}的赫格拉姆，约42级",
	["for {npc:2487} in {area:35}, around level 44"] = "交给{area:35}的{npc:2487}，约44级",
	["{area:1878}: kill these as you meet them"] = "{area:1878}：遇到了就杀",
	["{area:328}: kill these as you meet them"] = "{area:328}：遇到了就杀",
	["{area:334}: kill these as you meet them"] = "{area:334}：遇到了就杀",
	["{area:340} flight master"] = "{area:340}飞行管理员",
	["{area:340} is the Horde fortress built into the cliffs at the zone's western edge. {npc:5394} stands on {area:340}'s upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart."] = "{area:340}是建在本区西部边缘悬崖上的部落要塞。{npc:5394}站在{area:340}上层，远高于飞行管理员：走斜坡上去，箭头分不清楼层。",
	["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}，给\"沼泽之眼\"加尔",
	["{npc:2771}'s next {quest:678} is against Boulderfist elites: leave it."] = "{npc:2771}的下一个{quest:678}要对付石拳精英：放着别管。",
	["{npc:2920}: only if you carry {item:2868} ({skill:164} or the Auction House)"] = "{npc:2920}：仅当你携带{item:2868}时（{skill:164}或拍卖行）",
	["{npc:6868}, inside"] = "{npc:6868}，在里面",
	["{object:1661} has no Hunter or Shaman trainer: take the {zone:1454} zeppelin from the same tower instead and train in the city, then take the {zone:1458} zeppelin from the tower outside {zone:1454}'s main gate."] = "{object:1661}没有猎人或萨满祭司训练师：改从同一座塔楼乘飞艇前往{zone:1454}，在城里训练，然后从{zone:1454}正门外的塔楼乘飞艇前往{zone:1458}。",
	["{quest:1106}: Fizzle's letter from the {area:439}"] = "{quest:1106}：来自{area:439}的菲兹尔的信",
	["{zone:1418}: kill these as you meet them"] = "{zone:1418}：遇到了就杀",
	["{zone:1454} flight master"] = "{zone:1454}飞行管理员",
	["{zone:1458} flight master"] = "{zone:1458}飞行管理员",
	["{zone:1458} trainers"] = "{zone:1458}的训练师",
}

G["forever/horde/30-40/04-dustwallow-marsh"] = {
	["Back to {area:496}"] = "回到{area:496}",
	["Fly to {area:2408}"] = "飞往{area:2408}",
	["Fly to {area:378}"] = "飞往{area:378}",
	["Fly to {area:392}"] = "飞往{area:392}",
	["For {npc:2519} at {object:3202}, in the next guide"] = "交给{object:3202}的{npc:2519}，在下一个指南中",
	["Head back west to Brackenwall with the head."] = "带着头颅往西回到蕨墙村。",
	["Head east back to the {area:497}."] = "往东回到{area:497}。",
	["Head east from {area:378} along the road into the marsh. The burned-out {area:403} stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "从{area:378}沿路往东进入沼泽。刚过边界，路边就是烧毁的{area:403}；盾牌、徽章和蹄印都在废墟里和废墟旁。",
	["Head east to {area:602}. Use the Rod of Banishing by each demon portal to close six of them.\nCareful: Infernals, Doomguards and Burning Blade Summoners walk close by many portals and may join in; kill nearby mobs first or drag the guardian away, for example toward the coven's central lake."] = "往东到{area:602}。在每个恶魔传送门旁使用放逐之杖，关闭其中六个。\n小心：地狱火、末日守卫和燃刃召唤者会在许多传送门附近走动，可能加入战斗；先清掉附近的怪物，或者把守卫引开，比如引向集会所中央的湖。",
	["Head north to {area:502}. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "往北到{area:502}。臭臭站在山脚下；护送他，让他去山丘南边采集沼泽豆叶。",
	["Head north to {npc:5412} at {area:597}."] = "往北到{area:597}的{npc:5412}处。",
	["Head north up the road to the hut by the road north of the graveyard."] = "沿路向北，到墓地以北路边的小屋。",
	["Head north-east to the {area:607}. {npc:12277} is held in the Maraudine centaur camp; free her and escort her out east of the valley.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "往东北到{area:607}。{npc:12277}被关在玛拉多半人马营地；救出她并护送她到山谷以东。\n小心：脚本刷出的队伍是仇恨联动的，而且只在护送期间出现，所以无法事先清掉，也不能一只只拉。出发前把路上的普通半人马清掉确实有帮助。",
	["Head on south-west to Shadowprey."] = "继续向西南到暗影村。",
	["Head south along the coast from {area:392} to {area:720}. {npc:6236} stands by the arena: step on the grate to start the fight; the challengers come one at a time, then {npc:6238} (33)."] = "从{area:392}沿海岸向南到{area:720}。{npc:6236}站在竞技场旁：踏上铁栅格开始战斗；挑战者会一个个上来，最后是{npc:6238}（33级）。",
	["Head south from {area:2405} into the {area:607}. The Maraudine Scouts, Wranglers, Maulers, Windchasers and Marauders (36-39) drop the {quest:93225}."] = "从{area:2405}向南进入{area:607}。玛拉多斥候、牧者、殴打者、追风者和掠夺者（36-39级）会掉落{quest:93225}。",
	["Head south-east from the coven to the bone fields of the {area:2657}, where Undead Ravagers roam. At the far south-east, use the {item:15848} to draw the Magrami Spectres: they drop the ghost-o-plasm."] = "从集会所往东南到{area:2657}的骸骨旷野，那里有亡灵劫掠者游荡。在最东南角使用{item:15848}引出玛格拉姆幽灵：它们掉落幽灵原生质。",
	["Head west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely.\nThe Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes.\nCareful: Darkfang Lurkers (level 36-37) use Sneak to stealth while out of combat and cast Poison once fighting.\nCareful: Stealthed spiders in the same area will attack you on sight.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "往西穿回沼泽。蕨墙村以北山脊上的暗牙毒唾者掉落毒囊。塞拉摩渗透者（35-36级）在同一片树林里潜行：他们处于潜行状态，要仔细找。\n暗雾蜘蛛成群占据蕨墙村西北的洞口；每种都会掉眼睛。\n小心：暗牙潜伏者（36-37级）在战斗外使用潜行，开战后会施放毒药。\n小心：同一区域的潜行蜘蛛看到你就会攻击。\n小心：暗雾潜伏者潜行移动，进入战斗后会使用毒药。这些蜘蛛站得很密，很容易引来额外的怪；从外围单独拉可以少引一些。",
	["His next errand is not on this route."] = "他的下一个任务不在这条路线上。",
	["Jarl lives in the {area:497} south-east of {area:502}."] = "加尔住在{area:502}东南的{area:497}。",
	["Kodo bones"] = "科多兽骨头",
	["Maraudine totems"] = "玛洛迪图腾",
	["Mirefin murlocs"] = "黑鳍鱼人",
	["On the top floor"] = "在顶层",
	["Pick up the kodo bones scattered across the graveyard."] = "拾取散落在墓地各处的科多兽骨头。",
	["Shadowprey"] = "暗影村",
	["Slitherblade Myrmidon"] = "滑刃侍从",
	["Slitherblade Naga"] = "滑刃纳迦",
	["Slitherblade Sorceress"] = "滑刃女巫",
	["Slitherblade coast"] = "滑刃海岸",
	["Stinky Ignatz"] = "伊格纳兹",
	["Swamp Eye Jarl"] = "“沼泽之眼”加尔",
	["Take the road north at the fork to the ogre village of Brackenwall."] = "在岔路口沿道路向北，前往食人魔村庄蕨墙村。",
	["The Burning Blade hold the fortress north-west of {area:2407}. Use the {item:14523} on the {npc:11876} in the fortress to get the {item:13542}."] = "火刃氏族占据着{area:2407}西北的要塞。在要塞里对{npc:11876}使用{item:14523}，获得{item:13542}。",
	["The Mirefin murlocs crowd the coast east and north-east of {area:502}; every kind drops heads."] = "黑鳍鱼人聚集在{area:502}东边和东北边的海岸上；每种都会掉落头。",
	["The Seer stands on the south side of {area:599}, east of {area:2405}. Clear the cultists around it first."] = "先知站在{area:599}南侧、{area:2405}以东。先清掉它周围的信徒。",
	["The Slitherblade naga hold the coast north of {area:2405}, up to {area:598}. {npc:12369} guards the {quest:6027} at the far northern tip."] = "滑刃纳迦占据着{area:2405}北边直到{area:598}的海岸。{npc:12369}在最北端守护着{quest:6027}。",
	["The next guide takes you back to {zone:1434}."] = "下一个指南会带你回到{zone:1434}。",
	["The {area:2657}"] = "{area:2657}",
	["Theramore Infiltrator"] = "塞拉摩渗透者",
	["Underwater"] = "水下",
	["Your trainer is in {area:1638}: fly there (no flight path there yet? fly to {area:378} and head west through {zone:1412}), then on to {area:496}."] = "你的训练师在{area:1638}：飞过去（如果那里还没有飞行点，就先飞到{area:378}，穿过{zone:1412}往西），然后再去{area:496}。",
	["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "仅当你带着{item:3853}时（{skill:164}或拍卖行）",
	["{area:380} flight master"] = "{area:380}飞行管理员",
	["{area:392} flight master"] = "{area:392}飞行管理员",
	["{area:496} flight master"] = "{area:496}飞行管理员",
	["{area:496}: kill these as you meet them"] = "{area:496}：遇到这些就杀",
	["{npc:4501}, below ground"] = "{npc:4501}，在地下",
	["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}，在道路进入村庄处的南缘",
	["{npc:4711} walks around {area:598}: look inside the circle on the map"] = "{npc:4711}在{area:598}一带走动：看地图圆圈内",
	["{npc:4714} walks around {area:598}: look inside the circle on the map"] = "{npc:4714}在{area:598}一带走动：看地图圆圈内",
	["{npc:4983} waits in the {area:2302} east of the village. Follow him to Reethe and keep him alive through the fight that breaks out."] = "{npc:4983}在村庄东边的{area:2302}等候。跟着他去找雷瑟，并在随后爆发的战斗中保护他活下来。",
	["{npc:5395} and {npc:5412} stand in the post just west of Smeed's camp."] = "{npc:5395}和{npc:5412}站在斯米德营地西边的哨所里。",
	["{npc:6019} waits at the goblin camp on the west side of the {area:596}."] = "{npc:6019}在{area:596}西侧的地精营地里等候。",
	["{object:20985}, beside the manor"] = "{object:20985}，在庄园旁边",
	["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}，现在{npc:4791}已经读过报告了",
	["{quest:1218}, for \"Swamp Eye\" Jarl"] = "{quest:1218}，给“沼泽之眼”贾尔",
	["{zone:1456} flight master"] = "{zone:1456}飞行管理员",
}

G["forever/horde/40-50/01-stranglethorn-vale"] = {
	["\"Sea Wolf\" MacKinley, on the top floor"] = "“海狼”麦金利，在顶层",
	["Below ground"] = "地下",
	["Bloodsail Swashbuckler"] = "血帆剑客",
	["Boat to {area:35}"] = "乘船前往{area:35}",
	["Boat to {area:392}"] = "坐船到{area:392}",
	["Chucky \"Ten Thumbs\""] = "“十指”查基",
	["Draenethyst crystals"] = "德莱尼水晶",
	["Fly to {area:35}"] = "飞到{area:35}",
	["Fly to {area:75}"] = "飞到{area:75}",
	["Fly to {object:3202}"] = "飞往{object:3202}",
	["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "沿海岸向南。纳迦探险者在岸边涉水而行，携带一捆海蛇草；{object:759}就在他们正东的山丘里冒泡。",
	["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "再往北，风险投资公司的地精在路东的矿场挖掘；矿工、工头、测量员和修理工都会掉水晶。\n注意：潜行的暗牙豹和荆棘谷母虎会在营地周围游荡。",
	["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "把猩猩牙交给安巴格瓦并待在他身边：他会召唤三波猩猩，然后是{npc:1514}。一次对付一个。",
	["Head east to {area:75}, in the reeds south of the road."] = "向东到{area:75}，在路南的芦苇丛里。",
	["Head north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. {npc:1059} guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all."] = "向北到风险投资公司矿场以东的劈颅者废墟；一次拉一个猎头者和狂战士。{npc:1059}守着西南的废墟，废墟北侧有一堆战利品头骨。每个劈颅者都可能掉獠牙或项链：项链是最慢的部分，所以就在废墟以北的战士营地里继续杀，直到集齐。",
	["Head north up the road to the hunters' camp."] = "沿路向北到猎人营地。",
	["Head north up the road; the hunters camp on the hill above the river."] = "沿路向北；猎人们在河上方的山丘扎营。",
	["Head south to {area:35}. Shaky Phillipe waits on the docks."] = "向南到{area:35}。发抖的菲利普在码头上等着。",
	["Head west to {object:3202}."] = "向西到{object:3202}。",
	["His strongbox waits at his old camp north of {area:75}."] = "他的保险箱在{area:75}北边他原来的营地里。",
	["If you skipped {quest:192} or {quest:195}, grind here to level 42.68 to stay on the route's plan."] = "如果跳过了{quest:192}或{quest:195}，在这里刷到42.68级，以保持在路线计划内。",
	["If you skipped {quest:208}, grind here to level 42.74 to stay on the route's plan."] = "如果跳过了{quest:208}，在这里刷到42.74级，以保持在路线计划内。",
	["Inside"] = "里面",
	["Inside {area:1742}"] = "在{area:1742}里面",
	["Into the {area:8}"] = "进入{area:8}",
	["Jon-Jon the Crow"] = "乌鸦乔恩乔恩",
	["Jungle Stalker"] = "丛林潜伏者",
	["Jungle Stalkers"] = "丛林潜伏者",
	["Jungle stalkers"] = "丛林捕猎者",
	["Keep going north into {area:10}, then east along the road through {zone:1430} into the swamp. {npc:1776} waits at the {area:657}, the draenei camp near the way in from {zone:1430}."] = "继续向北进入{area:10}，然后沿路向东穿过{zone:1430}进入沼泽。{npc:1776}在{area:657}等着，那是从{zone:1430}进来处附近的德莱尼营地。",
	["Leave town by the tunnel; the note lies in the pirates' cove just north of {area:35}."] = "从隧道出城；信件在{area:35}正北的海盗海湾里。",
	["Level 42.68"] = "42.68级",
	["Level 42.74"] = "42.74级",
	["Maury \"Club Foot\" Wilkins"] = "“畸形脚”莫里·威尔金斯",
	["Mistvale gorillas"] = "迷雾谷猩猩",
	["Naga Explorer"] = "纳迦探险者",
	["Nesingwary's camp"] = "奈辛瓦里营地",
	["Noboru the Cudgel"] = "棍棒诺博鲁",
	["Noboru wanders the clearing south-west of the {area:76}; his cudgel starts a quest."] = "木棒诺博鲁在{area:76}西南的空地上游荡；他的木棒可以开始一个任务。",
	["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "在迷雾谷东北，赞吉尔的追随者在丛林里扎营；他们每个人都可能携带赞吉尔的药剂。",
	["Pirate ghosts"] = "海盗幽灵",
	["Raptors: Zjolnir, beside {npc:7953} in {area:367}."] = "迅猛龙：佐尔尼尔，在{area:367}的{npc:7953}旁边。",
	["Ride back east past {area:75} and follow the road south-east to the small Horde post on the shore."] = "向东骑回{area:75}，沿道路向东南前往岸边的部落小哨站。",
	["Ride north-east to the {area:76}. The crystals stand along the way up to {npc:5391}'s cage."] = "向东北骑往{area:76}。水晶分布在通往{npc:5391}笼子的路上。",
	["Ride west along the road to the draenei camp at the {area:657}, near the way in from {zone:1430}."] = "沿道路向西骑往{area:657}的德莱尼营地，靠近{zone:1430}的入口。",
	["Riding at 40"] = "40级骑术",
	["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:7953} in {area:367} on the {zone:1411} coast, with Zjolnir's raptors (20 gold each) beside him. Another race's trainer (Kildar in {zone:1454}) teaches you only once you are Exalted with his city."] = "骑术需要40级，花费100金；学会后会送你一只坐骑。每个种族在自己种族的训练师那里学习：你的是{zone:1411}海岸{area:367}的{npc:7953}，他旁边还有佐尔尼尔的迅猛龙（每只20金）。其他种族的训练师（{zone:1454}的基尔达）只在你对他的城市达到崇拜后才会教你。",
	["Sawtooth crocolisks"] = "盐齿鳄鱼",
	["Skullsplitter Berserker"] = "劈颅者狂战士",
	["Skullsplitter Headhunter"] = "劈颅者猎头者",
	["Skullsplitter Hunter"] = "劈颅者猎人",
	["Skullsplitter warriors"] = "劈颅战士",
	["South of Booty Bay the Bloodsail swashbucklers camp on the {area:43}; the charts and the orders lie in their tents. Any Bloodsail can carry snuff and {npc:2493}'s eye, so keep killing until you have both.\nTake the road south towards {area:35}. The Elder Mistvale Gorillas (40-41) live in {area:1737}, east of the road; about one in twenty carries an aged sinew."] = "藏宝海湾以南，血帆剑客在{area:43}扎营；海图和命令就在他们的帐篷里。任何血帆海盗都可能带着鼻烟和{npc:2493}的眼睛，所以一直杀到两样都拿到。\n沿路向南前往{area:35}。年长的薄雾谷猩猩（40-41级）住在路东的{area:1737}；大约二十只里有一只带着陈旧肌腱。",
	["Take the road north out of {area:35}; Unbagwa sits on a hill in {area:1737}, east of the road."] = "沿道路向北离开{area:35}；安巴格瓦坐在道路东边{area:1737}的一座山丘上。",
	["The Bloodsail ships"] = "血帆海盗船",
	["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights."] = "丛林潜伏者（40-41级）在{object:3202}以南的海岸活动。它们比你高不少：一次拉一只，打完就休息。",
	["The boat lands in {area:35}'s harbour. The quest givers stand on the boardwalks around the harbour and in the inn."] = "船停靠在{area:35}的港口。任务给予者站在港口周围的木栈道上和旅店里。",
	["The crocolisks wallow in the pools around {npc:5391}'s camp and south towards {area:75}; about one in four drops a flank.\nCareful: {npc:5592}'s camp sits by the coast. Along the way to it you pass level 40 spiders that chase a long distance, plus stealthed Shadow Panthers."] = "鳄鱼在{npc:5391}营地周围的水池里以及往南到{area:75}一带打滚；大约四只掉一块腹肉。\n注意：{npc:5592}的营地就在海边。去那里的路上会经过40级的蜘蛛，它们会追很远，还有潜行的暗影豹。",
	["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "猩猩在安巴格瓦周围的山谷里游荡。老迈的猩猩掉落内脏；任何猩猩都可能掉落猩猩牙。",
	["The next guide flies you north to {area:272} and into the {zone:1417}."] = "下一份攻略会带你向北飞到{area:272}，进入{zone:1417}。",
	["The next trophy skulls stand in the small ruins just north of the warriors' camp.\nThe last skulls are in the ruins a short walk west, on the way back to {object:3202}."] = "下一堆战利品头骨在战士营地正北的小废墟里。\n最后的头骨在往西走一小段的那处废墟，就在回{object:3202}的路上。",
	["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "丛林捕猎者迅猛龙在{object:3202}南边的丛林里捕猎，一直到西海岸。",
	["The three ghostly pirates haunt the jungle north of {area:35}, near Zanzil's camps: {npc:2535} and {npc:2536} stand together, {npc:2537} further east."] = "三个海盗幽灵在{area:35}北边、赞吉尔营地附近的丛林里出没：{npc:2535}和{npc:2536}站在一起，{npc:2537}在更东边。",
	["The three ships lie off the {area:43}. The crews are 42-45, Stillwater 45, Keelhaul 46 and {npc:2546} 48: at 41 this is a fight for a group, or for the end of the guide. If you go, swim out and pull the crew to the rail one at a time. A scroll, {quest:624}, lies on the ships' decks: take it."] = "三艘船停在{area:43}外的海面上。船员是42-45级，斯蒂沃特船长45级，尼哈鲁船长46级，{npc:2546}48级：41级时这是小队的战斗，或者留到本指南结束时再来。如果要去，就游过去，把船员一个个引到船舷边。船的甲板上有一张卷轴{quest:624}：拿上它。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:728} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人来一起做。{npc:728}是40级精英：大多数职业42级可以单挑，但可能需要帮忙。如果只有你一个人就跳过：路线会安排你刷怪补经验。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:730} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "这些是精英怪：建议组队，找人来一起做。{npc:730}是43级精英：大多数职业45级可以单挑，但可能需要帮忙。如果只有你一个人就跳过：路线会安排你刷怪补经验。",
	["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:731} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, {npc:731} calls for help from creatures within 20 yd."] = "这些是精英怪：建议组队，找人来一起做。{npc:731}是43级精英：大多数职业45级可以单挑，但可能需要帮忙。如果只有你一个人就跳过：路线会安排你刷怪补经验。\n注意：老虎和潜行的暗牙豹在他附近游荡。拉他之前先清掉。开打后，{npc:731}会向20码内的生物呼救。",
	["To {area:392}"] = "前往{area:392}",
	["Venture Co. mine"] = "风险投资公司矿洞",
	["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them."] = "在远征队营地西边，血顶酋长{npc:1061}和{npc:1062}一起站在祖昆达废墟里。先清掉他们的守卫，再引他们。",
	["You start in {area:75}. Bind here: you hearth back after the coast."] = "你从{area:75}开始。在这里绑定炉石：海岸那边结束后炉石回来。",
	["Zanzil's camps"] = "赞吉尔的营地",
	["Zul'Kunda"] = "祖昆达废墟",
	["Zul'Mamwe"] = "祖玛维废墟",
	["for Stoley in {zone:1446}; on the top floor"] = "给{zone:1446}的斯托雷；在顶层",
	["for a later stop in the {area:8}"] = "为之后在{area:8}的一站准备",
	["grind on {npc:667}"] = "刷{npc:667}",
	["the {object:2076}"] = "{object:2076}",
	["the {object:2076}, beside Nimboya"] = "{object:2076}，宁博亚旁边",
	["{area:127}: kill these as you meet them"] = "{area:127}：遇到就杀",
	["{area:1577}: kill these as you meet them"] = "{area:1577}：遇到就杀",
	["{area:1737}: kill these as you meet them"] = "{area:1737}：遇到就杀",
	["{area:35} flight master"] = "{area:35}飞行管理员",
	["{area:75} flight master"] = "{area:75}飞行管理员",
	["{npc:1442}, upstairs"] = "{npc:1442}，楼上",
	["{npc:1443}, on the top floor"] = "{npc:1443}，在顶层",
	["{npc:2488}, on the top floor"] = "{npc:2488}，在顶层",
	["{npc:2495}: the Snapjaw skins gathered earlier; inside"] = "{npc:2495}：之前收集的钳嘴鳄皮；在里面",
	["{npc:2498}, inside"] = "{npc:2498}，在里面",
	["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391}被关在沼泽东北的{area:76}。救出他并跟着他出去，击退追赶他的沼泽生物。",
	["{npc:5591}, inside"] = "{npc:5591}，在里面",
	["{npc:669} walks around here: look inside the circle on the map"] = "{npc:669}在这附近走动：看地图上的圆圈内",
	["{npc:6807}, upstairs"] = "{npc:6807}，楼上",
	["{npc:6930}, upstairs"] = "{npc:6930}，楼上",
	["{npc:737}, upstairs"] = "{npc:737}，楼上",
	["{npc:773}: for {quest:2864} in {area:976}; upstairs"] = "{npc:773}：为{area:976}的{quest:2864}；楼上",
	["{npc:7953}, riding trainer"] = "{npc:7953}，骑术训练师",
	["{object:3202} flight master"] = "{object:3202}飞行管理员",
}

G["forever/horde/40-50/02-feralas"] = {
	["Back to {area:976}"] = "回到{area:976}",
	["Fly to {area:1637}"] = "飞往{area:1637}",
	["Fly to {area:1638}"] = "飞往{area:1638}",
	["Fly to {area:484}"] = "飞往{area:484}",
	["Fly to {area:976}"] = "飞往{area:976}",
	["Fly to {object:3202}"] = "飞往{object:3202}",
	["Fly to {zone:1454}. The Droffers brothers run their shop in the Drag.\n{object:172958}, then the {object:172960} and the {object:172961}."] = "飞往{zone:1454}。德罗弗斯兄弟在暗巷区开着店。\n{object:172958}，然后是{object:172960}和{object:172961}。",
	["Gordunni Brute"] = "戈杜尼蛮兵",
	["Gordunni Mauler"] = "戈杜尼重击者",
	["Gordunni Ogre"] = "戈杜尼食人魔",
	["Gordunni Ogre Mage"] = "戈杜尼食人魔法师",
	["Gordunni Shaman"] = "戈杜尼萨满祭司",
	["Gordunni Warlock"] = "戈杜尼术士",
	["Grimtotem camp"] = "恐怖图腾营地",
	["Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest."] = "继续向西骑到海岸。海滩上的海滩龙虾人先知和海滩利爪龙虾人大约每杀四十只掉落一个OOX-22/FE定位器：如果掉了，就使用它开始任务。",
	["Kodos: {npc:3685}, beside {npc:3690} in {area:222}."] = "科多兽：{npc:3685}，在{area:222}的{npc:3690}旁边。",
	["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "在豺狼人北边，食人魔占据着一座山顶前哨站；把食人魔法师引到你身边来打。戈杜尼钴矿石在前哨站周围的土堆里，戈杜尼卷轴就在前哨站里的地上。",
	["Only with the distress beacon: the robot sits in a small cave on the north side of {area:1105}. Escort it to the dock on the {area:1108}; yetis and gorillas ambush you on the way. Its reward waits in {area:35} for a later visit.\nCareful: Three ambushes spawn during the escort, and the robot warns you before each one. The first is 3 yetis, just after the robot leaves the cave and climbs toward the road. The second is 3 gorillas, on the path that runs along the cliff. The third is about 4 gnolls, one of them a caster, where the route turns off toward the dock."] = "只有拿到求救信号器才能做：机器人待在{area:1105}北侧的一个小洞里。护送它到{area:1108}的码头；路上有雪人和猩猩伏击你。奖励留在{area:35}，以后再去领。\n注意：护送途中会刷三波伏击，机器人每次都会提前警告。第一波是3只雪人，在机器人离开山洞爬向大路后；第二波是3只猩猩，在沿悬崖的小路上；第三波约4只豺狼人，其中一只是法系，在路线拐向码头的地方。",
	["Ride north-east to the goblin harbour on the coast."] = "向东北骑往海岸边的地精港口。",
	["Ride south-west to the ogre ruins below {area:1105}. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb."] = "向西南骑往{area:1105}下方的食人魔废墟。里面满是戈杜尼萨满祭司、戈杜尼术士和戈杜尼虐待者；南端的戈杜尼大法师携带宝珠。",
	["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "骑术与风行者：{npc:265756}，在泽弗拉斯岛{area:16638}的{area:17684}。",
	["Riding at 40"] = "40级学骑术",
	["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:3690} in {area:222}, with {npc:3685}'s kodos (20 gold each) beside him. Another race's trainer ({npc:4752} in {zone:1454}) teaches you only once you are Exalted with his city."] = "骑术需要40级，花费100金；学会即获得坐骑。每个种族向本族的训练师学习：你的是{area:222}的{npc:3690}，旁边是{npc:3685}的科多兽（每头20金）。其他种族的训练师（{zone:1454}的{npc:4752}）只在你与其主城声望崇拜后才教你。",
	["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:4773} in {area:159}, with {npc:4731}'s skeletal horses (20 gold each) beside her. Another race's trainer ({npc:4752} in {zone:1454}) teaches you only once you are Exalted with his city."] = "骑术需要40级，花费100金；学会即获得坐骑。每个种族向本族的训练师学习：你的是{area:159}的{npc:4773}，旁边是{npc:4731}的骸骨军马（每匹20金）。其他种族的训练师（{zone:1454}的{npc:4752}）只在你与其主城声望崇拜后才教你。",
	["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel. Skyborne learn it from {npc:265756} at the {area:17684} in {area:16638} on Zephras Isle, with a Galestrider: the skyboat to the isle leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "骑术需要40级，花费100金；学会即获得坐骑。{npc:4752}在{object:172958}教兽人，就在{npc:3362}的兽栏旁。空裔在泽弗拉斯岛{area:16638}的{area:17684}找{npc:265756}学习，坐骑是风行者：前往该岛的天艇从{zone:1456}以北、{area:17045}以南的悬崖出发，约每五分钟一班。你种族的其他坐骑每只20金：“收藏·坐骑·40级”里有每只的指南。",
	["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "骸骨军马：{npc:4731}，在{area:159}的{npc:4773}旁边。",
	["South along the coast, the Southsea pirates hold the cove. {npc:7883} and the stolen cargo are on the docks at its far end. Any pirate can drop a hat, the kidnappers most often.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "沿海岸向南，南海海盗盘踞着那处海湾。{npc:7883}和被盗的货物在海湾尽头的码头上。任何海盗都可能掉帽子，绑匪掉率最高。\n注意：{npc:7883}身边有两三个海盗，开打后镇上还会有更多海盗加入战斗。",
	["Southsea Dock Worker"] = "南海码头工人",
	["Southsea Freebooter"] = "南海劫掠者",
	["Southsea Pirate"] = "南海海盗",
	["Southsea Swashbuckler"] = "南海剑客",
	["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "恐怖图腾牛头人在小精龙的树林旁扎营；恐怖图腾袭击者、恐怖图腾博学者和恐怖图腾萨满祭司都携带恐怖图腾之角。",
	["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane.\nCareful: Every Woodpaw gnoll except the Alpha runs off for help at 15% health, which can pull more gnolls into the fight."] = "木爪豺狼人在莫沙彻西北方的丘陵扎营；任何一只都可能掉鬃毛。\n注意：除了头领以外，每只木爪豺狼人都会在15%血量时逃跑求援，可能把更多豺狼人拉进战斗。",
	["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "祖卡什异种蝎的巢穴深入营地东南的山丘；{quest:7731}在最深处的洞室里等候。",
	["The bandits and thieves camp in the dunes east of {area:976}. Every Wastewander can carry a water pouch: keep ten, five for each of Luglunket's bounties.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "废土强盗和窃贼在{area:976}以东的沙丘扎营。每个废土匪徒都可能带着水袋：留十个，拉格伦凯特的两份悬赏各要五个。\n注意：废土盗贼（43-44级）潜行移动，可能在你毫无察觉时靠近。",
	["The battle map lies in the Woodpaw camp south of Mojache."] = "木爪作战地图在莫沙彻营地南边的木爪营地里。",
	["The shadow mages, rogues and assassins camp south-east of {area:976}.\nSouth-east of Gadgetzan the Wastewander bandits camp in the dunes; {npc:7847} stands in the eastern camp.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "废土暗法师、盗贼和刺客在{area:976}东南方扎营。\n加基森东南方，废土强盗在沙丘里扎营；{npc:7847}在东边的营地。\n注意：废土盗贼脱战时一直保持潜行，所以你在营地开打时可能有隐藏的盗贼加入。\n注意：两名潜行的废土盗贼无论他走到哪都跟着。在他的刷新营地，两名暗法师及其仆从离得很近，会加入战斗。在瞭望塔那边可以单独打他。",
	["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour.\nCareful: Most Alphas sit in small tent camps with 2-4 other gnolls that join the fight, and other gnolls patrol between the camps."] = "小精龙在莫沙彻正西的树林上空飞舞；几乎每只都掉翅膀。木爪头领统领着西南方的营地：一小时内杀完。\n注意：大多数头领待在有2-4只其他豺狼人的小帐篷营地里，开打会一起上，营地之间还有豺狼人巡逻。",
	["Upstairs"] = "楼上",
	["Wastewander Assassin"] = "废土刺客",
	["Wastewander Bandit"] = "废土强盗",
	["Wastewander Rogue"] = "废土盗贼",
	["Wastewander Shadow Mage"] = "废土暗法师",
	["Wastewander Thief"] = "废土窃贼",
	["Wolves: {npc:3362}, beside {npc:4752}."] = "狼：{npc:3362}，在{npc:4752}旁边。",
	["Woodpaw Alpha"] = "木爪头领",
	["Woodpaw battle map"] = "木爪作战地图",
	["Woodpaw north camp"] = "木爪北营地",
	["Your trainer is in {area:1638}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly there from {area:976}, then back to {area:976}."] = "你的训练师在{area:1638}：{area:1639}上的{npc:3033}（德鲁伊）、{npc:246344}（圣骑士）。从{area:976}飞过去，然后飞回{area:976}。",
	["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
	["Zeppelin to {zone:1458}"] = "乘飞艇去{zone:1458}",
	["for the {zone:1425}, around level 48"] = "交给{zone:1425}，大约48级时",
	["for {zone:1454}, around level 45"] = "交给{zone:1454}，大约45级时",
	["water pouches in your bags"] = "背包里的废土水袋",
	["{area:1099} flight master"] = "{area:1099}飞行管理员",
	["{area:1336}: kill these as you meet them"] = "{area:1336}：遇到就杀",
	["{area:1937}: kill these as you meet them"] = "{area:1937}：遇到就杀",
	["{area:2522}: kill these as you meet them"] = "{area:2522}：遇到就杀",
	["{area:357}: kill these as you meet them"] = "{area:357}：遇到就杀",
	["{area:392} flight master"] = "{area:392}飞行管理员",
	["{area:392} for the Felsteed"] = "前往{area:392}做地狱战马任务",
	["{area:75} flight master"] = "{area:75}飞行管理员",
	["{area:976} flight master"] = "{area:976}飞行管理员",
	["{area:976} is the walled goblin town just past the {area:440} border."] = "{area:976}是过了{area:440}边界后那座有城墙的地精城镇。",
	["{area:985}: kill these as you meet them"] = "{area:985}：遇到就杀",
	["{npc:3690}, riding trainer"] = "{npc:3690}，骑术训练师",
	["{npc:4752}, riding trainer"] = "{npc:4752}，骑术训练师",
	["{npc:4773}, riding trainer"] = "{npc:4773}，骑术训练师",
	["{npc:5234} walks around {area:2522}: look inside the circle on the map"] = "{npc:5234}在{area:2522}一带走动：查看地图上的圆圈范围",
	["{npc:7777} walks around {area:1099}: look inside the circle on the map"] = "{npc:7777}在{area:1099}一带走动：查看地图上的圆圈范围",
	["{npc:7854}, inside"] = "{npc:7854}，在屋里",
	["{npc:7875}: for {npc:7010} in {zone:1454}, around level 50"] = "{npc:7875}：交给{zone:1454}的{npc:7010}，约50级",
