	["tame one with {npc:252389}'s first {item:15908} while you are among them"] = "身处它们之中时，用{npc:252389}的第一根{item:15908}驯服一只",
	["the bounty board"] = "悬赏布告板",
	["{area:16622}: kill these as you meet them"] = "{area:16622}：遇到就杀",
	["{area:16623}: kill these as you meet them"] = "{area:16623}：遇到就杀",
