G["forever/reputation/orgrimmar"] = {
	["+150"] = "+150",
	["A {npc:3118} may drop a {item:277661}: use it to start {quest:97281}. Once you hand that in, {npc:3293} offers {quest:97282}."] = "某个{npc:3118}可能掉落{item:277661}：使用它以接取{quest:97281}。交完后，{npc:3293}提供{quest:97282}。",
	["Around the {area:380}"] = "{area:380}一带",
	["Berserk Owlbeast"] = "狂暴枭兽",
	["Blackrock Mountain, with a group"] = "黑石山，组队前往",
	["Blood Elf Reclaimer"] = "血精灵收复者",
	["Blood Elf Surveyor"] = "血精灵勘测员",
	["Bloodtalon Matriarch Eggs"] = "血爪女族长之蛋",
	["Boars, weapons and peons"] = "野猪、武器和苦工",
	["Dustwind Savage"] = "尘风野蛮人",
	["Dustwind Storm Witch"] = "尘风风暴巫女",
	["Exalted with {faction:76}"] = "与{faction:76}崇拜",
	["Find {npc:8578}'s camp"] = "找到{npc:8578}的营地",
	["Fly to {area:1237} in western {zone:1447}. {npc:8576} sends you north-east to the blood elf camp on the bluffs of the northern peninsula."] = "飞往{zone:1447}西部的{area:1237}。{npc:8576}会派你向东北前往北部半岛峭壁上的血精灵营地。",
	["From here it is cloth. Wool, Silk and Mageweave must all be handed in before {npc:14726} offers the {item:14047} donation, and {quest:7832} needs the {item:14047} donation. Buy cloth at the Auction House, or farm it: humanoids drop it, Wool from level 15 to 25, Silk 25 to 40, Mageweave 40 to 50, {item:14047} 50 and up. At 60 farm mobs of level 52 or more: lower ones are grey."] = "接下来是布料。羊毛、丝绸和魔纹布都要交完，{npc:14726}才会提供{item:14047}捐献任务，而{quest:7832}需要完成{item:14047}捐献。在拍卖行买布，或自己刷：人形生物掉落，羊毛15到25级，丝绸25到40级，魔纹布40到50级，{item:14047}50级以上。60级时刷52级以上的怪：更低的已是灰色。",
	["From now on Drohn takes 5 Lightning Glands, a {item:4897} and a {item:4896} for 50, as often as you like. The {npc:3238} thunder lizards (a gland about every other kill), the Greater Thunderhawks and the kodos south of {area:378} drop them. Gather several sets before you head back to {area:392}."] = "此后德罗恩会收5个闪电腺、一个{item:4897}和一个{item:4896}，每次50声望，不限次数。{npc:3238}雷霆蜥蜴（约每两只掉一个腺体）、巨型雷霆鹰和{area:378}以南的科多兽都会掉。回{area:392}之前多攒几套。",
	["Go back into the cave and keep to the right-hand wall all the way, over a small stream, to {npc:3183} on a ledge above a pool."] = "回到洞内，一路贴着右手边的墙壁走，越过一条小溪，到达水池上方岩台上的{npc:3183}。",
	["Hexed Troll"] = "被诅咒的巨魔",
	["Honored to Revered is 12,000: 240 hand-ins, 4,800 {item:14047}. The Auction House price of a stack decides whether to farm or buy."] = "尊敬到崇敬需12,000点：240次交付，4,800个{item:14047}。一组在拍卖行的价格决定是刷还是买。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. The {area:363} is the best of them: about 1,400 {faction:76} and 1,400 Darkspear reputation in 25 minutes (about 280 each at a fifth). {npc:3143} waits in the Den, the big hut; {npc:10176} stands outside it."] = "在经典旧世，低于你6级以上的任务收益减少（60级时只有五分之一）；据Forever测试服报告，它们全额奖励。第一次交任务就能看出：若只给五分之一，就跳过这些据点。{area:363}是其中最好的：25分钟约1,400{faction:76}和1,400暗矛声望（打五折则各约280）。{npc:3143}在大屋（兽穴）里等候；{npc:10176}站在屋外。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. {area:362} and north {zone:1411}: about 1,800 {faction:76} and 1,650 Darkspear reputation in 80 minutes (360 and 330 at a fifth). {npc:3142} and {npc:3139} stand in the middle of the town, {npc:3191} by the barracks, {npc:3147} and {npc:266940} at the edges."] = "在经典旧世，低于你6级以上的任务收益减少（60级时只有五分之一）；据Forever测试服报告，它们全额奖励。第一次交任务就能看出：若只给五分之一，就跳过这些据点。{area:362}和{zone:1411}北部：80分钟约1,800{faction:76}和1,650暗矛声望（打五折则360和330）。{npc:3142}和{npc:3139}站在镇中央，{npc:3191}在兵营旁，{npc:3147}和{npc:266940}在镇子边缘。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. {area:367} and the {area:368}: about 700 {faction:76} and 650 Darkspear reputation in 25 minutes (140 and 130 at a fifth). {npc:3188} and {npc:3304} stand by the huts, {npc:3194} near the water, {npc:7953} south of the village."] = "在经典旧世，低于你6级以上的任务收益减少（60级时只有五分之一）；据Forever测试服报告，它们全额奖励。第一次交任务就能看出：若只给五分之一，就跳过这些据点。{area:367}和{area:368}：25分钟约700{faction:76}和650暗矛声望（打五折则140和130）。{npc:3188}和{npc:3304}在屋旁，{npc:3194}在水边，{npc:7953}在村南。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. {area:380}: about 1,500 {faction:76} reputation in 70 minutes (300 at a fifth), {faction:76}'s only. {npc:3338}, {npc:3464}, {npc:3429}, {npc:3449} and {npc:267310} stand in the town, {npc:3432} by the inn."] = "在经典旧世，低于你6级以上的任务收益减少（60级时只有五分之一）；据Forever测试服报告，它们全额奖励。第一次交任务就能看出：若只给五分之一，就跳过这些据点。{area:380}：70分钟约1,500{faction:76}声望（打五折300），且只加{faction:76}。{npc:3338}、{npc:3464}、{npc:3429}、{npc:3449}和{npc:267310}在镇内，{npc:3432}在旅店旁。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. {quest:5726}: 400 {faction:76} reputation in 20 minutes (80 at a fifth), with a run through {area:2437} that a level 60 clears alone."] = "在经典旧世，低于你6级以上的任务收益减少（60级时只有五分之一）；据Forever测试服报告，它们全额奖励。第一次交任务就能看出：若只给五分之一，就跳过这些据点。{quest:5726}：20分钟400{faction:76}声望（打五折80），还有一段穿越{area:2437}的行程，60级可单刷。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip this. {quest:819} lies on the ground at one of several spots in the central and northern {zone:1413}, most of them by the roads around the {area:380}; once someone takes it, it turns up at another. {npc:3292} in {area:392} pays 250 {faction:76} reputation for the keg and its first filling, then 50 for every filling after, as often as you like (10 at a fifth)."] = "在经典旧世，低于你6级以上的任务收益减少（60级时只有五分之一）；据Forever测试服报告，它们全额奖励。第一次交任务就能看出：若只给五分之一，就跳过这个。{quest:819}散落在{zone:1413}中部和北部几处地点之一的地面上，多数在{area:380}周边的道路旁；一旦被人捡走，就会出现在另一处。{area:392}的{npc:3292}为酒桶和首次装填给250{faction:76}声望，之后每次装填50，不限次数（打五折10）。",
	["Kill the Reclaimers and Surveyors, then walk up to the book inside the ring of stone pillars. Read the {object:151286} there to start the next quest: break the crystals around the circle, kill the guard that comes, then {npc:8578}."] = "杀掉收复者和勘测员，然后走到石柱环内的书旁。阅读那里的{object:151286}以接下一个任务：打碎圆圈周围的水晶，杀掉出现的守卫，然后找{npc:8578}。",
	["Kul Tiras Marine"] = "库尔提拉斯陆战队",
	["Kul Tiras Sailor"] = "库尔提拉斯水兵",
	["Lazy Peon"] = "懒散的苦工",
	["Level 56-60 quests and {item:14047} to Exalted, with the old {zone:1411} quests as a fast extra if they still pay in full."] = "靠56-60级任务和{item:14047}冲到崇拜；若旧{zone:1411}任务仍全额奖励，可当作快速补充。",
	["Lieutenant Benedict"] = "本尼迪克特中尉",
	["Lions, plainstriders and a thunder lizard"] = "狮子、陆行鸟和一只雷霆蜥蜴",
	["Mageweave: the Jadefire satyrs in southern {zone:1448} and the Dunemaul ogres in {zone:1446} drop it about one kill in three, or buy it."] = "魔纹布：{zone:1448}南部的碧火萨特和{zone:1446}的沙丘食人魔约每三只掉一个，或者直接买。",
	["Makrura and surf crawlers walk the beaches east and south of Sen'jin. The {quest:97223} is east of the village. The Ridgeshade spiders are along the road south of {area:362} and north-east of the Den."] = "龙虾人和海滩爬行者出没在森金村东面和南面的海滩。{quest:97223}在村东。脊影蜘蛛在{area:362}以南的道路沿线以及大屋（兽穴）东北。",
	["Moontouched Owlbeast"] = "月触枭兽",
	["Moontouched Owlbeasts north of {area:2255} and south of it."] = "{area:2255}以北和以南的月触枭兽。",
	["Most Berserk Owlbeasts are north of {area:2255}. A {item:12558} may drop from the owlbeasts now: use it to start {quest:4882}."] = "大多数狂暴枭兽在{area:2255}以北。枭兽现在可能掉落{item:12558}：使用它以接取{quest:4882}。",
	["Mottled Boar"] = "斑纹野猪",
	["North of the Den"] = "大屋（兽穴）以北",
	["North {zone:1411}"] = "{zone:1411}北部",
	["Orgrimmar Reputation"] = "奥格瑞玛声望",
	["Prowlers, {npc:3452} and {quest:881}"] = "徘徊者、{npc:3452}和{quest:881}",
	["Ragged Owlbeast"] = "褴褛枭兽",
	["Raging Owlbeast"] = "暴怒枭兽",
	["Raging Owlbeasts north-west of {area:2255}, Ragged Owlbeasts further west."] = "暴怒枭兽在{area:2255}西北，褴褛枭兽再往西。",
	["Razormane Battleguard"] = "刺鬃战斗卫士",
	["Razormane Defender"] = "刺鬃防御者",
	["Razormane Dustrunner"] = "刺鬃扬尘者",
	["Razormane Geomancer"] = "刺鬃地卜师",
	["Razormane Hunter"] = "刺鬃猎人",
	["Razormane Quilboar"] = "刺鬃野猪人",
	["Razormane Scout"] = "刺鬃斥候",
	["Razormane Thornweaver"] = "刺鬃织棘者",
	["Razormane Water Seeker"] = "刺鬃寻水者",
	["Reputation · Cities"] = "声望 · 城市",
	["Revered to Exalted is 21,000: 420 hand-ins, 8,400 {item:14047}. Raid heads pay too: The Lord of Blackrock (Nefarian) 200 to every Horde city and Victory for the Horde (Onyxia) 400 to {faction:76}. At Exalted, {npc:3362} in the {object:172958} sells the wolves to every Horde race: 20 gold for a level 40 wolf, 200 gold for a swift wolf at level 60 (Forever's prices); in Classic other races needed Exalted to buy them."] = "崇敬到崇拜需21,000点：420次交付，8,400个{item:14047}。团队首领也给声望：“黑石之王”（奈法利安）给所有部落城市200点，“为部落而战”（奥妮克希亚）给{faction:76}400点。崇拜后，{object:172958}里的{npc:3362}会向所有部落种族出售狼：40级的狼20金，60级的迅捷狼200金（Forever价格）；经典旧世里其他种族需崇拜才能买。",
	["Ridgeshade Creeper"] = "脊影爬行者",
	["Ridgeshade Lurker"] = "脊影潜伏者",
	["Run out of {faction:76}'s west gate and over the bridge into the {zone:1413}. {npc:3337} and {quest:809} stand at {area:379}."] = "从{faction:76}西门跑出，过桥进入{zone:1413}。{npc:3337}和{quest:809}在{area:379}。",
	["Savannah Prowlers lie west and north of the {area:380}. {quest:876} leads the Witchwing harpies in the far north-west. Then {npc:3338} gives you the {item:10327}: blow it beside the kodo bones at {object:147524}, north of the town, and kill the white lion."] = "草原徘徊者在{area:380}以西和以北。{quest:876}指向最西北的巫翼鹰身人。之后{npc:3338}给你{item:10327}：在镇北{object:147524}的科多兽骸骨旁吹响，并杀死白狮。",
	["Savannah lions, plainstriders and thunder lizards roam the whole northern {zone:1413}. The lions drop a tusk about every other kill, the plainstriders a kidney about two kills in five; any thunder lizard may drop the horn, about one in five."] = "草原狮、陆行鸟和雷霆蜥蜴遍布{zone:1413}北部。狮子约每两只掉一颗獠牙，陆行鸟约五只掉两个肾脏；任何雷霆蜥蜴都可能掉角，约五分之一。",
	["Silk: the Syndicate in {area:287} and Alterac drop it about one kill in three, or buy it."] = "丝绸：{area:287}和奥特兰克的辛迪加约每三只掉一个，或者直接买。",
	["Swim to the largest of the {area:368}, south-east of the village. {quest:826}, the idols and the skulls at the circle of power are all there; the Durotar Tigers prowl the smaller islands."] = "游到村东南{area:368}中最大的岛。{quest:826}、神像和能量法阵的骷髅都在那里；杜隆塔尔猛虎在较小的岛上徘徊。",
	["The Charged Thunder Lizard Organs come from the thunder lizards on {area:369}, just west of {npc:3293}."] = "充能的雷霆蜥蜴器官来自{npc:3293}正西{area:369}的雷霆蜥蜴。",
	["The Razormane camps and the supply crates are north-east of the town; {npc:267307}, an elite boar, sits deep in the {area:1699} cave there. The Witchwing harpies nest far to the north-west. The {npc:10668} lies north-east of {area:378}, in the south: right-click it. Raptors and plainstriders are everywhere."] = "刺鬃营地和补给箱在镇的东北；精英野猪{npc:267307}深居那里的{area:1699}洞穴。巫翼鹰身人巢居在遥远的西北。{npc:10668}在南部{area:378}的东北：右键点击它。迅猛龙和陆行鸟到处都有。",
	["The Razormane camps are south-west and west of {area:362}; the Prickly Pear cacti grow among them. Then head to the {area:368} for the {object:3240}: each nest gives an egg every time."] = "刺鬃营地在{area:362}的西南和以西；仙人掌果就长在营地间。然后去{area:368}找{object:3240}：每个巢每次都出一个蛋。",
	["The cactus apples grow beside the cacti north of the Den. {npc:3287} lies wounded by the rocks to the north; {quest:790}, his big scorpid, roams close by. {quest:792} swarm at the mouth of the {area:365}; {quest:6394} lies inside: take the middle tunnel where it splits three ways."] = "仙人掌果长在大屋（兽穴）以北的仙人掌旁。{npc:3287}受伤躺在北边的岩石旁；他的大蝎子{quest:790}在附近游荡。{quest:792}在{area:365}洞口成群；{quest:6394}在里面：在分三岔处走中间那条隧道。",
	["The coast and the road"] = "海岸与道路",
	["The keep is south of {area:362} on the coast. {npc:3192} is in the keep's only building; his key opens {object:3239} on the roof, and the {item:4881} inside starts {quest:830}. The sailors and marines drop the {item:4870}; the {item:275713}, Battleaxe and Shield lie outside the keep."] = "城堡在{area:362}以南的海岸上。{npc:3192}在城堡唯一的建筑里；他的钥匙能打开屋顶上的{object:3239}，里面的{item:4881}可开启{quest:830}。水手和陆战队员掉落{item:4870}；{item:275713}、战斧和盾牌躺在城堡外。",
	["The training weapons lie on the ground in the Den and among the boars to the north. For the peons: target a sleeping {npc:10556} and use the {item:16114} on it."] = "训练用武器躺在大屋（兽穴）的地上以及北边野猪群中。对付苦工：选中一个睡着的{npc:10556}并对它使用{item:16114}。",
	["The wreck"] = "沉船",
	["The wrecked ship lies in the shallows east of {area:372}. Open the Gnomish Toolboxes."] = "沉船在{area:372}以东的浅滩。打开侏儒工具箱。",
	["The {area:368}"] = "{area:368}",
	["These quests are level 56 to 59, so they pay in full at 60. {npc:10306} stands at {area:1997}; the owlbeasts live in {zone:1452}, through the Timbermaw tunnel north of {zone:1448}."] = "这些任务是56到59级，所以60级时全额奖励。{npc:10306}在{area:1997}；枭兽住在{zone:1452}，经{zone:1448}以北的木喉隧道前往。",
	["Vile Familiar"] = "卑劣的魔仆",
	["Voodoo Troll"] = "巫毒巨魔",
	["Zhevra Runners graze south and west of the town. {npc:3438} leads the Razormane camps north-east. The Witchwing Slayers carry the rings. The {quest:3281} is in the {area:1697} east of {area:378}: follow the nest-lined path on its left side to the last nest."] = "泽布拉奔跑者在镇南和镇西吃草。{npc:3438}指向东北的刺鬃营地。巫翼杀戮者携带戒指。{quest:3281}在{area:378}以东的{area:1697}：沿其左侧布满巢穴的小路走到最后一个巢。",
	["Zhevras, quilboars, harpies and the {area:1697}"] = "泽布拉、野猪人、鹰身人和{area:1697}",
	["back at {npc:3139} in {area:362}"] = "回到{area:362}的{npc:3139}处",
