G["forever/reputation/thunder-bluff"] = {
	["+150"] = "+150",
	["Back to the mine for the workers, supervisors and {quest:765}. The Galak centaurs and {npc:275767} camp east of the village. Swoops fly all over {zone:1412}; the Windfury harpies roost south-east of the village; the Palemane gnolls camp west of it."] = "回到矿井处理矿工、监工和{quest:765}。加拉克半人马和{npc:275767}在村子东边扎营。猛鹫遍布{zone:1412}各地；风怒鹰身人在村子东南方栖息；白鬃豺狼人在村子西边扎营。",
	["Broodmother Valraxx"] = "育母瓦尔拉克斯",
	["Brumeran"] = "布鲁米兰",
	["Eastern {zone:1412}"] = "{zone:1412}东部",
	["Exalted with {faction:81}"] = "{faction:81}崇拜",
	["From here it is cloth. Wool, Silk and Mageweave must all be handed in before {npc:14728} offers the {item:14047} donation, and {quest:7825} needs the {item:14047} donation. Buy cloth at the Auction House, or farm it: humanoids drop it, Wool from level 15 to 25, Silk 25 to 40, Mageweave 40 to 50, {item:14047} 50 and up. At 60 farm mobs of level 52 or more: lower ones are grey."] = "从这里开始就是捐布了。毛料、丝绸和魔纹布都要先各捐过一次，{npc:14728}才会提供{item:14047}的捐赠，而{quest:7825}需要{item:14047}。布料可以在拍卖行买，也可以自己刷：人形怪掉落，毛料出自15到25级，丝绸25到40级，魔纹布40到50级，{item:14047}出自50级以上。60级时刷52级以上的怪：等级更低的已经灰了。",
	["Galak Centaur"] = "加拉克半人马",
	["Galak Outrunner"] = "加拉克斥候",
	["Gloomrise Hatchling"] = "幽谷雏龙",
	["Gloomrise Soldier"] = "幽谷士兵",
	["Honored to Revered is 12,000: 240 hand-ins, 4,800 {item:14047}, fewer if you also hand in {item:11040}. {area:1584} pays too: Disharmony of Flame and Disharmony of Fire from Thunderheart at {area:340} ({npc:9017}, 150 in full)."] = "尊敬到崇敬是12,000点：240次上缴，4,800个{item:14047}，如果同时上缴{item:11040}可以少一些。{area:1584}也给声望：{area:340}雷霆之心给的不和谐之焰与不和之火（{npc:9017}，全额150点）。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. The Earthen Ring camp on the {area:17045}, north-west of {faction:81}: 300 {faction:81} reputation in 20 minutes (60 at a fifth), plus 100 each for {zone:1454} and the Darkspear Trolls and 450 Earthen Ring. {npc:259118}, {npc:264074} and {npc:264072} stand in the camp."] = "经典旧世里，比你低6级以上的任务奖励的声望会减少（60级时只剩五分之一）；有Forever测试服报告称它们全额支付。第一次交任务就能看出是哪种：如果只给五分之一，就跳过这些任务点。{faction:81}西北方{area:17045}上的大地之环营地：20分钟刷300点{faction:81}声望（五分之一时60点），外加{zone:1454}和暗矛巨魔各100点，以及450点大地之环声望。{npc:259118}、{npc:264074}和{npc:264072}都在营地里。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. {area:221}, at the south end of {zone:1412}: about 1,100 {faction:81} reputation in 25 minutes (220 at a fifth). Starting-zone quests give the other cities no share. {npc:2980} and {npc:2981} stand in the camp, {npc:3209} at its edge."] = "经典旧世里，比你低6级以上的任务奖励的声望会减少（60级时只剩五分之一）；有Forever测试服报告称它们全额支付。第一次交任务就能看出是哪种：如果只给五分之一，就跳过这些任务点。{zone:1412}南端的{area:221}：25分钟约刷1,100点{faction:81}声望（五分之一时220点）。新手区的任务不给其他主城分成。{npc:2980}和{npc:2981}在营地里，{npc:3209}在营地边缘。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. {area:222} and eastern {zone:1412}: about 1,000 {faction:81} reputation in 45 minutes (200 at a fifth). {npc:2993} stands in the middle of the village; {npc:2947}, {npc:2985} and {npc:3222} close by; {npc:2988} waits east of the village by the road."] = "经典旧世里，比你低6级以上的任务奖励的声望会减少（60级时只剩五分之一）；有Forever测试服报告称它们全额支付。第一次交任务就能看出是哪种：如果只给五分之一，就跳过这些任务点。{area:222}和{zone:1412}东部：45分钟约刷1,000点{faction:81}声望（五分之一时200点）。{npc:2993}站在村子中央；{npc:2947}、{npc:2985}和{npc:3222}就在附近；{npc:2988}在村子东边的路旁等你。",
	["Mageweave: the Jadefire satyrs in southern {zone:1448} and the Dunemaul ogres in {zone:1446} drop it about one kill in three, or buy it."] = "魔纹布：{zone:1448}南部的碧火萨特和{zone:1446}的砂槌食人魔约每三次击杀掉一个，或者直接买。",
	["Nearly every beast, plant and silithid in the crater drops {quest:3761}, about one kill in three (the Bloodpetals and the Gorishi wasps about one in two), and the dirt mounds give it too. Take far more than 20: every casing uses 2, about 18 for each {item:11040} hand-in."] = "环形山里几乎每种野兽、植物和异种虫都会掉{quest:3761}，约每三次击杀掉一个（血瓣花和格里什蜂约每两次掉一个），土堆也会出。拿的远多过20个：每个外壳要消耗2个，每次上缴{item:11040}约要18个。",
	["Palemane Poacher"] = "白鬃偷猎者",
	["Palemane Skinner"] = "白鬃剥皮者",
	["Palemane Tanner"] = "白鬃制革者",
	["Reputation · Cities"] = "声望·主城",
	["Revered to Exalted is 21,000: 420 hand-ins, 8,400 {item:14047}. For The Horde! (Rend's head) and The Lord of Blackrock (Nefarian's head) pay 200 to every Horde city. At Exalted, {npc:3685} in {area:222} sells the kodos to every Horde race: 20 gold for a level 40 kodo, 200 gold for a great kodo at level 60 (Forever's prices); in Classic other races needed Exalted to buy them."] = "崇敬到崇拜是21,000点：420次上缴，8,400个{item:14047}。“为了部落！”（雷德的头颅）和“黑石之王”（奈法利安的头颅）给每个部落主城200点。崇拜后，{area:222}的{npc:3685}把科多兽卖给每个部落种族：40级科多兽20金，60级巨型科多兽200金（Forever的价格）；经典旧世里其他种族要崇拜才能购买。",
	["Shy-Rotam"] = "害羞的罗塔姆",
	["Silk: the Syndicate in {area:287} and Alterac drop it about one kill in three, or buy it."] = "丝绸：{area:287}和奥特兰克的辛迪加约每三次击杀掉一个，或者直接买。",
	["The Skywatcher camp: hand in"] = "观天者营地：交任务",
	["The mine, the centaurs and the plains"] = "矿井、半人马与平原",
	["Thunder Bluff Reputation"] = "雷霆崖声望",
	["Ursius"] = "尤尔修斯",
	["Venture Co. Supervisor"] = "风险投资公司监工",
	["Venture Co. Worker"] = "风险投资公司矿工",
	["the {object:2908}"] = "{object:2908}",
	["{area:17044} (optional hub)"] = "{area:17044}（可选任务点）",
	["{area:17044} is the tauren burial ground north of {faction:81}. Use the {item:273015} on the Gnawed Corpses. {npc:264082} waits at the heart of it; her body carries a {item:273658}: read it to start {quest:96294}."] = "{area:17044}是{faction:81}以北的牛头人墓地。对被啃噬过的尸体使用{item:273015}。{npc:264082}在墓地中心等你；她的尸体上带着一封{item:273658}：阅读它来开启{quest:96294}。",
	["{area:221} (optional hub)"] = "{area:221}（可选任务点）",
	["{area:221}: hand in"] = "{area:221}：交任务",
	["{area:221}: last hand-in"] = "{area:221}：最后交任务",
	["{area:221}: the Battleboars"] = "{area:221}：斗猪",
	["{area:222} (optional hub)"] = "{area:222}（可选任务点）",
	["{area:222}: hand in"] = "{area:222}：交任务",
	["{area:222}: last hand-in"] = "{area:222}：最后交任务",
	["{faction:81} reputation comes from quests, {item:11040} and cloth. {npc:14728}, the cloth quartermaster, stands on the central rise among the leatherworkers' and tailors' tents. He takes four one-time donations of 60 cloth (150 each) and then {quest:7825}, 20 {item:14047} for 50, as often as you like. Every point you earn with {faction:81} also gives a quarter as much to {zone:1454}, the {zone:1458} and the Darkspear Trolls. While you level, do {faction:81}'s quests within 5 levels of them: {zone:1412} at 1 to 12, {area:378} and the {area:380} at 13 to 22, {zone:1441} at 25 to 30. The Legacy perk Diplomat adds up to 10%. Rewards: at Honored Thunder Bluff's merchants sell to you for 10% less (the Classic rule), the kodo vendor included; at Exalted other races can buy the kodos: 20 gold for a level 40 kodo, 200 gold for a great kodo at level 60, once you have mount training. {faction:81} has no tabard or other reward."] = "{faction:81}声望来自任务、{item:11040}和捐布。布料军需官{npc:14728}站在中央高地的制皮匠与裁缝帐篷之间。他先收四次一次性的60布料捐赠（每次150点），然后是{quest:7825}，20个{item:14047}换50点，想交多少次都行。你在{faction:81}获得的每一点声望，同时以四分之一计入{zone:1454}、{zone:1458}和暗矛巨魔。练级过程中，在任务等级与你相差不超过5级时去做{faction:81}的任务：1到12级在{zone:1412}，13到22级在{area:378}和{area:380}，25到30级在{zone:1441}。传承特长“外交官”最多加成10%。奖励：尊敬后雷霆崖的商人对你打九折（经典旧世规则），科多兽商人也在内；崇拜后其他种族可以购买科多兽：40级科多兽20金，60级巨型科多兽200金，前提是你已学会骑术。{faction:81}没有战袍或其他奖励。",
	["{faction:81}: how it works"] = "{faction:81}：运作方式",
	["{item:11020}, 1 gold"] = "{item:11020}，1金",
	["{item:11022}, 10 silver each"] = "{item:11022}，每个10银",
	["{item:11040} (optional)"] = "{item:11040}（可选）",
	["{item:11040} as you go"] = "{item:11040}，边做边收",
	["{item:11040}, if you grow it"] = "{item:11040}，如果你有培育",
	["{item:11040}, if you grow it: {npc:9087} takes it"] = "{item:11040}，如果你有培育：{npc:9087}收",
	["{item:11040}: use the pouch every 10 minutes and open the casings; {npc:9087} takes it"] = "{item:11040}：每10分钟用一次袋子并打开外壳；{npc:9087}收",
	["{item:12733}, from the frostsabers"] = "{item:12733}，出自霜刃豹",
	["{item:14047}: the Scarlet at {area:2266} in the {zone:1423}, the Gordok ogres outside {area:2577} in {zone:1444} and the Twilight camps of {zone:1451} drop it about one kill in three. The Auction House is faster if you have gold."] = "{item:14047}：{zone:1423}{area:2266}的血色十字军、{zone:1444}{area:2577}外的戈多克食人魔和{zone:1451}的暮光营地约每三次击杀掉一个。金币够的话拍卖行更快。",
	["{item:14047}: the Scarlet outside {area:2266}"] = "{item:14047}：{area:2266}外的血色十字军",
	["{item:2592}: the Thistlefur furbolgs drop it about one kill in four"] = "{item:2592}：刺毛熊怪约每四次击杀掉一个",
	["{item:273181}, from Gloomrise Spinners"] = "{item:273181}，出自幽谷结网蛛",
	["{item:273658}: {quest:96294}, +100 ({zone:1454} +100)"] = "{item:273658}：{quest:96294}，+100（{zone:1454} +100）",
	["{item:4306}: the Syndicate"] = "{item:4306}：辛迪加",
	["{item:4338}: the Jadefire satyrs"] = "{item:4338}：碧火萨特",
	["{item:4851}: {quest:781}, +100"] = "{item:4851}：{quest:781}，+100",
	["{npc:10303}'s four quests are level 56 to 60, so they pay in full: 400 {faction:81} reputation. {npc:10806}, an elite bear, walks a loop over the four hills north of {area:2255}: wait on a hilltop for him."] = "{npc:10303}的四个任务是56到60级，所以全额支付：400点{faction:81}声望。{npc:10806}是一头精英熊，在{area:2255}以北的四座山丘上绕圈：在山头上等他。",
	["{npc:10306} stands at {area:1997}, through the Timbermaw tunnel south of {zone:1452}."] = "{npc:10306}站在{area:1997}，穿过{zone:1452}南边的木喉隧道即到。",
	["{npc:10806}, elite"] = "{npc:10806}，精英",
	["{npc:10807} and {quest:5056}"] = "{npc:10807}和{quest:5056}",
	["{npc:10807}, an elite chimera, spawns south of {area:2255}. For {quest:5056}, kill frostsabers north of {area:2255} until one drops {item:12733} (about one in ten), then use the meat at the {object:103819}, far to the north, and kill the great cat that comes. If you have done {npc:10306}'s Wild Guardians quests (the {zone:1454} guide), the Crazed, Moontouched and Berserk owlbeasts around {area:2255} sometimes drop a {item:12558}: it starts {quest:4882}, 50 {zone:1454} and then 100 {faction:81} reputation in full."] = "{npc:10807}是一只精英双头奇美拉，在{area:2255}以南刷新。做{quest:5056}要在{area:2255}以北杀霜刃豹，直到掉出{item:12733}（约每十只一个），然后在遥远的北方{object:103819}处使用这块肉，杀掉闻味而来的大猫。如果你做过{npc:10306}的野性守卫系列任务（见{zone:1454}攻略），{area:2255}周围的疯狂、月触和狂暴枭兽偶尔会掉{item:12558}：它开启{quest:4882}，全额给50点{zone:1454}以及之后的100点{faction:81}声望。",
	["{npc:10807}, elite"] = "{npc:10807}，精英",
	["{npc:14728}, +150"] = "{npc:14728}，+150",
	["{npc:14728}: {quest:7820}, +150"] = "{npc:14728}：{quest:7820}，+150",
	["{npc:14728}: {quest:7825}, +50"] = "{npc:14728}：{quest:7825}，+50",
	["{npc:259118}: {quest:96259}, +100"] = "{npc:259118}：{quest:96259}，+100",
	["{npc:264072}: {quest:96260}, +100"] = "{npc:264072}：{quest:96260}，+100",
	["{npc:264074}: {quest:96241} (Darkspear +100)"] = "{npc:264074}：{quest:96241}（暗矛 +100）",
	["{npc:2947}: {quest:761}, +150"] = "{npc:2947}：{quest:761}，+150",
	["{npc:2980}: {quest:747}, +100"] = "{npc:2980}：{quest:747}，+100",
	["{npc:2981}: {quest:752}, +50"] = "{npc:2981}：{quest:752}，+50",
	["{npc:2982} and the cougars"] = "{npc:2982}与山地狮",
	["{npc:2982} sits on the hill south of the camp; the Mountain Cougars live in those hills."] = "{npc:2982}坐在营地南边的小山上；山地狮就生活在那些山丘里。",
	["{npc:2985}: {quest:743}, +100"] = "{npc:2985}：{quest:743}，+100",
	["{npc:2988}: {quest:749}, +75"] = "{npc:2988}：{quest:749}，+75",
	["{npc:2991} and the plains"] = "{npc:2991}与平原",
	["{npc:2991}'s tent is south-east of the camp; the water pitcher stands at the well beside it. Plainstriders graze all around."] = "{npc:2991}的帐篷在营地东南方；水罐就立在旁边的水井边。陆行鸟在四周各处吃草。",
	["{npc:2993}: {quest:745}, +100"] = "{npc:2993}：{quest:745}，+100",
	["{npc:3209}: {quest:3376}, +200"] = "{npc:3209}：{quest:3376}，+200",
	["{npc:3222}: {quest:99079}, +10"] = "{npc:3222}：{quest:99079}，+10",
	["{npc:3685}: the kodos"] = "{npc:3685}：科多兽",
	["{npc:5770} stands on {area:1639}, beside {npc:5769}."] = "{npc:5770}站在{area:1639}上，就在{npc:5769}旁边。",
	["{npc:9076} takes the soil. {npc:9087} sells the {item:11020} (1 gold) and Packets of Tharlendris Seeds (10 silver each). With a seed packet and 2 {quest:3761} in your bags, use the pouch: it grows an {item:11024}, once every 10 minutes. Open each casing: about one in three holds 1 to 5 {item:11040}, the rest common herbs. Use the pouch whenever it is ready while you follow the rest of this guide."] = "{npc:9076}收土壤。{npc:9087}出售{item:11020}（1金）和萨伦迪斯种子包（每个10银）。背包里有种子包和2个{quest:3761}时使用袋子：它会培育出一个{item:11024}，每10分钟一次。打开每个外壳：约三分之一装有1到5个{item:11040}，其余是普通草药。在跟随本攻略余下步骤的过程中，袋子一冷却好就用。",
	["{npc:9087} stands on {area:1639}. If your 10 {item:11040} are not ready yet, skip this step and go on with the cloth: the cloth steps below list the {item:11040} hand-in too."] = "{npc:9087}站在{area:1639}上。如果你的10个{item:11040}还没凑齐，跳过这一步先去做捐布：下面的捐布步骤也会列出{item:11040}的上缴。",
	["{npc:9087}: {quest:3804}, +50"] = "{npc:9087}：{quest:3804}，+50",
	["{quest:3761}, +100"] = "{quest:3761}，+100",
	["{quest:3782}, +100"] = "{quest:3782}，+100",
	["{quest:3804} takes 10 {item:11040} for 50, as often as you like, and pays in full at 60, but it is slow: the {item:11020} grows one casing every 10 minutes and a casing holds about one {item:11040} on average, so each hand-in takes about 90 minutes of waiting, 18 {quest:3761} and 9 seed packets (90 silver). It runs beside whatever else you do: a little over 30 reputation an hour. The chain before it is level 50 (in Classic a fifth at 60). {npc:6746} sends you to {npc:5769} on {area:1639}; he wants 20 {quest:3761}."] = "{quest:3804}用10个{item:11040}换50点声望，想交多少次都行，60级时也全额支付，但很慢：{item:11020}每10分钟才长出一个外壳，而外壳平均只装约一个{item:11040}，所以每次上缴要约90分钟的等待、18个{quest:3761}和9个种子包（90银）。它可以伴随你做的任何事同时进行：每小时略多于30点声望。它的前置任务链是50级的（经典旧世里60级只剩五分之一）。{npc:6746}让你去{area:1639}找{npc:5769}；他要20个{quest:3761}。",
	["{quest:3804}, +50"] = "{quest:3804}，+50",
	["{quest:4882}, +100: to {npc:5770} in {faction:81}"] = "{quest:4882}，+100：交给{faction:81}的{npc:5770}",
