	["{quest:764}, +75"] = "{quest:764}，+75",
	["{quest:765}, +100"] = "{quest:765}，+100",
	["{quest:780} graze east of the camp; the Bristleback quilboar and {npc:8554} hold {area:358} beyond them. A {item:4851} lies in the ravine: reading it starts {quest:781}."] = "{quest:780}在营地东边吃草；刺背野猪人和{npc:8554}占据着更远的{area:358}。一张{item:4851}躺在峡谷里：阅读它开启{quest:781}。",
	["{quest:780}, +150"] = "{quest:780}，+150",
	["{quest:7825} to Exalted"] = "{quest:7825}刷到崇拜",
	["{quest:7825} to Honored"] = "{quest:7825}刷到尊敬",
	["{quest:7825} to Revered"] = "{quest:7825}刷到崇敬",
	["{quest:7825}, +50"] = "{quest:7825}，+50",
	["{quest:7825}: 20 {item:14047} for 50 reputation, as often as you like. Friendly to Honored is 6,000: 120 hand-ins, 2,400 {item:14047}, less what the quests gave you (a tauren starts at Friendly 1,000: 100 hand-ins; an Undead at Neutral 500 first needs 50 more to reach Friendly). Hand in every 20 you carry, one after another."] = "{quest:7825}：20个{item:14047}换50点声望，想交多少次都行。友善到尊敬是6,000点：120次上缴，2,400个{item:14047}，还要减去任务已给你的部分（牛头人开局是友善1,000点：100次上缴；亡灵开局是中立，先要再刷50点才能到友善）。背包里每攒够20个就交一次，一次接一次地交。",
	["{quest:98427}, +150"] = "{quest:98427}，+150",
	["{quest:99079} waits by the eastern border. The {object:2908} of the ravaged caravan lies north-east of the village: open it to start the next quest. {quest:764} mine is further north-east; the elite shredder Venture Co. Clearcutter works deep inside."] = "{quest:99079}在东部边界旁等你。被洗劫商队的{object:2908}就在村子东北方：打开它开启下一个任务。{quest:764}的矿井在更远的东北方；精英伐木机风险投资公司清砍者在深处作业。",
	["{quest:99080}, +100"] = "{quest:99080}，+100",
	["{quest:99081}, +10"] = "{quest:99081}，+10",
	["{quest:99082}, +10: to {npc:3057} in {faction:81}"] = "{quest:99082}，+10：交给{faction:81}的{npc:3057}",
	["{quest:99101}, +10"] = "{quest:99101}，+10",
	["{zone:1452}'s level 56-60 quests, {item:11040} and {item:14047} to Exalted, with {zone:1412}'s old quests as an optional extra."] = "{zone:1452}的56-60级任务，再用{item:11040}和{item:14047}冲到崇拜，{zone:1412}的旧任务作为可选补充。",
}

G["forever/reputation/undercity"] = {
	["+150"] = "+150",
	["Andorhal Tower Four"] = "安多哈尔四号塔",
	["Andorhal Tower One"] = "安多哈尔一号塔",
	["Andorhal Tower Three"] = "安多哈尔三号塔",
	["Andorhal Tower Two"] = "安多哈尔二号塔",
	["Around {area:154}"] = "{area:154}一带",
	["Around {area:159}"] = "{area:159}一带",
	["Borelgore"] = "波雷戈尔",
	["Exalted with the {faction:68}"] = "{faction:68}声望崇拜",
	["From here it is cloth. Wool, Silk and Mageweave must all be handed in before {npc:14729} offers the {item:14047} donation, and {quest:7819} needs the {item:14047} donation. Buy cloth at the Auction House, or farm it: humanoids drop it, Wool from level 15 to 25, Silk 25 to 40, Mageweave 40 to 50, {item:14047} 50 and up. At 60 farm mobs of level 52 or more: lower ones are grey."] = "从这里开始靠布料。{npc:14729}要你先把毛料、丝绸和魔纹布都捐过一轮，才会开放{item:14047}捐赠，而{quest:7819}需要捐{item:14047}。布料可在拍卖行买，也可以刷：人形怪掉落，毛料出自15到25级，丝绸25到40级，魔纹布40到50级，{item:14047}出自50级以上。60级时刷52级以上的怪：等级更低的是灰色的。",
	["Honored to Revered is 12,000: 240 hand-ins, 4,800 {item:14047}. The {item:12358} ({area:1584}) pays 150 in full."] = "尊敬到崇敬是12000点：240次上缴，4800块{item:14047}。{item:12358}（{area:1584}）全额给150点。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. {area:154}, the Forsaken start at the west end of Tirisfal: about 900 {faction:68} reputation in 25 minutes (180 at a fifth). Starting-zone quests give the other cities no share. {npc:1661}, {npc:1570} and {npc:1740} stand in the village."] = "经典旧世里，比你低6级以上的任务声望奖励会减少（60级时只剩五分之一）；Forever测试服的一份报告称全额支付。你第一次交任务就能看出来：如果只给五分之一，就跳过这些据点。{area:154}是被遗忘者在提瑞斯法西端的新手村：约25分钟拿900点{faction:68}声望（五分之一时为180点）。新手村任务不给其他主城分成。{npc:1661}、{npc:1570}和{npc:1740}在村里。",
	["In Classic, quests 6+ levels below you pay less (a fifth at 60); a Forever beta report says they paid in full. Your first turn-in shows which: if it pays a fifth, skip these hubs. {area:159} and the fields around it: about 1,100 {faction:68} reputation in 45 minutes (220 at a fifth). {npc:1515}, {npc:1499}, {npc:1518}, {npc:1496} and {npc:1500} are in the town."] = "经典旧世里，比你低6级以上的任务声望奖励会减少（60级时只剩五分之一）；Forever测试服的一份报告称全额支付。你第一次交任务就能看出来：如果只给五分之一，就跳过这些据点。{area:159}及其周围的农场：约45分钟拿1100点{faction:68}声望（五分之一时为220点）。{npc:1515}、{npc:1499}、{npc:1518}、{npc:1496}和{npc:1500}在镇里。",
	["Mageweave: the Jadefire satyrs in southern {zone:1448} and the Dunemaul ogres in {zone:1446} drop it about one kill in three, or buy it."] = "魔纹布：{zone:1448}南部的碧火萨特和{zone:1446}的杜恩莫食人魔约三次击杀掉一组，或者直接买。",
	["Monstrous Plaguebat"] = "巨型瘟疫蝙蝠",
	["Motivate 5 Deathguards"] = "激励5名亡灵卫兵",
	["Night Web Spider"] = "夜网蜘蛛",
	["Noxious Plaguebat"] = "剧毒瘟疫蝙蝠",
	["Pathstrider"] = "巡路者",
	["Plaguebats, {area:2276} and {area:2264}"] = "瘟疫蝙蝠，{area:2276}和{area:2264}",
	["Ranger"] = "游侠",
	["Read {item:9323} at the altar of {area:353} to call {npc:2707}, an elite level 55 spider: she drops her venom every time."] = "在{area:353}的祭坛读取{item:9323}来召唤{npc:2707}，一只55级精英蜘蛛：她每次必掉毒液。",
	["Reputation · Cities"] = "声望·主城",
	["Revered to Exalted is 21,000: 420 hand-ins, 8,400 {item:14047}. For The Horde! (Rend's head) and The Lord of Blackrock (Nefarian's head) pay 200 to every Horde city. At Exalted, {npc:4731} in {area:159} sells the skeletal horses to every Horde race: 20 gold for a level 40 horse, 200 gold for a level 60 warhorse (Forever's prices); in Classic other races needed Exalted to buy them."] = "崇敬到崇拜是21000点：420次上缴，8400块{item:14047}。“为了部落！”（雷德的头颅）和“黑石之王”（奈法利安的头颅）给每个部落主城各200点。崇拜后，{area:159}的{npc:4731}把骸骨军马卖给所有部落种族：40级马20金，60级战马200金（Forever的价格）；经典旧世里其他种族需要崇拜才能买。",
	["Rot Hide Graverobber"] = "腐皮盗墓贼",
	["Rot Hide Mongrel"] = "腐皮恶犬",
	["Silk: the Syndicate in {area:287} and Alterac drop it about one kill in three, or buy it."] = "丝绸：{area:287}和奥特兰克的辛迪加约三次击杀掉一组，或者直接买。",
	["Six quests across the {zone:1425}, {area:272}, {area:367}, {area:978} and the {faction:68}: 600 {faction:68} and 225 Darkspear reputation. {quest:2937} and {quest:2938} are level 55 and pay 400 in full at 60; the four before them are level 43 to 45 (a fifth at 60 in Classic, 440 {faction:68} in all then). Allow about 90 minutes with the travel. The {quest:2933} stand on the tables of the Witherbark village in the west of the {zone:1425}: click one to start."] = "横跨{zone:1425}、{area:272}、{area:367}、{area:978}和{faction:68}的六个任务：600点{faction:68}和225点暗矛声望。{quest:2937}和{quest:2938}是55级，60级时全额给400点；前面四个是43到45级（经典旧世60级时按五分之一算，那样合计440点{faction:68}）。算上跑路约需90分钟。{quest:2933}摆在{zone:1425}西部枯木村的桌子上：点击一份开始。",
	["The Noxious Plaguebats fly in the south of the zone, the Monstrous Plaguebats further north-west. {area:2276} is north-west of {area:2268}; the {item:15847} lies inside. Do {area:2264} last: its Scourge drop {item:15447}, which lasts only 10 minutes. With 7 in your bags, use the {item:15454} at once for the {item:15448}."] = "剧毒瘟疫蝙蝠在该地区南部飞，巨型瘟疫蝙蝠在更西北方。{area:2276}在{area:2268}西北方；{item:15847}就在里面。{area:2264}留到最后做：那里的天灾掉落的{item:15447}只能保存10分钟。背包里攒够7个后，立刻使用{item:15454}换取{item:15448}。",
	["The Plaguelands' level 55-60 quests and {item:14047} to Exalted, with Tirisfal's old quests as an optional extra."] = "用瘟疫之地55-60级的任务和{item:14047}冲到崇拜，提瑞斯法的旧任务作为可选补充。",
	["The Scarlet camp"] = "血色营地",
	["The Scarlet camp is south-east of {area:154}. {npc:1667} leads it."] = "血色营地在{area:154}东南方。由{npc:1667}统领。",
	["The Witherbark Broodguards crawl around {area:353} in the south-west of the {zone:1425}; about one in ten carries an undamaged sac."] = "枯木巢穴守卫在{zone:1425}西南部的{area:353}一带爬动；约十分之一带着完好的囊。",
	["The level 55 to 60 quests pay in full. First the {area:152}: {npc:10879}, by the {faction:68}'s elevators, sends you there."] = "55到60级的任务全额支付。先去{area:152}：{faction:68}升降梯旁的{npc:10879}会派你去。",
	["The skeletons of {area:157} drop the ribs; the Darkeye Bonecasters the skulls."] = "{area:157}的骷髅掉肋骨；暗眼碎骨者掉颅骨。",
	["The {object:164662} are all around the village. {quest:380} is the mine north-west; the {npc:271961} hang inside. {npc:1919} waits at the ruined camp by the road north-east: bury his remains at {object:178090}, in the front row of the village graveyard."] = "{object:164662}遍布村子四周。{quest:380}是西北方的矿洞；{npc:271961}吊在里面。{npc:1919}在东北方路边的废弃营地等你：把他的遗骨埋到{object:178090}，就在村墓地的前排。",
	["Undercity Reputation"] = "幽暗城声望",
	["Use the {item:286176} on five Deathguards around {area:159}. For {quest:99141}, talk to {npc:1496} west of {area:159}, {npc:251001} at the waystation east of it and {npc:10666} on the road. The Rot Hide gnolls dig at the mass grave north of {area:159}. The {npc:1525} walk around the old bridge west of {area:159}; the dry branches lie under the trees there. Darkhounds roam everywhere."] = "对{area:159}周围的五名亡灵卫兵使用{item:286176}。{quest:99141}要找：{area:159}西边的{npc:1496}、东边驿站的{npc:251001}和路上的{npc:10666}。腐皮豺狼人在{area:159}以北的乱葬岗刨土。{npc:1525}在{area:159}以西的旧桥一带走动；干树枝就在那里的树下。黑暗犬到处游荡。",
	["Webbed Forsaken"] = "被网住的被遗忘者",
	["Woodsman"] = "樵夫",
	["Young Night Web Spider"] = "幼年夜网蜘蛛",
	["read the {object:142715}"] = "阅读{object:142715}",
	["the {object:176088}"] = "{object:176088}",
	["the {object:176361}"] = "{object:176361}",
	["the {object:176392}"] = "{object:176392}",
	["the {object:176393}"] = "{object:176393}",
	["the {object:177289}"] = "{object:177289}",
	["{area:152} is also where The Key to {area:2057} ends (200), after a longer chain. {npc:10136} in the {faction:68}'s Apothecarium pays about 290 more for oozes from {zone:1448} and {zone:1449}."] = "较长的任务链“{area:2057}的钥匙”也在{area:152}结束（200点）。{faction:68}炼金房的{npc:10136}还会为{zone:1448}和{zone:1449}的软泥怪再给约290点。",
	["{area:152} is the Forsaken camp on the road from Tirisfal into the {zone:1422}. {npc:10837}'s chain sends you against the Scourge cauldrons of the {zone:1422}: about 820 {faction:68} reputation, about 710 at 60 if the level 53 quests pay less. Take a {item:12814} from the box beside him; burn the command tent of the Scarlet camp between {area:200} and {area:199} and plant the {item:12807} beside it."] = "{area:152}是从提瑞斯法进入{zone:1422}路上的被遗忘者营地。{npc:10837}的任务链让你对付{zone:1422}的天灾瘟疫锅：约820点{faction:68}声望，如果53级任务减成，60级时约710点。从他身旁的箱子里拿{item:12814}；烧掉{area:200}和{area:199}之间血色营地的指挥帐篷，把{item:12807}插在旁边。",
	["{area:152}: done"] = "{area:152}：完成",
