	["{area:157} again"] = "再去{area:157}",
	["{area:159} (optional hub)"] = "{area:159}（可选据点）",
	["{area:159}: hand in"] = "{area:159}：交任务",
	["{area:199} and the Andorhal towers"] = "{area:199}和安多哈尔塔楼",
	["{area:272} and the {faction:68}"] = "{area:272}和{faction:68}",
	["{area:272}, then {area:367}"] = "{area:272}，然后{area:367}",
	["{area:353}: an {quest:2934}"] = "{area:353}：一个{quest:2934}",
	["{area:978} is a level 44 to 54 dungeon in northern {zone:1446}; a level 60 can clear the way alone, or bring a group. {npc:7272}, an elite troll, guards his tomb in the instance: kill him and read the {object:142715} there."] = "{area:978}是{zone:1446}北部的44到54级地下城；60级可以单刷清路，也可以组队。精英巨魔{npc:7272}守着副本里的墓穴：杀掉他，阅读那里的{object:142715}。",
	["{area:978}: the {object:142715}"] = "{area:978}：{object:142715}",
	["{faction:68} reputation comes from quests and cloth. {npc:14729}, the cloth quartermaster, stands in the {object:36082} beside the tailors. He takes four one-time donations of 60 cloth (150 each) and then {quest:7819}, 20 {item:14047} for 50, as often as you like. Every point you earn with the {faction:68} also gives a quarter as much to {zone:1454}, {zone:1456} and the Darkspear Trolls. While you level, do the {faction:68}'s quests within 5 levels of them: Tirisfal at 1 to 12, Silverpine at 10 to 20, {area:287} and {area:272} at 20 to 33. The Legacy perk Diplomat adds up to 10%. Rewards: at Honored the {faction:68}'s merchants sell to you for 10% less (the Classic rule), the horse vendor included; at Exalted other races can buy the skeletal horses: 20 gold for a level 40 horse, 200 gold for a level 60 warhorse, once you have mount training. {object:1661} has no tabard or other reward."] = "{faction:68}声望来自任务和布料。布料军需官{npc:14729}站在{object:36082}的裁缝旁边。他先收四次一次性的60块布料捐赠（各150点），然后是{quest:7819}，20块{item:14047}换50点，想交多少次都行。你在{faction:68}每赚1点，{zone:1454}、{zone:1456}和暗矛巨魔也会各得四分之一。升级途中，在任务等级与你相差5级以内时做{faction:68}的任务：提瑞斯法1到12级，银松森林10到20级，{area:287}和{area:272}20到33级。传承特长“外交家”最多加10%。奖励：尊敬时{faction:68}的商人对你降价10%（经典旧世规则），包括卖马商人；崇拜后其他种族也能买骸骨军马：40级马20金，60级战马200金，前提是你已学骑术。{object:1661}没有战袍或其他奖励。",
	["{faction:68}: how it works"] = "{faction:68}：运作方式",
	["{item:14047}: the Scarlet at {area:2266} in the {zone:1423}, the Gordok ogres outside {area:2577} in {zone:1444} and the Twilight camps of {zone:1451} drop it about one kill in three. The Auction House is faster if you have gold."] = "{item:14047}：{zone:1423}{area:2266}的血色十字军、{zone:1444}{area:2577}外的戈多克食人魔和{zone:1451}的暮光营地约三次击杀掉一组。有钱的话拍卖行更快。",
	["{item:14047}: the Scarlet outside {area:2266}"] = "{item:14047}：{area:2266}外的血色十字军",
	["{item:15448}: 7 {item:15447} and the {item:15454}"] = "{item:15448}：7个{item:15447}加{item:15454}",
	["{item:2592}: the Thistlefur furbolgs drop it about one kill in four"] = "{item:2592}：蓟皮熊怪约四次击杀掉一组",
	["{item:2885}, from {npc:1667}"] = "{item:2885}，出自{npc:1667}",
	["{item:4306}: the Syndicate"] = "{item:4306}：辛迪加",
	["{item:4338}: the Jadefire satyrs"] = "{item:4338}：碧火萨特",
	["{item:9324}, from {npc:2707}"] = "{item:9324}，出自{npc:2707}",
	["{npc:10902}: use the {item:12815} at the door"] = "{npc:10902}：在塔门处使用{item:12815}",
	["{npc:11075} guards the cauldron at {area:199}. Click the cauldron after the kill to start {quest:5230}. Mark the four towers of Andorhal with the {item:12815} at their doors."] = "{npc:11075}守着{area:199}的瘟疫锅。击杀后点击瘟疫锅开始{quest:5230}。用{item:12815}在安多哈尔四座塔楼的门口做标记。",
	["{npc:11076} guards the cauldron at the {area:202}."] = "{npc:11076}守着{area:202}的瘟疫锅。",
	["{npc:11077} guards the cauldron at {area:200}."] = "{npc:11077}守着{area:200}的瘟疫锅。",
	["{npc:11078} guards the cauldron at {area:201}."] = "{npc:11078}守着{area:201}的瘟疫锅。",
	["{npc:11878}, the Ranger Lord, keeps his camp on the western edge of the {zone:1423}. His quests are level 58 to 60 and pay in full: 500 {faction:68} reputation."] = "游侠领主{npc:11878}在{zone:1423}西缘扎营。他的任务是58到60级，全额支付：500点{faction:68}声望。",
	["{npc:11878}: 500 {faction:68} reputation. His {area:2279} quests (The {npc:12337}, The Scarlet Oracle, Demetria, Ramstein) need a group."] = "{npc:11878}：500点{faction:68}声望。他的{area:2279}系列任务（{npc:12337}、血色预言者、德米提雅、拉姆斯登）需要组队。",
