	["{npc:11897}, an elite bat, roams the fields north of {area:2260}. {npc:11896} paces a long valley west of {area:2272}."] = "精英蝙蝠{npc:11897}在{area:2260}以北的田野游荡。{npc:11896}在{area:2272}以西的一条长谷里来回走动。",
	["{npc:14729}, +150"] = "{npc:14729}，+150",
	["{npc:14729}: {quest:7813}, +150"] = "{npc:14729}：{quest:7813}，+150",
